local _, ns = ...

if GetLocale() ~= "frFR" then
    return
end

ns.DB:AddTexts("frFR", nil, function() return {
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "Votre propre familier au niveau 10 : trois apprivoisements d'entraînement avec {item:15908} vous enseignent {spell:1515}, puis {spell:5149}.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Au niveau 10, {npc:254084}, un maître des chasseurs de {zone:2521}, peut vous envoyer à {area:16638} avec {quest:94007}. Ce n'est qu'une indication : passez-la si vous êtes déjà à {area:16638}.",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} se tient avec les maîtres près de la porte ouest de {area:16638}, {npc:254411} à côté d'elle.",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "Les rampants Chant-du-vent ne vivent qu'au bord de l'eau : les plus proches trottinent sur le rivage au sud-ouest de {area:16638}, parmi les crabes. Fonctionnement du bâtonnet : ciblez un rampant vivant, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'il vous frappe ; bouger, riposter ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet. En tuer un ne compte pas. Gardez chaque bâtonnet : il retourne à {npc:252389}.",
	["Use the {item:15908} on a living crawler"] = "Utilisez {item:15908} sur un rampant vivant",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Renvoyez d'abord le rampant (clic droit sur le portrait du familier, {spell:2641}). Les coursiers du vent grincheux broutent à {area:16626}, les champs à quelques pas à l'ouest et au sud-ouest de {area:16638}.",
	["Use the {item:15908} on a living galestrider"] = "Utilisez {item:15908} sur un coursier du vent vivant",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Renvoyez le coursier du vent. Les alphas vuldren chassent dans le même {area:16626}, un peu plus au sud.",
	["Use the {item:15908} on a living alpha"] = "Utilisez {item:15908} sur un alpha vivant",
	["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}, à côté d'elle : {spell:5149}",
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Au niveau 10, allez voir {npc:1231}, le maître des chasseurs à la forge de {area:131}. La Voie du chasseur, auprès de {npc:5116} à {zone:1455}, de {npc:11807} au nord-ouest de {area:131} ou de {npc:5515} à {zone:1453}, mène aussi ici, pour un peu d'expérience ; ce n'est qu'une indication. Vous êtes plutôt en Elwynn au niveau 10 ? La suite de {npc:251507} à {area:87} enseigne la même chose.",
	["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "De grands sangliers des rochers (niveau 6-7) fouillent les champs à l'ouest, au sud et au nord-ouest de {area:131} et réapparaissent toutes les 3 minutes. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe. Bouger, riposter, être hors de portée ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet ; si elles sont épuisées, détruisez le bâtonnet, abandonnez la quête et reprenez-la auprès de {npc:1231}. Les sangliers utilisent {spell:6268} à 25 mètres : commencez avec le bâtonnet, pas avec {spell:75}. Gardez chaque bâtonnet : il retourne à {npc:1231}.",
	["Use the {item:15908} on a living boar"] = "Utilisez {item:15908} sur un sanglier vivant",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "Renvoyez d'abord le sanglier (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des léopards des neiges (niveau 7-8) rôdent sur les pentes au sud-est de {area:131}, d'autres au nord-ouest et à l'ouest ; les jeunes léopards des neiges, plus petits, ne comptent pas.",
	["Use the {item:15908} on a living leopard"] = "Utilisez {item:15908} sur un léopard vivant",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "Renvoyez le léopard. Des ours Griffe-de-glace (niveau 7-8) parcourent les collines autour de {area:131}, beaucoup au sud-est et d'autres au nord-ouest vers {area:77} ; leur {spell:3130} frappe fort, commencez donc avec toute votre vie.",
	["Use the {item:15908} on a living bear"] = "Utilisez {item:15908} sur un ours vivant",
	["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "{npc:10090}, le maître des familiers, se tient dans {object:32390}, à {object:32359} de {zone:1455}, près des maîtres des chasseurs.",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Au niveau 10, allez voir {npc:3601}, le maître des chasseurs à {area:186}. La Voie du chasseur, auprès de {npc:3596} à {area:256}, de {npc:4146} à {zone:1457}, de {npc:5515} à {zone:1453}, de {npc:5116} à {zone:1455} ou de {npc:1231} à {area:131}, mène aussi ici, pour un peu d'expérience ; ce n'est qu'une indication. Vous êtes plutôt en Elwynn au niveau 10 ? La suite de {npc:251507} à {area:87} enseigne la même chose.",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "Des rôdeuses Tisse-bois (niveau 5-6) rampent dans les bois juste au nord-est, au sud-ouest et à l'est de {area:186}. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe ; bouger, l'attaquer ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet (plus de charges : détruisez le bâtonnet, abandonnez la quête, reprenez-la). Leur {spell:1265843} vous immobilise mais n'interrompt pas la canalisation si vous ne bougez pas. Gardez chaque bâtonnet : il retourne à {npc:3601}.",
	["Use the {item:15908} on a living spider"] = "Utilisez {item:15908} sur une araignée vivante",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "Renvoyez d'abord l'araignée (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des traqueurs sabres-de-nuit (niveau 7-8) se couchent sur le flanc de colline au sud de {area:259}, au sud de {area:186} ; les simples sabres-de-nuit près du village ne comptent pas.",
	["Use the {item:15908} on a living stalker"] = "Utilisez {item:15908} sur un traqueur vivant",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "Renvoyez le félin. Des hurleurs strigides (niveau 7-8), des chouettes, se perchent dans les bois au sud, au sud-ouest et à l'ouest de {area:186}.",
	["Use the {item:15908} on a living owl"] = "Utilisez {item:15908} sur une chouette vivante",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "Prenez la route vers l'ouest depuis {area:186} jusqu'à {zone:1457}. {npc:4146} se tient dans {area:1658} avec les maîtres des chasseurs ; Silvaria, la maîtresse des familiers, est en haut de la rampe à côté d'elle.",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "Au niveau 10, allez voir {npc:251507}, la maîtresse des chasseurs qui se tient avec les autres maîtres près de l'auberge de la Fierté du lion à {area:87} ; {npc:258930}, la maîtresse des familiers, est à côté d'elle. Célestes : ceci est pour qui a quitté {zone:2521} sans apprivoiser ; la quête enseigne la même chose.",
	["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "Des sangliers Peau-de-roche (niveau 7-8) broutent en trois hardes au sud et au sud-est de {area:87}, vers {area:64}. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe. Bouger, riposter, un soin de quelqu'un d'autre ou quelqu'un d'autre qui frappe la bête l'interrompt et coûte l'une des rares charges du bâtonnet ; si elles sont épuisées, détruisez le bâtonnet, abandonnez la quête et reprenez-la. Les sangliers utilisent {spell:6268} : commencez avec le bâtonnet, pas avec {spell:75}. Tuer un sanglier ne compte pas. Gardez chaque bâtonnet : il retourne à Josephine. Un nain ou un elfe de la nuit qui a pris le bâtonnet de Josephine plutôt que celui de son maître d'origine est guidé à travers {area:87} à partir d'ici.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "Renvoyez d'abord le sanglier (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des loups gris des forêts (niveau 7-8) courent dans les bois à l'est de {area:87}, à l'est de {area:18}.",
	["Use the {item:15908} on a living wolf"] = "Utilisez {item:15908} sur un loup vivant",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "Renvoyez le loup. De jeunes ours des forêts (niveau 8-9) parcourent les bois juste au sud de {area:87}, d'autres au sud-ouest et au sud-est de la ville.",
	["Your first pet"] = "Votre premier familier",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} fonctionne comme le bâtonnet : une bête de votre niveau ou moins, une canalisation pendant laquelle il ne faut pas bouger, la bête vous frappant tout du long. Un familier garde le niveau auquel vous l'apprivoisez et monte de niveau avec vous ; il ne peut jamais dépasser votre niveau, apprivoisez-en donc un proche du vôtre. Chaque famille a sa propre capacité sur Forever (la Charge d'un sanglier, par exemple). Pour monter en niveau, un félin frappe le plus fort (Griffe et {spell:17253}) et un sanglier encaisse davantage.",
	["Tame a beast of your level to keep"] = "Apprivoisez une bête de votre niveau à garder",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "Près de {area:87}, il n'y a pas de félins : des rôdeurs (loups, niveau 9-10) parcourent l'est d'Elwynn, des groins longs (sangliers, 10-11) son extrême sud-ouest près de la frontière de {zone:1436} ; aux niveaux 12-13, de jeunes broche-tripes (sangliers) broutent dans les champs du nord de {zone:1436}.",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "Près de {area:131} : des léopards des neiges (félins, niveau 7-8) rôdent partout à {zone:1426}, des sangliers des rochers balafrés (9-10) à l'est vers {zone:1432} ; aux niveaux 10-11, des sangliers des montagnes parcourent l'ouest de {zone:1432}.",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "Près de {area:186} : de vieux sabres-de-nuit (félins, niveau 8-9) et des sabres-de-nuit farouches (félins, 10-11) rôdent dans les bois du nord-ouest de {zone:1438}.",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "Près de {area:16638} : les alphas vuldren (niveau 10), la bête de votre dernier apprivoisement d'entraînement, chassent à {area:16626} ; les matriarches criardes (raptors, niveau 9) nichent juste à l'ouest de {area:16638} ; des urseras Ombre-bourrasque (ours, 10-11) parcourent le nord de {zone:2521}.",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584} : ouvrez votre grimoire, lancez {spell:1584} et cliquez sur une nourriture que mange la famille de votre familier (son infobulle les liste : les félins mangent viande et poisson, les sangliers presque tout). La viande crue ramassée sur les bêtes compte. Pour en acheter : Toddrick le boucher à {area:87}, Jaeana à {zone:1457} et les aubergistes de {zone:2521} vendent de la viande ; les aubergistes de {area:131} et de {area:186} vendent du pain. Une nourriture proche du niveau du familier le rend le plus heureux ; une nourriture bien plus basse donne environ moitié moins. Impossible de nourrir en combat.",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Bonheur : le visage sur le cadre du familier. Un familier malheureux fait trois quarts de ses dégâts, un familier heureux un quart de plus. Le bonheur baisse lentement, plus vite quand le familier meurt ; un familier laissé malheureux trop longtemps peut s'enfuir.",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "La loyauté grandit avec le temps et les victimes. Chaque rang de loyauté augmente les points de dressage que vous dépensez dans {spell:5149} (niveau du familier multiplié par le rang de loyauté moins un).",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149} (grimoire, onglet Général) enseigne à votre familier actuel les capacités que vous connaissez. Pour apprendre une nouvelle capacité ou un nouveau rang : laissez votre familier chez un maître des écuries (Erma à {area:87}, {npc:9980} à {area:131}, Seriadne à {area:186}, {npc:265756} à {zone:2521}), apprivoisez une bête qui l'a (l'onglet du grimoire du familier montre ce qu'elle connaît), utilisez la capacité en combat jusqu'à ce que le jeu indique que vous l'avez apprise, puis reprenez votre familier et enseignez-la-lui avec {spell:5149}. Un familier a au plus quatre capacités actives.",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "Les maîtres des familiers vendent les rangs de {spell:1853} et les résistances. Alliance : {npc:258930} à {area:87}, {npc:2879} près des maîtres des chasseurs dans {object:28027} de {zone:1453}, {npc:2878} à {area:131}, {npc:10090} dans {object:32390} de {zone:1455}, Keldas à {area:186}, Silvaria dans l'Enclave cénarienne de {zone:1457}, {npc:254411} à {area:16638}.",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}, {spell:2641} et {spell:982} sont maintenant dans votre grimoire ; {spell:136} vient de votre maître au niveau 12. Un familier mort a besoin de {spell:982} ; un familier qui s'éloigne de plus d'environ 100 mètres est renvoyé et revient avec {spell:883}.",
	["A robe or a blouse for Alliance mages in their late 20s."] = "Une robe ou une blouse pour les mages de l'Alliance vers la fin de la vingtaine.",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497} se tient au sommet du Sanctum des sorciers, la tour violette de {object:2101} ; le portail près du haut de la rampe en spirale vous mène à elle.",
	["{npc:5694} (Skyborne)"] = "{npc:5694} (Célestes)",
	["You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:5694} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {npc:5694}, the pointer quest; it is only a pointer and you can skip it.)"] = "Pas besoin de lettre : au niveau 26, montez dans le Sanctum des sorciers, la tour violette de {object:2101} de {zone:1453}. {npc:5694} attend sur la passerelle en spirale, juste après la porte de la salle du portail près du sommet, et a la quête pour vous. ({npc:5497} peut aussi vous proposer {npc:5694}, la quête d'indication ; ce n'est qu'une indication et vous pouvez la passer.)",
	["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939} attend sur la passerelle en spirale du Sanctum des sorciers, juste après la porte de la salle du portail en descendant depuis les maîtres.",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "Partez vers l'est à travers {zone:1429} jusqu'aux Carmines, ou volez jusqu'à {area:69}. {area:96} se dresse seule à l'est de la zone. Montez tout en haut (pas l'étage en dessous) : le traité est le livre qui dépasse de l'étagère là où arrive l'escalier. Deux chiens gnolls et un gnoll lanceur de sorts gardent l'étagère ; le {spell:2691} des chiens interrompt le clic, combattez-les donc dans l'escalier hors de leur vue. Morganth (élite de niveau 26) se tient de l'autre côté du dernier étage : vous n'avez pas besoin de lui, restez sur le bord gauche de la rampe pour qu'il ne bouge pas. Le livre revient deux secondes après qu'on le prend. Si vous mourez, votre fantôme peut monter et revenir à la vie à côté.",
	["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "{area:492}, dans l'ouest de {zone:1431} : les six recluses charognardes (niveau 25-26, vertes, {spell:3609}) arpentent les tombes, la statue centrale et la berge, et chacune lâche une soie ; elles reviennent au bout de 5 minutes. Les jeunes veuves noires (24-25) sur les pentes à l'est du cimetière en lâchent environ une fois sur six, mêlez-les donc en attendant. {npc:522}, un squelette élite de niveau 35, arpente le cimetière : faites attention à lui.",
	["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309} travaille à {object:23296} dans {object:2101}. La robe donne intelligence, endurance et esprit ; la blouse plus d'intelligence et d'endurance mais pas d'esprit.",
	["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328} est le maître des mages de {area:87}, à l'étage de l'auberge de la Fierté du lion.",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:5497} se tient au sommet du Sanctum des sorciers, la tour violette de {object:2101} : montez la rampe en spirale et prenez le portail près du sommet. {item:7247} et {item:7308} sont sur la table derrière elle (tous deux reviennent 5 minutes après qu'on les prend). Vous les rendez tous les deux à la fin, gardez-les donc.",
	["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169} est la taverne de {object:2101}. Lisez {item:7308} à l'intérieur pour faire apparaître les rejetons de faille invisibles (niveau 16-17) : à la cave il en fait venir un, sur le balcon ou dans la cuisine deux, dans la salle principale ou près de la porte trois ; lisez-la donc en bas. Ils frappent fort et se libèrent vite de {spell:122}. Mettez-en un à terre : il ne meurt pas mais reste étourdi avec une spirale au-dessus de la tête ; utilisez {item:7247} sur lui pendant qu'il est étourdi, puis cliquez sur {item:7292} qu'il laisse au sol (cliquer avant qu'il apparaisse gaspille une charge). Il en faut trois, et l'incantation ne marche qu'une fois toutes les 5 minutes (se déconnecter ne la réinitialise pas) : prévoyez trois tours.",
	["{npc:6492}, down to the stun"] = "{npc:6492}, jusqu'à l'étourdissement",
	["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}, sur {npc:6492} étourdi",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "N'importe quel humanoïde lâche {item:2589}, et les rats des tunnels de {area:149} en lâchent pendant que vous ramassez les gemmes ; l'hôtel des ventes de {object:2096} en vend. Vous en rendez dix.",
	["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "Prenez {area:2257} jusqu'à {zone:1455}, puis la route vers l'est par le tunnel de la porte Sud jusqu'à {zone:1432}. {area:149} est à l'extrémité nord du loch, au nord de {area:144} ; des kobolds rats des tunnels le tiennent. Les gemmes ne viennent que des hautes piles de {object:271} (le curseur montre un engrenage dessus ; les caisses seules ne contiennent rien) : chaque caisse en donne une, il y en a quatorze et elles reviennent au bout de 3 à 5 minutes. Il vous faudra peut-être aller jusqu'à la salle du fond pour en avoir six. Les mêmes caisses servent à la quête des Pattes sales des nains.",
	["Ley or {item:9514} or Orb (Alliance)"] = "Bâton ou {item:9514} ou orbe (Alliance)",
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "Un bâton ou un orbe en main gauche au niveau 10, auprès du maître des mages de votre ville d'origine ; les Célestes y ajoutent une baguette.",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "Au niveau 10, {npc:252373}, le maître des mages de {area:16638}, vous envoie à {npc:256507}, le marchand de bâtons à quelques pas dans la même ville.",
	["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "La branche gît au sol parmi les formations de Pierre-vent, le sanctuaire du vent sur la butte à l'ouest du camp de Fillion, au sud de {area:16636}. Elle ne scintille pas, regardez donc le sol près des pierres ; il y a deux emplacements possibles.",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861} (les étapes suivantes) vous attend auprès de {npc:5497} à {zone:1453}, vers le niveau 15.",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {npc:5144}'s quest in {zone:1455}; you get one staff-or-orb quest."] = "Au niveau 10, {npc:328}, le maître des mages de {area:87}, à l'étage de l'auberge de la Fierté du lion, vous envoie à {npc:5497} à {zone:1453}. La prendre ferme la quête de {npc:5144} à {zone:1455} ; vous n'avez qu'une quête de bâton ou d'orbe.",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "Au niveau 10, {npc:1228}, le maître des mages de {area:131} dans {area:2102}, vous envoie à {npc:5144} à {zone:1455}. La prendre ferme {quest:1861} de {npc:5497} ; vous n'avez qu'une quête de bâton ou d'orbe. (Un gnome qui a pris la quête de {npc:328} à {area:87} suit plutôt les étapes de {quest:1861} ; un humain qui a pris celle-ci, les étapes du Gizmoniteur.)",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Suivez la route au nord jusqu'à {zone:1453} puis à l'ouest jusqu'à {object:2101}. {npc:5497} se tient au sommet du Sanctum des sorciers, la haute tour violette : montez la rampe en spirale et entrez dans le portail près du sommet, qui vous dépose à côté d'elle. Elle vous remet {item:7207}. Les mages célestes prennent {quest:1861} auprès d'elle en arrivant pour la première fois à {zone:1453}, vers le niveau 15.",
	["The {quest:1861} waterfall"] = "La cascade de {quest:1861}",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "Quittez {zone:1453} par la grande porte et partez au sud-ouest jusqu'à la cascade qui alimente {quest:1861}. Avancez dans l'eau sous la chute jusqu'au rocher derrière et utilisez-y {item:7207} (5 secondes d'incantation) ; ailleurs, ça échoue. Des lanceurs de sorts défias de niveau 10 se tiennent sur les rochers de part et d'autre des chutes et tirent à distance : attirez-les un par un ou remplissez la flasque depuis l'eau.",
	["{item:7207}, under the falls"] = "{item:7207}, sous les chutes",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Remontez le Sanctum des sorciers et repassez le portail. L'orbe se tient en main gauche avec une arme à une main ; le bâton se tient à deux mains.",
	["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497} : {item:7508} ou {item:9513}",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144} entraîne les mages dans {object:32362}, au fond de {zone:1455} après {object:32386}.",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "Prenez la route vers l'ouest jusqu'à {area:133}. Juste au nord de son entrée se dressent deux huttes ; la boîte à outils est dans la plus haute, à l'est, celle avec l'ascenseur : une petite boîte grise au rez-de-chaussée, à moitié sous la table à côté de l'ascenseur. Des gnomes lépreux (niveau 8) gardent les huttes : attirez-les un par un. Il n'y a qu'une boîte à outils et elle met 15 minutes à revenir après qu'on l'a ouverte ; si elle n'y est plus, attendez tout près.",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144} : {item:7507} ou {item:9514}",
	["{npc:256507}'s wand (optional)"] = "La baguette de {npc:256507} (facultative)",
	["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "La quête de {npc:256507} est aussi ouverte aux mages humains et gnomes, si vous passez un jour à {area:16638} sur {zone:2521}, chez les Célestes : {npc:252373}, le maître des mages de la ville, vous envoie à {npc:256507} juste à côté, qui veut {item:262668} ramassée au sol près des formations de Pierre-vent au sud de {area:16636}, pour {item:263430}. Elle ne ferme pas le bâton ni l'orbe.",
	["Teleports and Portals (Alliance)"] = "Téléportations et portails (Alliance)",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "Vos téléportations de ville aux niveaux 20 et 30 et les portails de groupe aux niveaux 40 et 50, auprès du maître des portails de chaque ville.",
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "Au niveau 20, allez au Sanctum des sorciers, la tour violette de {object:2101} de {zone:1453}. {npc:2485}, la maîtresse des portails, se tient tout en haut : montez la rampe en spirale et prenez le portail près du sommet. Elle enseigne {spell:3561} pour 20 pièces d'argent. Chaque téléportation consomme {item:17031} (10 pièces d'argent chez n'importe quel vendeur de composants ; {npc:1308} en vend au pied de la tour) : ayez-en quelques-unes sur vous.",
	["{item:17031}, 10s each"] = "{item:17031}, 10 pa pièce",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "Prenez {area:2257} depuis {object:28027} de {zone:1453} jusqu'à {zone:1455}. {npc:2489}, le maître des portails, se tient avec les maîtres des mages dans {object:32362} au fond de la ville : {spell:3562}, 20 pièces d'argent.",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "Au niveau 30. Prenez le bateau de {area:17203} à {area:442} à {zone:1439}, puis le bateau jusqu'à {area:702} et le portail rose qui monte à {zone:1457}. {npc:4165}, le maître des portails, enseigne {spell:3565} pour 80 pièces d'argent.",
	["Portals to {zone:1453} and {zone:1455}"] = "Portails vers {zone:1453} et {zone:1455}",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "Au niveau 40, les maîtres des portails enseignent les portails : une porte que tout votre groupe peut franchir, pour 1 pièce d'or et 50 d'argent chacun. Chaque portail consomme {item:17032} (20 pièces d'argent chez n'importe quel vendeur de composants). {npc:2485} a {spell:10059} au sommet du Sanctum des sorciers ; puis le tram jusqu'à {npc:2489} dans {object:32362} de {zone:1455} pour {spell:11416}.",
	["{item:17032}, 20s each"] = "{item:17032}, 20 pa pièce",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "Au niveau 50, {npc:4165} à {zone:1457} enseigne le dernier, {spell:11419}, pour 3 pièces d'or et 20 d'argent. Utilisez votre {spell:3565} pour y aller.",
	["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "Une cape rare au niveau 30, tirée de l'ancienne histoire de {spell:407778} ; pour l'instant, seuls les paladins de l'Alliance peuvent la terminer.",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "Montez au sommet de {area:444} dans le nord de {zone:1439}. Les fanatiques du Sombre brin autour sont faciles (niveau 16-17), mais quatre invocateurs du Vide du Sombre brin (niveau 28-29) se tiennent dans la tour sur le chemin de l'orbe : chacun appelle un marcheur du Vide et lance {spell:686} à distance. Aux niveaux 22-25, venez avec un ou deux amis, attirez-les un par un et placez-vous derrière un mur pour qu'ils viennent à vous. Ramassez l'orbe étrange au sommet : elle vous donne l'orbe d'Althalaxx ; faites un clic droit dessus pour commencer la quête. Gardez l'orbe dans vos sacs jusqu'à {object:409311} : trois quêtes suivantes en ont besoin.",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663} se tient à {area:413}, dans l'ouest de {zone:1440}, au sud de la route de {zone:1439}. Il vous envoie à {zone:1453} avec l'orbe.",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492} se tient dans la cathédrale de la Lumière ; elle vous envoie demander un second avis à un démoniste.",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "{npc:5495}, la maîtresse des démonistes, est dans le sanctuaire des démonistes de {object:2101}, dans la cave de {object:2164}. Elle veut 14 {item:209778} pour lire l'orbe.",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "Les invocateurs, champions et pisteurs Rochenoire (niveau 22-25, non élites) campent au nord-ouest des Carmines et lâchent {item:209778} ; il vous en faut 14. Deux lanceurs d'ombre Rochenoire élites (22-23) se tiennent à l'entrée de la grotte à l'extrémité est du camp : contournez-les. Les camps Rochenoire à l'est de {area:69} lâchent aussi le sel, mais leurs lanceurs d'ombre, sentinelles et chasseurs sont élites (niveau 21-24), tout comme {npc:334} (26) : restez au nord-ouest.",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435} se trouve au sud-est de {zone:1440}, à l'est de {area:431} (un camp de la Horde : contournez-le). Les flagellants de Mannoroc, les infernaux brûlants, les gangregardes et les molosses de la Légion (niveau 29-30, non élites) lâchent les grains de Mannoroth ; il vous en faut 12. Sous le niveau 27 environ, ils sont durs seul : venez avec un second joueur ou plus tard. Les gangregardes vous renversent, les flagellants lancent {spell:686} et {spell:348}, les infernaux gardent un bouclier de feu. Ils réapparaissent en cinq minutes.",
	["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "{object:409311} se dresse à l'extrémité est de {area:435}. Rendez les grains à la lance avec l'orbe d'Althalaxx dans vos sacs : l'orbe se brise, et {object:409315} à côté commence la dernière quête.",
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Retour auprès de {npc:3663} à {area:413}, dans l'ouest de {zone:1440}, à travers toute la zone.",
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "Une pierre à usage unique qui vous rend bien plus fort contre les morts-vivants pendant 10 minutes ; l'ancien choix d'objet a peut-être disparu sur Forever.",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "Au niveau 50, {npc:928}, le maître des paladins de la cathédrale de la Lumière, vous envoie à {area:3197} dans {zone:1422}. {npc:5149} à {zone:1455} donne la même quête.",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "Au niveau 50, {npc:5149}, le maître des paladins de {object:32362}, vous envoie à {area:3197} dans {zone:1422}. {npc:928} à {zone:1453} donne la même quête.",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197} est le camp de l'Alliance à l'extrémité sud de {zone:1422}, au nord des contreforts d'Alterac. {npc:10838} le commande ; {npc:10840} se tient dans le même camp.",
	["The Scourge drop no Scourgestones unless you wear an {item:12846}. {npc:10840} gives you one through her quest, {item:12846}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "Le Fléau ne lâche pas de pierres du Fléau si vous ne portez pas {item:12846}. {npc:10840} vous en donne une par sa quête, {item:12846}, que vous rendez aussitôt (si vous en avez déjà une de {area:2268}, portez-la). Équipez-la dans un emplacement de bijou : elle apparaît comme une amélioration qui ne s'épuise jamais. Gardez-la jusqu'à avoir 20 pierres.",
	["{item:12846}: equip it"] = "{item:12846} : équipez-la",
	["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "Tuez le Fléau de {zone:1422} avec la commission sur vous : squelettes, goules et cultistes (niveau 50-58) lâchent {item:12840} environ deux fois sur cinq. {area:197}, juste à l'est de {area:3197} autour de {area:196}, est l'endroit le plus proche. Évitez les golems de chair qui patrouillent dans les champs ; les gardiens squelettes lancent {spell:120} et {spell:1449} au contact, les invocateurs sombres fuient chercher de l'aide quand leur vie est basse.",
	["{item:12840} x20"] = "{item:12840} x20",
	["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854} monte la garde à {area:196} sur {area:197}, à l'est du camp. Il transforme vos 20 pierres en un {item:20612} : gardez-le.",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "Retour à {area:3197}. Ashlam a besoin du vaudou des trolls de {area:1417} pour la pierre.",
	["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}, {area:1417}, se trouve dans {area:74}, dans l'est de {zone:1435} : montez l'escalier de la ruine, plongez dans la salle inondée et suivez l'escalier jusqu'au portail. C'est un donjon pour un groupe de cinq vers les niveaux 50-55. Six mini-chefs trolls élites (niveau 51-52) se tiennent sur les balcons autour de la grande salle ronde du temple, chacun derrière un groupe d'élites sur son passage latéral. Chacun lâche sa plume à chaque fois : Gasher et {npc:5716} l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte ; il vous les faut toutes les six. Hukku appelle des gardiens et lance des salves de traits de l'ombre, Mijan soigne : tuez-les en premier.",
	["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2 : Gasher, {npc:5716}",
	["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2 : Hukku, Mijan",
	["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2 : Zolo, Loro",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "Retour auprès d'Ashlam à {area:3197} : il forge {item:20620}. Regardez la fenêtre de récompense avant de rendre : Classic proposait aussi {item:20505}, {item:20504} ou {item:20512}, et les notes de Forever disent que ce choix a peut-être disparu. Utilisez la pierre avant un combat contre des morts-vivants ({area:2279}, {area:2057}) : elle dure dix minutes et disparaît après un usage.",
	["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "{spell:7328} au niveau 12, la résurrection du paladin : une suite facile à travers votre capitale et sa zone d'origine.",
	["The summons (Human)"] = "La convocation (humain)",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "Au niveau 12, {npc:927}, le maître des paladins de {area:87}, vous envoie auprès de {npc:6171} dans la cathédrale de la Lumière de {zone:1453}. La course est facultative, un peu d'expérience : {npc:5149} à {zone:1455} donne la même (en prendre une ferme l'autre), et {npc:6171} commence la suite sans elle.",
	["The summons (Dwarf)"] = "La convocation (nain)",
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "Au niveau 12, {npc:5149}, le maître des paladins dans {object:32362} de {zone:1455}, vous envoie à l'étage auprès de {npc:6179}. La course est facultative, un peu d'expérience : {npc:1232} à {area:131} et {npc:928} à {zone:1453} donnent la même (en prendre une ferme les autres), et {npc:6179} commence la suite sans elle.",
	["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Il vous remet {item:6775} : faites un clic droit dessus dans vos sacs pour commencer la quête suivante. Si le livre indique que la quête est déjà faite, détruisez-le et demandez un nouvel exemplaire à {npc:6171}. Apportez 10 {item:2589} pour l'étape suivante si vous en avez.",
	["Right-click the {item:6775}"] = "Clic droit sur {item:6775}",
	["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174} se tient à un angle au milieu de {object:2096}, devant une boutique de fournitures. Elle veut 10 {item:2589} : les humanoïdes en lâchent (les gnolls Rivepatte de {zone:1436} environ une fois sur deux, les Défias et les kobolds un peu moins), ou achetez-en à l'hôtel des ventes à quelques pas dans {object:2096}.",
	["{item:2589} x10"] = "{item:2589} x10",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Retour à la cathédrale. {npc:6171} vous donne {item:6866} ; {npc:6173} gît blessé près de l'autel de la même salle. Gardez le symbole : il vous servira sur {npc:6172}. Si vous le perdez, {npc:6171} vous en donne un autre ({item:6866}).",
	["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172} gît mort à {area:56}, l'île de {area:86} dans l'est d'Elwynn, au sommet de l'un des tertres autour du cercle de pierres. Ciblez son corps et utilisez {item:6866} pour le relever, puis parlez-lui. Si un autre paladin vient de le relever, son corps revient en trois minutes environ. Les sorciers renégats défias de l'île (niveau 9-10) lancent {spell:116} de loin : ils sont espacés, attirez-les donc un par un.",
	["{item:6866} on {npc:6172}'s body"] = "{item:6866} sur le corps de {npc:6172}",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "Les sorciers renégats défias autour de la grande tablette de pierre à l'est de {npc:6172} portent {item:6846} : environ une victime sur deux le lâche, mais certains joueurs ont besoin de beaucoup de victimes. Ils réapparaissent en trois minutes.",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Retour à la cathédrale de la Lumière : {npc:6173} prend le texte, {npc:6171} vous enseigne {spell:7328}.",
	["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}, à l'étage de {object:32386}",
	["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179} se tient à l'étage de {object:32386}, dans {object:32362} : prenez la rampe au fond de la salle. Elle vous remet {item:6916} : faites un clic droit dessus dans vos sacs pour commencer la quête suivante. Si le livre indique que la quête est déjà faite, détruisez-le et demandez un nouvel exemplaire à {npc:6179}. Apportez 10 {item:2589} pour l'étape suivante si vous en avez.",
	["Right-click the {item:6916}"] = "Clic droit sur {item:6916}",
	["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175} arpente l'anneau extérieur de la Place commune, après la grande porte, la banque et l'hôtel des ventes. Il veut 10 {item:2589} : les humanoïdes en lâchent ({npc:1245} à {area:131} à chaque fois, les embusqués Sombrefer environ deux fois sur cinq), ou achetez-en à l'hôtel des ventes sur son anneau.",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Retour à l'étage de {object:32386}. {npc:6179} vous donne {item:6866} ; son mari {npc:6178} se repose au même étage. Gardez le symbole : il vous servira sur {npc:6177}. Si vous le perdez, {npc:6179} vous en donne un autre ({item:6866}).",
	["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177} gît mort à {zone:1426}, pas à {zone:1432} : à l'est après {area:131}, au nord-est du domaine d'Ironband, sur la plus petite de trois petites collines entre {area:212} et le camp {object:147516}. Ciblez son corps et utilisez {item:6866} pour le relever, puis parlez-lui. Si un autre paladin vient de le relever, son corps revient en trois minutes environ.",
	["{item:6866} on {npc:6177}'s body"] = "{item:6866} sur le corps de {npc:6177}",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "Les espions Sombrefer (niveau 9-11, douze en tout) se faufilent autour de la petite maison en contrebas du lac, juste au sud de Narm ; vous les voyez depuis sa colline. Environ une victime sur deux lâche {item:6847}. Ils fuient chercher de l'aide quand leur vie est basse : achevez-les ou reculez. Ils réapparaissent en trois minutes.",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Remontez à {object:32386} : {npc:6178} prend le texte, {npc:6179} vous enseigne {spell:7328}.",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "La masse à deux mains rare du paladin de l'Alliance pour la vingtaine, avec un bouclier et {spell:5502} en chemin.",
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "Au niveau 20, {npc:6179}, à l'étage de {object:32386} dans {object:32362}, vous donne {item:6776}. Faites un clic droit dessus : il vous envoie auprès de {npc:6171} dans la cathédrale de la Lumière de {zone:1453}. Prenez {area:2257} de {zone:1455} à {zone:1453}.",
	["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Les humains reçoivent {item:6776} de lui. Faites un clic droit sur le livre pour commencer sa quête et rendez-la-lui aussitôt.",
	["Right-click the {item:6776}"] = "Clic droit sur {item:6776}",
	["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "La ferme de {npc:6182} se trouve sur la côte sud-ouest de {zone:1436}, au sud de {area:20} : prenez le chemin qui descend au sud à côté de la sortie arrière de {area:1581}. Quand vous prenez sa quête, elle marche de son verger à la maison et trois vagues de pillards défias (niveau 17-18) attaquent : trois, puis quatre, puis cinq. Combattez près d'elle pour qu'ils ne l'encerclent pas, et soignez-la quand sa vie baisse. Vous avez le temps de manger et boire entre les vagues, et elle se soigne entièrement. Si vous ou {npc:6182} mourez, la quête échoue : abandonnez-la et reprenez-la auprès d'elle (elle revient cinq minutes après sa mort). Les joueurs la trouvent difficile seuls avant le niveau 24 environ.",
	["Protect {npc:6182}: three waves"] = "Protégez {npc:6182} : trois vagues",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Retour à la cathédrale de la Lumière : {npc:6171} vous donne le bouclier {item:9607} et vous enseigne {spell:5502}.",
	["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181} travaille devant les portes de {zone:1455}, pas à l'intérieur. Il vous donne {item:6996} : quatre pièces, dans n'importe quel ordre. Gardez les notes.",
	["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241} est au rez-de-chaussée de la maison de {area:144} qui a un marchand de couture devant. Sa quête ne s'ouvre qu'une fois celle de Jordan en votre possession.",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "La caisse de minerai se trouve dehors, au milieu du camp des ogres Mo'grosh dans le nord-est de {zone:1432}, à côté d'un grand arbre et d'un chariot cassé, entre les grottes. Le camp abrite une quinzaine d'ogres Mo'grosh élites (niveau 18-19), qui vous renversent et reviennent au bout de cinq minutes : un groupe est conseillé ; aux niveaux 20-22, il faut un groupe d'environ trois. La caisse revient deux secondes après chaque ramassage, chaque paladin du groupe en a donc une.",
	["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241} transforme le minerai en {item:6993}, la pièce que veut Jordan.",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} est un donjon pour cinq sous {area:20} ; le portail de l'instance est au fond de la mine de {area:20}. Les sculpteurs sur bois gobelins (élites, niveau 18-19) de la salle du mât avec Sneed lâchent le bois à chaque fois.",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236} est un donjon pour un groupe de cinq entre le début et le milieu de la vingtaine, dans le sud de {zone:1421}, en terre de la Horde : un long voyage pour l'Alliance, par {zone:1437}, Arathi et {area:287}. Le marteau est posé sur une caisse face aux chevaux dans les écuries, au début du donjon, au fond de la cour avant la rampe ; il revient cinq minutes après qu'on l'a pris.",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649} est à {area:442}. Prenez sa quête avant de chasser les nagas : la gemme de Kor ne tombe jamais sans elle.",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Les nagas de Brassenoire des passages inondés autour de l'entrée de {area:2797}, sur la côte nord-ouest de {zone:1440}, lâchent {item:6995} : prêtresses des marées (niveau 20-21), oracles (21-22) et sorcières des mers (23-24), une fois sur deux. Inutile d'entrer dans l'instance. Tous sont élites : un groupe est conseillé ; les joueurs les battent seuls un par un, difficilement. Ils se soignent, fuient chercher de l'aide quand leur vie est basse, des satyres se tiennent près de certains, et les sorcières des mers lancent {spell:122} au contact. Certains joueurs signalent ne rien obtenir en groupe de raid.",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "Apportez les quatre pièces à {npc:6181} devant {zone:1455}. Acceptez sa dernière quête et attendez à côté de lui pendant qu'il forge la masse à son enclume.",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "Les sorts de prêtre gnome, nouveaux sur Forever : {quest:94817} au niveau 10, {quest:94818} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "Au niveau 10, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455}. {area:131} est sur la route qui monte à la ville.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455}.",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 10 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "Au niveau 10, allez voir {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} (au nord-ouest de la ville), juste à côté de {npc:11406} : elle donne {quest:94817} et la reprend aussitôt. Pas besoin de lettre. {quest:94817} désoriente jusqu'à cinq ennemis autour de vous pendant 3 secondes (tout dégât les réveille), avec 2 minutes de recharge : le temps de reculer et de vous soigner, ou de fuir.",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "Suivez la route qui monte de {area:131} jusqu'à {zone:1455} et {object:32362} : {npc:258785}, dans {object:32386}, prend la lettre et enseigne {quest:94824}.",
	["{quest:94822}: Josetta's letter"] = "{quest:94822} : la lettre de Josetta",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["{quest:94821}: Laurena's letter"] = "{quest:94821} : la lettre de Laurena",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94823} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94825} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94826} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:94818} pour {npc:258785} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "Au niveau 20, {npc:258785}, dans {object:32386}, enseigne {quest:94818} par une quête qu'elle donne et reprend aussitôt. {quest:94818} protège un allié pendant 30 secondes : s'il passe sous 35 % de vie, il reçoit aussitôt un bouclier et un soin sur la durée (cumulable avec {spell:139} et {spell:17}). 5 minutes de recharge.",
	["{quest:94819}: Laurena's letter"] = "{quest:94819} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre de Laurena à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94820} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["The Dwarf priest spells: {quest:5634} at 10, {quest:5641} (new in Forever) at 20. Free, no objectives."] = "Les sorts de prêtre nain : {quest:5634} au niveau 10, {quest:5641} (nouveau sur Forever) au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "Au niveau 10, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet une lettre {quest:5634} pour {npc:11406}. {area:131} est sur la route qui monte à {zone:1455}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455} ({area:2257} depuis {object:28027} de {zone:1453}).",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "Au niveau 10 à {zone:1453}, {npc:11397}, le maître des prêtres du Parc (le quartier des elfes de la nuit, à l'ouest de la ville), vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}. {npc:376}, à la cathédrale, n'en a pas pour les nains.",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Au niveau 10 à {zone:1438}, {npc:3600}, dans le bâtiment au bord nord de {area:186}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}.",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Au niveau 10 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}.",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5634} and takes it back at once. No letter needed. {quest:5634} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "Au niveau 10, allez voir {npc:11406} dans {object:32386}, dans {object:32362} de {zone:1455} (au nord-ouest de la ville) : il donne {quest:5634} et la reprend aussitôt. Pas besoin de lettre. {quest:5634} vous soigne instantanément, ne coûte pas de mana et a une longue recharge : gardez-la pour les urgences.",
	["Follow the road up from {area:131} into {zone:1455} and west to the {object:32362}: {npc:11406} in the {object:32386} takes the letter and teaches {quest:5637}. The letter tells you to head to {zone:1453}, but the one who wants you is Rohan in {zone:1455}."] = "Suivez la route qui monte de {area:131} jusqu'à {zone:1455} puis à l'ouest jusqu'à {object:32362} : {npc:11406}, dans {object:32386}, prend la lettre et enseigne {quest:5637}. La lettre vous dit d'aller à {zone:1453}, mais celui qui vous attend est Rohan, à {zone:1455}.",
	["{quest:5635}: Josetta's letter"] = "{quest:5635} : la lettre de Josetta",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["{quest:5638}: Nara's letter"] = "{quest:5638} : la lettre de Nara",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1438}, the boat from {area:702} to {area:442}, the boat to {area:150} and the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : depuis {zone:1438}, le bateau de {area:702} à {area:442}, le bateau jusqu'à {area:150} et la route vers le nord par {zone:1437} et {zone:1432} (ou le bateau jusqu'à {area:17203} et {area:2257}).",
	["{quest:5640}: Alathea's letter"] = "{quest:5640} : la lettre d'Alathea",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: its text says {zone:1453}, but Rohan is in {zone:1455}. From {zone:1457}, the portal down to {area:702}, the boat to {area:442}, then {area:150} and the road north (or {area:17203} and the {area:2257})."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : son texte indique {zone:1453}, mais Rohan est à {zone:1455}. Depuis {zone:1457}, le portail qui descend à {area:702}, le bateau jusqu'à {area:442}, puis {area:150} et la route vers le nord (ou {area:17203} et {area:2257}).",
	["{quest:5634}: an old letter"] = "{quest:5634} : une ancienne lettre",
	["This letter also goes to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Cette lettre va aussi à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:5641} pour {npc:11406} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "Au niveau 20 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre {quest:5641} pour {npc:11406} à {zone:1455}.",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "Au niveau 20, {npc:11406}, dans {object:32386}, enseigne {quest:5641} par une quête qu'il donne et reprend aussitôt. Forever l'a renommé (anciennement Absence de peur) : {quest:5641} inflige des dégâts à un humanoïde et l'immobilise 2 secondes (instantané, 2 minutes de recharge), et tous les prêtres apprennent maintenant {spell:6346}.",
	["{quest:5645}: Laurena's letter"] = "{quest:5645} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: he teaches {quest:5645}."] = "Remettez la lettre de Laurena à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : il enseigne {quest:5645}.",
	["{quest:5647}: Alathea's letter"] = "{quest:5647} : la lettre d'Alathea",
	["Hand Alathea's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1457}, the boats via {area:702} and {area:442} to {area:150}, then the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Remettez la lettre d'Alathea à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : depuis {zone:1457}, les bateaux par {area:702} et {area:442} jusqu'à {area:150}, puis la route vers le nord par {zone:1437} et {zone:1432} (ou le bateau jusqu'à {area:17203} et {area:2257}).",
	["The Human priest spells: {quest:94773} at 10 (new in Forever), {spell:13896} at 20. Free, no objectives."] = "Les sorts de prêtre humain : {quest:94773} au niveau 10 (nouveau sur Forever), {spell:13896} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "Au niveau 10, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre pour {npc:376}. {area:87} est sur la route du nord vers {zone:1453}, sans détour.",
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "Un prêtre humain à {zone:1438} au niveau 10 : {npc:3600}, dans le bâtiment au bord nord de {area:186}, vous remet une lettre pour {npc:376} à {zone:1453}.",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get Desperate Prayer in Forever: this is their spell instead."] = "Au niveau 10, allez voir {npc:376} à l'autel de la cathédrale de la Lumière, dans {object:2098} de {zone:1453}, et prenez sa quête : elle enseigne {quest:94773} sur place. Pas besoin de lettre ; celle d'un autre maître marche aussi (étapes suivantes). {quest:94773} soigne instantanément un allié sous la moitié de sa vie et dissipe {spell:6788}, pour pouvoir le protéger à nouveau (5 minutes de recharge) ; ne fonctionne pas sur vous-même. Les prêtres humains n'ont pas Prière du désespoir sur Forever : c'est leur sort à la place.",
	["{quest:94774}: Josetta's letter"] = "{quest:94774} : la lettre de Josetta",
	["Hand Josetta's letter to {npc:376} at the altar of the Cathedral of Light: she teaches {quest:94774}."] = "Remettez la lettre de Josetta à {npc:376} à l'autel de la cathédrale de la Lumière : elle enseigne {quest:94774}.",
	["Hand {npc:3600}'s letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1438}: the boat from {area:702} to {area:442}, then the boat to {area:17203}): she teaches {quest:94775}."] = "Remettez la lettre de {npc:3600} à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} (depuis {zone:1438} : le bateau de {area:702} à {area:442}, puis le bateau jusqu'à {area:17203}) : elle enseigne {quest:94775}.",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94776} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94777} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94778} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94779} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "Au niveau 20 à {zone:1455}, {npc:11406}, dans {object:32386} ({object:32362}), vous remet une lettre pour {npc:376} à {zone:1453}. {area:2257} depuis {object:171524} vous y emmène.",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "Au niveau 20 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre pour {npc:376} à {zone:1453}.",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "Au niveau 20, {npc:376}, à l'autel de la cathédrale de la Lumière, enseigne {spell:13896} par une quête qu'elle donne et reprend aussitôt.",
	["{spell:13896}: Rohan's letter"] = "{spell:13896} : la lettre de Rohan",
	["Hand Rohan's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (the {area:2257} from {object:171524} in {zone:1455}): she teaches {spell:13896}."] = "Remettez la lettre de Rohan à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} ({area:2257} depuis {object:171524} à {zone:1455}) : elle enseigne {spell:13896}.",
	["{spell:13896}: Alathea's letter"] = "{spell:13896} : la lettre d'Alathea",
	["Hand Alathea's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1457}: the portal down to {area:702}, the boat to {area:442}, then the boat to {area:17203}): she teaches {spell:13896}."] = "Remettez la lettre d'Alathea à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} (depuis {zone:1457} : le portail qui descend à {area:702}, le bateau jusqu'à {area:442}, puis le bateau jusqu'à {area:17203}) : elle enseigne {spell:13896}.",
	["Priest Robes at 5 (Alliance)"] = "Robes de prêtre au niveau 5 (Alliance)",
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Une robe inhabituelle gratuite au niveau 5 : soignez et fortifiez un garde blessé près de votre première ville.",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:375}, le maître des prêtres dans {area:24}, vous envoie auprès de {npc:377} à {area:87}. Apprenez {spell:613} (rang 2) auprès d'Anetta tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Suivez la route au sud pour sortir de {area:9} jusqu'à {area:87}. {npc:377} est à l'étage de l'auberge de la Fierté du lion.",
	["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (rang 2), si Anetta ne l'a pas encore enseigné",
	["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} est agenouillé près d'un arbre sur la rive du lac à l'est de {area:87}, à l'écart de la route : longez la rive, la minimap ne le montre pas depuis la route. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243}. Le rang 1 de {spell:613} ne compte pas ; faites glisser le rang 2 du grimoire sur votre barre (ou lancez les deux depuis le grimoire si un addon de barres d'action gêne). Il s'en va une fois les deux sorts reçus et revient en 3 minutes environ.",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "De retour à l'étage de l'auberge de la Fierté du lion : Josetta vous donne {item:16605}.",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:837}, le maître des prêtres dans {area:77} à {area:132}, vous envoie auprès de {npc:1226} à {area:131}. Apprenez {spell:613} (rang 2) auprès de lui tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Prenez le tunnel au nord-est pour sortir de {area:132} et suivez la route vers l'est jusqu'à {area:131}. {npc:1226} est dans {area:2102}.",
	["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (rang 2), si {npc:837} ne l'a pas encore enseigné",
	["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} est agenouillé sur une crête entre deux murets juste au sud de {area:131}, de l'autre côté de la route du maître des familiers : si la route commence à descendre, vous l'avez dépassé. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243} ; il parle après chaque sort. Le rang 1 de {spell:613} ne compte pas.",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "De retour dans {area:2102} : {npc:1226} vous donne {item:16605}.",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:3595}, la maîtresse des prêtres au deuxième niveau de {area:256}, le grand arbre de {area:188}, vous envoie auprès de {npc:3600} à {area:186}. Apprenez {spell:613} (rang 2) auprès d'elle tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Quittez {area:188} par la rampe et suivez la route au sud-ouest jusqu'à {area:186}. {npc:3600} est dans le bâtiment au bord nord du village.",
	["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (rang 2), si {npc:3595} ne l'a pas encore enseigné",
	["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} est agenouillée sur les rochers au bord de {area:259}, à environ 100 mètres au sud de {area:186}, sans point d'exclamation au-dessus d'elle. Lancez d'abord {spell:613} (rang 2) sur elle, puis {spell:1243} ; elle court vers le lac une fois les deux sorts reçus et revient en 5 minutes environ. Le rang 1 de {spell:613} ne compte pas.",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "De retour au bord nord de {area:186} : {npc:3600} vous donne {item:16604}.",
	["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "Les sorts de prêtre elfe de la nuit : {spell:10797} au niveau 10, {spell:2651} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Au niveau 10, {npc:3600}, le maître des prêtres dans le bâtiment au bord nord de {area:186}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {area:186} est sur la route de l'ouest vers {zone:1457}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1426}, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 10 à {zone:1453}, {npc:5489}, à l'autel de la cathédrale de la Lumière, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {npc:11397}, au Parc, a la même lettre.",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1455}, {npc:5142}, dans {object:32386} ({object:32362}), vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Au niveau 10, allez voir {npc:11401} sur le balcon supérieur du temple de la Lune, à l'extrémité sud de {zone:1457} : prenez la rampe qui monte du sol du temple ; elle se tient à côté de {npc:7999}. {quest:5627} est donnée et reprise aussitôt et enseigne {spell:10797}. Pas besoin de lettre. Forever a rendu {spell:10797} bien plus puissant, avec 30 secondes de recharge.",
	["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Prenez la route vers l'ouest depuis {area:186} jusqu'à {zone:1457} et montez au balcon supérieur du temple de la Lune, à côté de {npc:7999} : {npc:11401} prend {quest:5629} et enseigne {spell:10797}.",
	["{spell:10797}: Josetta's letter"] = "{spell:10797} : la lettre de Josetta",
	["{quest:5628} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5628} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5630} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5630} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{spell:10797}: Joshua's letter"] = "{spell:10797} : la lettre de Joshua",
	["{quest:5631} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5631} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{spell:10797}: Nara's letter"] = "{spell:10797} : la lettre de Nara",
	["{quest:5632} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5632} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5633} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5633} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}. {npc:11397}, au Parc, a la même lettre.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Au niveau 20 à {zone:1455}, {npc:11406}, dans {object:32386} ({object:32362}), vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}.",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Au niveau 20, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, enseigne {quest:5672} par une quête qu'elle donne et reprend aussitôt. Sur Forever, {quest:5672} divise par deux les chances des attaques de mêlée et à distance de vous toucher pendant 15 secondes ou jusqu'à ce que trois attaques ratent.",
	["{quest:5673}: Laurena's letter"] = "{quest:5673} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Laurena à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5674}: Nara's letter"] = "{quest:5674} : la lettre de Nara",
	["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Nara à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5675}: Rohan's letter"] = "{quest:5675} : la lettre de Rohan",
	["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Rohan à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Au niveau 10, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous donne un paquet pour {npc:332} à {zone:1453}. Apprenez {spell:921} si vous ne l'avez pas : cette suite en a besoin.",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Partez au nord jusqu'à {zone:1453}. Shaw se tient à l'étage du bâtiment du SI:7 dans {object:2100} (la quête parle de la caserne ; il s'agit du SI:7).",
	["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "{npc:6846} (niveau 10, un gobelin) travaille dans la maison du quai à {area:797}, sur la rivière au bord sud d'Elwynn, au sud de {area:87}. Entrez camouflé et faites-lui {spell:921} par-derrière : l'horaire ne tombe jamais de son cadavre. N'ouvrez pas avec {spell:2070} ni par un combat : il appelle trois vagues de gardes du corps. Tenez-vous loin des cheminées de la maison ; elles vous font sortir du camouflage. Il revient 2 à 5 minutes après sa mort.",
	["{item:7675}: {spell:921} the {npc:6846}"] = "{item:7675} : {spell:921} sur {npc:6846}",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} est dans {object:32383}, le quartier des voleurs au nord de {zone:1455} : entrez dans le bâtiment avec un marchand louche devant et descendez l'escalier.",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Partez vers l'ouest jusqu'à {area:133}. À côté de la route qui mène à son entrée se dresse une tour en spirale en bois : {npc:6886} attend camouflé sur la plate-forme du haut, à côté d'un {npc:1211} de niveau 10 ; vous ne le voyez que de près.",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Au niveau 10, {npc:3599}, le maître des voleurs de l'auberge de {area:186}, vous donne une rose pour {npc:4163} à {zone:1457}. Si vous perdez la rose, abandonnez la quête et reprenez-la.",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Partez vers l'ouest jusqu'à {zone:1457}. {npc:4163} est sous terre à {area:1658} : on descend par l'ouverture au pied de l'arbre fendu à gauche de l'arbre de l'archidruide, près du maître des sabres-de-nuit. Son repère sur la carte s'affiche à la surface.",
	["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (satyre de niveau 12) vit sur une grande branche au nord de {area:264} : passez par la brèche en V dans le mur au nord de la clairière et avancez le long de la branche. Faites-lui les poches pour le journal ; le tuer ne le donne pas, et un combat fait venir trois serviteurs de Sethir. Il marche entre la branche principale et une branche latérale : attendez camouflé au bout de la branche principale et faites-lui les poches par-derrière quand il revient. Puis {spell:2983} pour partir. Il revient 8 minutes et demie après sa mort.",
	["{item:7737}: Pick Pocket Sethir the Ancient"] = "{item:7737} : faire les poches de Sethir l'Ancien",
	["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}, then {item:7676} from {npc:7009}."] = "Votre premier crochetage au niveau 16 : le coffret de {npc:6966} à {quest:2282}, pour {quest:2300}, puis {item:7676} auprès de {npc:7009}.",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "Au niveau 16, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous envoie auprès de {npc:6946} à {zone:1453}. La prendre ferme les indications des autres villes.",
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "Au niveau 16, {npc:1234}, dans {area:2102} à {area:131}, vous envoie auprès de {npc:5165} dans {object:32383} de {zone:1455}.",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} est dans la maison avec un marchand louche devant, dans {object:32383}, en bas de l'escalier. Puis volez ou prenez {area:2257} jusqu'à {zone:1453}.",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "Au niveau 16, {npc:3599}, à l'auberge de {area:186}, vous envoie auprès de {quest:2259} à {zone:1457}.",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} se tient à {area:1658}. Puis le bateau de {area:702} à {area:442}, et le bateau de {area:442} à {area:17203}.",
	["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} se tient à l'étage du bâtiment de {quest:2300} dans {object:2100}, derrière les maîtres des voleurs. Avant de partir : si vous n'avez pas {spell:1804}, {npc:13283}, dans le bâtiment de {quest:2300}, l'enseigne ; le crochetage est l'épreuve de la quête suivante.",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Partez vers l'est à travers {zone:1429} jusqu'aux Carmines, ou volez jusqu'à {area:69}. {npc:6966} se tient sur une caisse sur l'un des quais de {area:69}, au sud de la ville ; il vous donne {item:5060} avec la tâche ({npc:3090} à {area:69} en vend d'autres). {spell:1804} ne marche pas sans les outils dans vos sacs.",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} se trouve à l'est de {area:69}, en hauteur à l'écart de la route ; des orcs Rochenoire rôdent tout près. À l'intérieur, les coffrets d'entraînement reviennent presque aussitôt : crochetez-les jusqu'à ce que {object:121264} s'ouvre pour vous (environ 25 en crochetage). Votre plafond de crochetage monte de 5 par niveau, un personnage de bas niveau peut donc plafonner. Certains coffrets sont piégés (un piège de givre, par exemple) ; la compétence monte quand même. Sur Forever, des araignées de niveau 20 errent près des coffrets : éliminez-les d'abord ou venez avec un ami. Le coffret contient toujours le jeton et revient deux secondes après usage. Continuez à vous entraîner tant que ça fait monter la compétence : la quête de classe suivante demande environ 75.",
	["{npc:7009}, beside {npc:6966}, wants the {quest:2358}, which the Blackrock orcs of Redridge carry: the first one you kill drops them. The easiest are the Blackrock Grunts (level 19) and Outrunners (20) east of {area:69}; the Shadowcasters (22) and {npc:334} (26) are elite."] = "{npc:7009}, à côté de {npc:6966}, veut {quest:2358}, que portent les orcs Rochenoire des Carmines : le premier que vous tuez les lâche. Les plus faciles sont les grunts (niveau 19) et les coursiers (20) Rochenoire à l'est de {area:69} ; les lanceurs d'ombre (22) et {npc:334} (26) sont élites.",
	["{quest:2358}: any Blackrock orc"] = "{quest:2358} : n'importe quel orc Rochenoire",
	["{npc:7009}: ten {item:7676}"] = "{npc:7009} : dix {item:7676}",
	["Poisons (Alliance)"] = "Poisons (Alliance)",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever enseigne les poisons par cette suite de quêtes, pas par le maître ; la recette de {item:7676} vient avec.",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Au niveau 20, {npc:332}, à l'étage du bâtiment du SI:7 dans {object:2100}, vous envoie auprès de {npc:7024} à {zone:1436}. C'est ainsi qu'on apprend les poisons sur Forever : ne la passez pas.",
	["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen se cache, camouflé, contre le côté ouest d'un grand arbre précédé de deux petits arbres, juste au nord de la tour défias de {npc:7053}, tout à l'est de {zone:1436}, près de la frontière de {zone:1431}. Lisez {item:8046} pour le plan de la tour si vous le souhaitez.",
	["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "Prenez d'abord la clé. {npc:7051} (niveau 23, non élite) part de l'entrée de la tour et fait une boucle à l'extérieur ; c'est celui aux cheveux hérissés qui laisse des étincelles jaunes. Camouflez-vous et faites-lui {spell:921} par-derrière : il a toujours la clé. Il frappe fort : si le camouflage tombe, {spell:2983} pour partir. Attention à la paire de bourdons défias qui patrouille aussi.",
	["{item:7923}: {spell:921} the {npc:7051}"] = "{item:7923} : {spell:921} sur {npc:7051}",
	["Klaven's journal"] = "Le journal de Klaven",
	["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Montez la tour en vous faufilant. Des patrouilleurs (23) et des sentinelles (24) défias gardent les étages ; une Embuscade à la dague les tue d'un coup si vous préférez les éliminer. {npc:7053}, un élite de niveau 26, attend au dernier étage : assommez-le, ou venez avec un ami. {object:123214}, à côté de son bureau, demande environ 70-75 en crochetage (entraînez-vous d'abord sur les coffrets de {area:97} aux Carmines). Une astuce : pendant que les sentinelles sont ailleurs, sautez de la chaise à la lampe puis à l'étagère au-dessus du coffre, sortez du camouflage et ouvrez le coffre de là. L'ouvrir vous empoisonne avec {spell:9810}, qui bloque votre camouflage un moment et permet au bourdon de vous voir ; c'est pourquoi la clé passe en premier. Puis sortez.",
	["{item:7908}: the {object:123214}, top floor"] = "{item:7908} : {object:123214}, dernier étage",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Partez au nord à travers Elwynn jusqu'à {zone:1453} ; Mathias Shaw est à l'étage du SI:7. Il enseigne les poisons et vous donne la recette de {item:7676}. Les poisons se fabriquent, ils ne s'achètent pas : chaque lot de {item:6947} demande {item:2928} et {item:3371}, que {npc:1325} et {npc:1326} vendent dans {object:2100} à côté du SI:7. Achetez une pile de chaque, ouvrez Poisons depuis votre grimoire pour les fabriquer, puis appliquez un poison sur votre arme.",
	["{npc:332}: Poisons"] = "{npc:332} : Poisons",
	["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} est toujours sur vous. {npc:7207} travaille dans la cave du bâtiment du SI:7 : l'escalier qui descend est sous celui qui monte à l'étage, derrière {npc:1325}. Ciblez-le et tapez /allonger (rien après) pour être examiné, puis attendez. S'il ne fait rien, abandonnez la quête, reprenez-la et attendez qu'il vous demande de vous allonger.",
	["/lay with the Doc targeted"] = "/allonger en ciblant le docteur",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: an engineering supplier, who keeps only a few (or an engineer or the Auction House). The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Les quatre sont à {zone:1453}. {item:3421} : chez Bernard ou chez le fleuriste {npc:1303} près du canal de {object:2096}. {item:3372} : chez beaucoup de marchands de fournitures et d'alchimie ({npc:1257}, {npc:1325} et d'autres). {item:4371} : chez un fournisseur d'ingénierie, qui n'en a que quelques-uns (ou un ingénieur ou l'hôtel des ventes). {item:8431} gît au sol à côté de l'extrémité gauche du comptoir dans {object:2177}, la boutique du tailleur sur les canaux ; vous ne pouvez la ramasser qu'avec cette quête. Si vous passez le remède, {item:6452} ({skill:129}) ou le {spell:526} d'un druide dissipe aussi {spell:9810}.",
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Au niveau 30, {npc:258098}, le maître des chamans de {zone:1455}, vous envoie auprès de {npc:259023} à {zone:1417}. Vos totems d'air du niveau 30 (Glèbe, {spell:10596}) ont besoin de {item:5178} qu'il donne.",
	["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} campe dans les collines juste à l'ouest de {area:321}, la ville de la Horde au nord-est d'Arathi : attention à ses gardes. Volez jusqu'à {area:320} et partez au nord-est.",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} est un donjon pour cinq joueurs au bord sud de {zone:1413} (la flèche pointe son entrée) ; {npc:4421} (élite de niveau 33) en est le dernier boss. Elle lance {spell:8292}, {spell:139} sur ses alliés et Pureté ; {item:274463} ne tombe que sur elle.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinq totems de feu tordus. Les troggs de Cave-pierre (cogne-crânes, brise-os et chamans, niveau 37-41) au sud de {area:338} dans {zone:1418} en portent ; les chamans lâchent des totems de Nova de feu et {npc:3560}, les brise-os fuient chercher de l'aide quand ils sont blessés. Réapparition en cinq minutes environ.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinq totems de terre tordus. Les Égarés (murlocs, niveau 34-39) au nord et au nord-est de {area:75} dans {zone:1435} en portent ; la plupart fuient chercher de l'aide quand ils sont blessés.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinq totems d'eau tordus. Les murlocs Nageoire-de-boue (niveau 35-38) au nord-est de {area:496}, dans le nord de {zone:1445}, en portent.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinq totems d'air tordus. Les centaures maraudine (niveau 36-40) au nord et au nord-est de {area:2408}, dans l'ouest de {zone:1443}, en portent ; les éclaireurs en lâchent un presque une fois sur deux. Les dresseurs lancent Filet et Désarmement, les chasse-vent soignent, les tempétueux lancent {spell:9654} : attirez-les un par un. Réapparition en cinq minutes environ.",
	["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} vous remet {item:268582}. {zone:1441} est loin : le bateau jusqu'à Theramore et la route vers l'ouest, ou volez jusqu'à {area:489} à la frontière de {zone:1444} et partez à l'est dans le canyon. Placez {item:268582} aux bassins de vapeur au nord-ouest de {area:484} pour appeler les élémentaires corrompus puis {npc:216474} ; des huttiers Tranchecrin rejoignent le combat pendant le rituel. Une quête de groupe : venez avec au moins un ou deux amis. {item:212792} tombe environ une fois sur deux, et chaque membre du groupe peut la ramasser.",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} campe dans les ruines à l'est de {zone:1416} : depuis {area:272}, suivez la rivière à l'est de la ville vers le nord dans les collines. Choisissez votre arme : {item:280607}, {item:280605} ou {item:280604}.",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Votre {item:5175} : sans elle, aucun totem de terre ne peut être posé. {spell:8071} vient avec, au niveau 4.",
	["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} entraîne les chamans dans {area:77}, la salle à l'extrémité sud de {area:132}. La quête s'ouvre au niveau 4. Jamais prise et maintenant niveau 10 ou plus ? {npc:258098} à {zone:1455} ou {npc:258113} à {area:131} vous donne {quest:94373}, une indication pour retourner voir Teo : prenez-la pour l'expérience en chemin.",
	["Iceclaw Bear Pendants"] = "Pendentifs d'ours Griffe-de-glace",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Les jeunes trolls Crins-de-givre (niveau 3-4) tiennent les pentes enneigées à l'ouest et au sud-ouest de {area:77}, et les novices Crins-de-givre (niveau 3-4, ils lancent des éclairs de givre à distance) campent au sud. Les deux portent les pendentifs ; ils réapparaissent en trois minutes environ.",
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Retour auprès de Teo dans {area:77}. Il vous remet {item:6635} : ne le buvez pas encore.",
	["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Seulement si {quest:94472} n'est plus dans vos sacs (bue loin de la pierre, ou vendue) : Teo vous en donne une autre.",
	["The Spirit Stone"] = "La pierre de l'esprit",
	["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "La pierre de l'esprit se dresse sur une crête enneigée au nord-ouest de {area:77}. Le sentier est facile à manquer : il monte la colline depuis le fond de la vallée ; au petit camp près du sommet, tournez à gauche et la pierre apparaît. Placez-vous à côté, buvez {item:6635} et parlez à {npc:5891} avant qu'il ne s'efface.",
	["it hands you the {item:6656}: keep it"] = "il vous remet {item:6656} : gardez-le",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Rapportez {item:6656} à Teo dans {area:77}. Gardez {item:5175} dans vos sacs pour de bon : chaque totem de terre en a besoin.",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446} : {spell:8071} et votre {item:5175}",
	["the level 4 shaman spells"] = "les sorts de chaman du niveau 4",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Votre {item:5176} pour chaque totem de feu, {spell:3599} avec, et {item:263412} de Forever.",
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Au niveau 10, {npc:258113}, le maître des chamans de {area:131}, ou {npc:258098}, le maître des chamans de {zone:1455}, vous envoie auprès de {npc:257597}.",
	["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131} ; ou {npc:258098}, {zone:1455}",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Suivez la route vers l'est jusqu'au tunnel vers {area:806}. À la sortie du premier tunnel, restez à gauche après {npc:1959} et la tour : un sentier étroit, difficile à voir mais indiqué sur la minimap, serpente dans la montagne jusqu'à la grotte de {npc:257597} au-dessus de la ferme. Il vous remet {item:6653} : gardez-le jusqu'à la fin de la suite.",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Depuis le rebord de {npc:257597}, vous pouvez descendre prudemment la montagne jusqu'à {zone:1432}, ou revenir à pied par le tunnel. {npc:257808} garde le sanctuaire sur le pic juste au sud de {area:144} : un sentier caché le long d'une corniche, balisé de totems de pierre, y monte depuis la route au nord du pic.",
	["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Les voyants Brise-pierre (niveau 13-14) se tiennent parmi les troggs de {area:923} au sud du loch, et dans les camps de troggs au nord-est de {area:144}. Ils lancent {spell:1245113} à 40 mètres et fuient chercher de l'aide quand ils sont blessés : attirez-les un par un. Réapparition en cinq minutes environ.",
	["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Les géomanciens rats des tunnels (niveau 12-13) ne travaillent que dans {area:149}, à l'extrémité nord du loch, après {area:144}. Ils lancent {spell:2136} derrière {spell:134} et fuient chercher de l'aide quand leur vie est basse.",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Remontez le sentier jusqu'à {npc:257808}. Il fabrique {item:6636} avec le goudron et la bourse : gardez-le avec la torche.",
	["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Seulement si {quest:94473} n'est plus dans vos sacs : {npc:257808} vous en donne un autre.",
	["The Shrine of Eternal Flame"] = "Le sanctuaire de la Flamme éternelle",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Continuez après {npc:257808} jusqu'au pic. Buvez {item:6636} à côté de la statue de pierre pour voir {npc:5893} (niveau 12) : il attend que vous frappiez, mais devient plus fort plus on le laisse, et il est insensible au feu. Ouvrez tout de suite avec {spell:8017} et {spell:8042}. Son {item:6655} tombe à chaque fois.",
	["{item:6636}, beside the statue"] = "{item:6636}, à côté de la statue",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Cliquez sur {object:61934} au sommet du sanctuaire avec la torche dans vos sacs pour placer la braise, puis cliquez à nouveau pour la quête suivante : {item:277329} allumée.",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Revenez par le tunnel de la porte Sud et remontez le sentier jusqu'à la grotte de {npc:257597}. Gardez {item:5176} dans vos sacs pour de bon : chaque totem de feu en a besoin.",
	["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597} : {spell:3599}, votre {item:5176} et {item:263412}",
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Au niveau 20, {npc:258098}, le maître des chamans dans {object:32362} de {zone:1455}, vous envoie auprès de {npc:258043} à {zone:1432}.",
	["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "La hutte terrier de {npc:258043} se dresse sur la rive nord-ouest du loch, sous {area:146}, au nord de {area:144}.",
	["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "La famille de {npc:258203} vit dans une grotte sous les chutes sud de {zone:1437}, à l'est de {area:836} : pas dans une ville. Par le tunnel d'Algaz au nord de {zone:1432}, puis à l'est en quittant la route.",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Remplissez {item:265732} au pied des cascades sous la grotte de {npc:258203}, là où l'eau douce rencontre l'eau saumâtre. Des nains {object:147516} rôdent près des chutes.",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} jaillissent de {area:68} à l'extrémité est des Carmines (volez de {zone:1455} à {area:69}). Remplissez {item:265747} à leur pied, là où se rassemblent les rampants nocturnes murlocs ; éloignez d'abord les murlocs de l'endroit. Si l'outre disparaît sans compter, abandonnez la quête et reprenez-la auprès de {npc:258203} pour en avoir une nouvelle.",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Prenez le bateau de {area:150} à {area:442} (il fait escale à {area:271}), puis volez ou marchez au sud à travers {zone:1439} jusqu'à {area:415} à {zone:1440}. Remplissez {item:265772} dans le lac autour de la ville, puis reprenez le bateau pour Menethil.",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Retour auprès de {npc:258043} près de {area:146} avec {item:7810}. Il vous remet {item:6637} et {item:7811} : gardez les deux pour {zone:1436}.",
	["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Seulement si {quest:94616} n'est plus dans vos sacs : {npc:258043} vous en donne une autre avant votre départ pour {zone:1436}.",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Volez jusqu'à {area:108} et partez au sud jusqu'à {area:20} : {area:919} et {object:619896} se trouvent juste au nord. Buvez {item:6637} près du sanctuaire pour voir {npc:5894} (niveau 22, {spell:8056} et {spell:122} ; un seul exemplaire, de retour trois minutes après sa mort), battez-le pour ses brassards (toujours lâchés), puis placez-les avec {item:7811} sur {object:619896} (c'est cela, et non {npc:258043}, qui termine la quête). Cliquez à nouveau sur le sanctuaire : {npc:5895} se lève à côté ; parlez-lui avant de partir (s'il a disparu, abandonnez et reprenez la quête au sanctuaire). Il vous donne {item:7813}.",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Retour auprès de {npc:258043} avec {item:7813}. Gardez {item:5177} dans vos sacs pour de bon : chaque totem d'eau en a besoin.",
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Un chapeau en tissu vers la fin de la vingtaine : la course de Zardeth pour tout joueur de l'Alliance rapporte ce bonus aux démonistes.",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Au niveau 25, {npc:1435}, dans la cave de {object:2164} dans {object:2101} (à côté des maîtres des démonistes), veut deux ingrédients pour une décoction. Faites-la quand votre montée en niveau vous mène à {zone:1431} et à {zone:1437}.",
	["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} se trouve au nord-est de {zone:1431}, au nord de {area:42}. {object:321} est une petite fleur blanche au ras de l'herbe dans le jardin clôturé à côté de la maison de Stalvan : difficile à voir, balayez donc le jardin avec la souris. Des cadavres fétides (niveau 29) errent sur le domaine et arrivent vite : au niveau 25, envoyez votre marcheur du Vide sur le plus proche, prenez la fleur et partez. {npc:315} (32) est dans la maison ; laissez-le tranquille.",
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "La racine pousse au bord de l'eau dans le bassin sous les petites chutes à l'est de {area:836}, à côté de la grotte {object:147516} sous {area:146} : une grande racine de bois hérissée, pas au pied du barrage lui-même.",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Retour auprès de Zardeth. Il prépare {item:2788} et vous le donne pour {npc:1439} dans la salle des Requérants, la première salle à droite dans {object:2117}.",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Retour une dernière fois auprès de Zardeth : il offre une récompense aux démonistes, que son diablotin {npc:1733}, à côté de lui, vous remet.",
	["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} est un port gobelin neutre sur la côte de {zone:1413} : le bateau de {area:35} y accoste. {npc:6251} se tient sur la colline au-dessus de la ville, derrière la hutte des ingénieurs, près de sa petite tour ; {npc:6266} et deux acolytes sont avec lui. Il vous envoie auprès de {npc:6294} à {zone:1455}.",
	["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} est dans la bibliothèque de {object:32356}. Il veut deux morceaux perdus de {quest:1758} : un sur la côte de {area:287}, un à {zone:1441}.",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Le tome est un petit livre gris-bleu posé dans le sable d'un camp de murlocs sur le rivage au sud-ouest de {area:271}, près du bord de l'eau. Six ou sept murlocs le gardent et d'autres se cachent sous l'eau : ils viennent en groupes, apeurez-en donc un et gardez votre marcheur du Vide sur les autres. Descendez jusqu'à l'eau pour cliquer dessus ; depuis le flanc de colline, les caisses bloquent le curseur.",
	["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, sur {quest:1802} dans le sable",
	["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La grotte des centaures s'ouvre dans les falaises au nord de {area:484}, une ville de la Horde : tenez-vous loin de ses gardes. À l'intérieur, restez à droite à chaque embranchement, traversez le bassin près de la petite cascade et ouvrez la petite boîte sombre contre le mur à côté d'un coffre plus grand : le grand n'est pas le bon. Vous ne pouvez l'ouvrir qu'avec la quête. Les centaures réapparaissent derrière vous en sortant.",
	["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} reconstitue le tome et vous donne {item:7006} : gardez-le, {npc:6251} le prend avec les bâtonnets.",
	["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Les Gueule-de-dragon tiennent {area:1036} dans les collines à l'est de la route de {area:150} à {area:836}. Seuls les lanceurs de sorts lâchent les bâtonnets, quatre fois sur cinq : les gardes-os (niveau 27, avec des squelettes) et les gardes de l'ombre (28). Un sentier escarpé au nord du gardien des âmes central monte dans le camp en évitant la plupart des guerriers.",
	["Rods of Channeling, from the Dragonmaw casters"] = "Bâtonnets de canalisation, sur les lanceurs de sorts Gueule-de-dragon",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Retour auprès de {npc:6251} à {area:392}. Quand vous acceptez, il trace le cercle d'invocation et ses acolytes canalisent un cercle supérieur au-dessus : attendez dans la tour que les deux soient faits. Puis utilisez {quest:1804} sur le cercle. Le chasseur corrompu (niveau 30, non élite) réduit au silence et dévore le mana, et il disparaît au bout de deux minutes : sortez votre marcheur du Vide, ouvrez tout de suite avec vos dégâts sur la durée et laissez le marcheur du Vide encaisser. Si vous mourez ou s'il gagne, abandonnez {quest:1795} et reprenez-la auprès de {npc:6251}. Gardez le tome : {npc:6251} le reprend.",
	["{quest:1804}, on the circle"] = "{quest:1804}, sur le cercle",
	["Imp (Alliance)"] = "Diablotin (Alliance)",
	["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Votre premier démon aux niveaux 1-4 : le diablotin, auprès du maître des démonistes de votre zone de départ.",
	["{npc:459} (Humans)"] = "{npc:459} (humains)",
	["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Votre première lettre ({item:9576}, de {npc:197} après Nettoyage du camp kobold) vous envoie auprès de {npc:459}, la maîtresse des démonistes dans le petit cimetière à côté de {area:24}. Elle demande un livre que les Défias ont volé.",
	["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "La tente défias se dresse dans les vignes à l'est de l'abbaye. Le livre est petit : il est posé au sol juste à droite de l'entrée de la tente, à côté d'une cruche bleue. Trois brutes défias (niveau 3-4) gardent la tente ; attirez-les une par une, ou entrez dans la tente et cliquez sur le livre, là où elles ne peuvent pas vous atteindre. Le livre réapparaît trois minutes après qu'on l'a pris.",
	["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} vous enseigne {spell:688} au rendu : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
	["{npc:460} (Gnomes)"] = "{npc:460} (gnomes)",
	["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Votre première lettre ({item:9577}, de {npc:658} après Équipement nain) vous envoie auprès de {npc:460}, le maître des démonistes à l'étage dans {area:77}. Il demande trois charmes de plume.",
	["Feather Charms"] = "Charmes de plume",
	["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Les novices Crins-de-givre (niveau 3-4) se tiennent au fond de la grotte des trolls au sud de {area:77}, près de Grek'nir le Froid à côté du bassin gelé : prenez le tunnel de gauche après l'entrée. Quatre victimes sur cinq lâchent un charme, mais seuls deux ou trois novices apparaissent, vous attendrez donc peut-être leur réapparition de trois minutes. Ils lancent des éclairs de givre à distance ; les jeunes trolls à l'entrée de la grotte sautent sur tous ceux qui passent. Une fois les charmes en poche, votre pierre de foyer vous ramène directement : celle d'un nouveau personnage est liée à {area:132}.",
	["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} vous enseigne {spell:688} au rendu : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
	["Succubus and Incubus (Alliance)"] = "Succube et incube (Alliance)",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Au niveau 20 : la succube et l'incube de Forever, son jumeau masculin, chacun avec une bourse d'âmes pour vos fragments.",
	["{quest:1717} (Gnomes)"] = "{quest:1717} (gnomes)",
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Au niveau 20, {npc:6120}, le maître des démonistes dans {object:32383} de {zone:1455}, vous envoie auprès de {npc:6122} à {zone:1453}. Prenez {area:2257}.",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Au niveau 20, {npc:6122}, dans la cave de {object:2164} dans {object:2101}, vous envoie auprès de {npc:6244} à {zone:1413} : un long voyage pour l'Alliance. Prenez le bateau de {area:150} à Theramore et partez vers l'ouest à travers {zone:1445}, ou le bateau de {area:35} à {area:392}.",
	["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} campe sous une tente avec un feu de camp juste au nord-est de {area:378}, à une bifurcation de la route : en terre de la Horde, arrivez donc par l'est et évitez les gardes de Taurajo. {npc:6247}, à côté de lui, commence {item:6898}. Takar propose les deux branches : prenez les deux.",
	["the succubus"] = "la succube",
	["the incubus"] = "l'incube",
	["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran se trouve dans le nord-ouest de {zone:1440}, au nord de {area:415} le long de la route vers {zone:1439}. Une vingtaine de cultistes du Sombre brin tiennent les ruines autour du grand arbre : longez le mur extérieur et cliquez sur {quest:1738} d'aussi loin que possible. Elle se rend à {npc:6122}, pas à Takar.",
	["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "La maison se dresse seule parmi les arbres du nord-ouest de {zone:1440}, au nord-ouest d'Ordil'Aran et bien au nord de {area:413} : faites-la lors du même voyage que {quest:1738}. Prenez {item:190307} sur la table dehors, allumez-la à un feu de camp ({object:29784} à vous, ou le feu de Talen à {area:414}) et revenez aussitôt : {item:190308} s'éteint au bout de cinq minutes, un feu à vous à côté de la maison est donc le plus rapide. Sans elle, la silhouette de la maison vous arrête. La figurine est à l'étage.",
	["{item:190307}, on the table outside"] = "{item:190307}, sur la table dehors",
	["{quest:1739}: succubus"] = "{quest:1739} : succube",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Retour auprès de {npc:6122} avec {quest:1738}. Il vous remet {item:6913} : prenez l'escalier derrière lui jusqu'à la crypte ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à la salle au cercle violet. Placez-vous dessus et utilisez le noyau. Invoquez d'abord votre marcheur du Vide et gardez la succube (niveau 20, non élite) sur le cercle, sinon les gardes risquent de la tuer et la victoire ne compte pas. Si elle gagne, utilisez à nouveau le noyau ; gardez-le, {npc:6122} le reprend.",
	["{item:6913}, on the circle in the crypt"] = "{item:6913}, sur le cercle de la crypte",
	["{quest:65603}: incubus"] = "{quest:65603} : incube",
	["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Donnez la figurine à Gakin, puis utilisez {item:190309} au milieu du même cercle et battez l'incube qu'il appelle (niveau 20, non élite ; il peut vous charmer), votre marcheur du Vide encaissant. Gardez la figurine : {npc:6122} la reprend.",
	["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, au cercle de la crypte",
	["Voidwalker (Alliance)"] = "Marcheur du Vide (Alliance)",
	["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Votre démon protecteur au niveau 10 : le marcheur du Vide, après le collier d'une sorcière noire et un combat dans la crypte de {npc:6122}.",
	["{quest:1685} (Humans)"] = "{quest:1685} (humains)",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Au niveau 10, {npc:6121}, dans la cave de l'auberge de la Fierté du lion à {area:87} (l'escalier descend dans l'arrière-salle après la table du boucher), vous envoie auprès de {npc:6122} à {zone:1453}.",
	["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, cave de l'auberge de la Fierté du lion",
	["{quest:1715} (Gnomes)"] = "{quest:1715} (gnomes)",
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Au niveau 10, {npc:6120}, le maître des démonistes dans {object:32383} de {zone:1455}, vous envoie auprès de {npc:6122} à {zone:1453}. Prenez {area:2257} depuis {object:171524}. Si {npc:6120} ne la propose pas, allez quand même voir {npc:6122} : il vous donne quand même la quête suivante.",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} est la taverne de {object:2101} ; {npc:6122} est dans sa cave, en bas de l'escalier intérieur.",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (niveau 9) est dans la ferme de {area:62}, au sud-est d'Elwynn près de la route des Carmines. {npc:473} (niveau 10) et un guerrier se tiennent avec elle et rejoignent le combat ; Morgan suriine et s'en prend à votre diablotin, gardez-le donc apeuré. Posez d'abord vos dégâts sur la durée sur {npc:881}, apeurez les autres, et ramassez son collier avant de les achever : il reste à vous même si vous mourez ensuite. Elle lance des boules de feu à distance et revient trois minutes après sa mort. Ayez la quête avant de la tuer, sinon le collier ne tombe pas.",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Retour auprès de {npc:6122}. Il vous remet {item:6928}. Le cercle est difficile à trouver : prenez l'escalier derrière {npc:6122} ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à une salle avec un cercle violet lumineux au milieu. Placez-vous dessus et utilisez le collier. Le marcheur du Vide (niveau 10, non élite) devient dangereux sous 30 % de vie : {spell:14868}, Corruption et {spell:348} avec votre diablotin dessus, Peur quand il s'approche. S'il vous bat, utilisez à nouveau le collier. Gardez le collier : {npc:6122} le reprend.",
	["{item:6928}, on the circle in the crypt"] = "{item:6928}, sur le cercle de la crypte",
	["A hauberk at 28, a coif, leggings and gauntlets from three smiths, and a shield on the way."] = "Un haubert au niveau 28, une coiffe, des jambières et des gantelets de trois forgerons, et un bouclier en chemin.",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Au niveau 20, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres des guerriers de {object:2100}, vous envoie auprès de {quest:1698} aux Carmines.",
	["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} est assis à l'auberge de {area:69}. Son épreuve est chronométrée : avant de la prendre, éliminez les gnolls des Carmines sur le chemin de {area:98} dans les collines au nord-ouest de {area:69}, y compris les deux sur le rocher près de l'entrée de la grotte (montez-y par son côté droit).",
	["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Vous avez une heure, et {spell:8553} de {npc:6166} vous laisse ivre pendant 8 à 10 minutes. Courez au nord-ouest jusqu'à {area:98}, en longeant la falaise pour éviter la plupart des groupes de gnolls, et entrez jusqu'au premier embranchement ; puis revenez voir {npc:6166} (depuis la crête, vous pouvez sauter jusqu'à {area:69}). Mourir et libérer votre esprit fait échouer la quête : abandonnez-la et {npc:6166} vous la redonne.",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413} travaille dans le quartier des Nains de Hurlevent. Il prend {item:6843} (perdu ? abandonnez la quête et {npc:6166} en donne un nouveau) et vous donne {item:6970}, un bouclier ; {quest:1701} est une quête de niveau 28, {item:6842} listant ce qu'il faut.",
	["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "Il vous faut 50 crocs. Les traqueurs sangsues et les traqueurs des cavernes (niveau 21-22) rampent au milieu de {zone:1437}, au nord de {area:836} ; tous lâchent un croc. Ils empoisonnent ; de retour en 5 minutes.",
	["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Les chimères vivent au sud-ouest de {area:460} à {area:465} : il vous faut 12 cornes calcinées sur les chimères novices (niveau 25-27) et les jeunes chimères (23-25), quatre fois sur cinq, et {item:6840} sur {npc:6167} (28, la grande), aussi quatre fois sur cinq. Seules trois novices, deux jeunes et une matriarche y vivent, chacune de retour en 5 minutes : attendez-vous à patienter. Les novices et la matriarche crachent {spell:3396}, les jeunes lancent {spell:403}. Alliance : volez jusqu'à {area:467} et partez au sud.",
	["{item:6839}, from the young chimaeras"] = "{item:6839}, sur les jeunes chimères",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug est un huttier élite (niveau 28) dans {area:1717}, le donjon à l'extrémité sud de {zone:1413} ; un donjon pour cinq : il faut un groupe de cinq, et ses gardes viennent avec lui. À l'intérieur, prenez à gauche au premier embranchement, traversez le pont de racines, passez le grand chaudron vide : il est dans un cul-de-sac à droite, avec une dizaine d'élites en chemin. Il lance {spell:403} et appelle des grondeurs de terre. La fiole tombe toujours.",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Retour auprès de {npc:5413} dans {object:28027} pour le haubert. Il vous envoie ensuite au forgeron de votre race ; les pièces des deux autres forgerons vous sont aussi ouvertes : parlez-leur directement.",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} tient l'armurerie au nord-ouest de {object:28027}, à quelques pas de {npc:5413}. Il veut 20 {quest:1705} et {item:6845}.",
	["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Les worgens Plaie-de-nuit de {zone:1431} (coureurs sombres, crocs infâmes, tisseurs d'ombre, worgens et souillés, niveau 26-31) au sud et à l'ouest de {area:42} lâchent {quest:1705} quatre fois sur cinq. {npc:6170} (niveau 32, non élite) porte {item:6845} (aussi quatre fois sur cinq) : il va et vient entre l'intérieur et l'entrée de la mine de {area:2161} au sud-est de {area:42} ; attendez donc à l'entrée et attirez-le dehors. {npc:6170} et les souillés empoisonnent et hurlent ; les crocs infâmes causent {spell:3427}.",
	["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, sur les worgens Plaie-de-nuit",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} travaille du côté sud de {area:1660} à {zone:1457}. Il veut 20 {quest:1710}.",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "Les coquilles gisent au sol sous les nids de wyvernes de {area:482}, dans l'ouest de {zone:1441}, plus loin dans la gorge. Il n'en existe que neuf et chacune revient 3 minutes après ramassage, vous attendrez donc ; certaines choses qui y ressemblent ne se ramassent pas. Des wyvernes Haut-perchoir (niveau 28-31) les gardent et viennent parfois à plusieurs.",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Prenez {area:2257} de {zone:1453} à {zone:1455}. {quest:1704}, un forgeron gnome, travaille dans {object:171524} près des maîtres ingénieurs. Il veut 20 {item:6848}.",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an {item:5996} removes the risk."] = "{quest:1708} pousse au fond de la mer juste au sud de {area:150}, près des huttes des murlocs et d'un bateau échoué : huit là et deux au sud-est du port, chacune de retour en 3 minutes ; vous attendrez donc les réapparitions pour arriver à 20. Les murlocs peuvent vous prendre au filet sous l'eau : surveillez votre souffle, et {item:5996} supprime le risque.",
	["{spell:71} and a Weapon (Alliance)"] = "{spell:71} et une arme (Alliance)",
	["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} au niveau 10 et une arme à une main de votre choix à {zone:1453}, {zone:1455} ou {zone:1457}.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Au niveau 10, {npc:252377} se tient avec les maîtres près de la porte ouest de {area:16638}. Un cultiste, {npc:257196}, détient le bouclier de sa famille à {area:16629}.",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Partez au nord-ouest depuis {area:16638} jusqu'à {area:16629}. {npc:257196} se tient à l'ouest de l'accès au sanctuaire, parmi les gardiens, les invocateurs d'esprits et les maîtres-lames du culte : attirez-les un par un avant de vous en prendre à lui. Il lâche {item:263993}.",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Retour auprès de {npc:252377} à {area:16638}. Elle enseigne {spell:71} et vous donne {item:275290}, un bouclier pour s'en servir. La route de {npc:6090} ci-dessous donne toujours une arme, une fois arrivé à {zone:1453}.",
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Au niveau 10, {npc:1229}, le maître des guerriers de {area:131}, vous envoie auprès de {quest:1679} à {zone:1455}. Tout guerrier de l'Alliance peut prendre l'une des trois routes, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? {quest:1638} de {npc:5480} est la posture la plus rapide (un combat dans une taverne), suivie d'une arme de Haggard.",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} se tient dans {object:32390}, à {object:32359}.",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (niveau 11, un troll seul) attend à sa hutte sur une colline au sud de {area:135}, près des montagnes, en haut d'une petite rampe, sans autre troll autour ; la hutte devant {area:135} n'est pas la bonne. Il combat en {spell:71} et fracasse votre armure ; {spell:6343} le ralentit. Sa tête tombe toujours ; il revient environ 8 minutes après sa mort.",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Retour auprès de {npc:6114} pour {spell:71}, puis auprès de {quest:1680} à {object:32372}, au milieu de {zone:1455}.",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} se trouve dans l'est de {zone:1426}, sous {area:212}, sur son côté sud. Des espions Sombrefer (niveau 8-10) se tiennent en chemin, assez espacés pour être attirés un par un. {object:85562} est dans la cave de la maison la plus au sud ; {npc:6124} (niveau 11) se tient à côté et charge dès qu'il vous voit. La boîte contient toujours le minerai et se remplit 15 minutes après ouverture.",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Au niveau 10, {npc:3598}, le maître des guerriers de {area:186}, ou {npc:2151}, qui patrouille sur la route à l'ouest de {area:186}, vous envoie auprès de {quest:1684} sur {area:1660} à {zone:1457}. Tout guerrier de l'Alliance peut prendre l'une des trois routes, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? {quest:1638} de {npc:5480} enseigne la même posture après un combat dans une taverne.",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684} se tient sur {area:1660}.",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (niveau 10, un satyre) se tient à un puits de lune caché en haut d'un flanc de colline à l'ouest de {area:186}. Le sentier est difficile à repérer : il part derrière un camp Pin-tordu et monte en lacets bordés de lampadaires. Les furbolgs en contrebas peuvent venir en groupes. Son cor tombe toujours ; il revient 5 minutes après sa mort.",
	["Elunite under {area:442}"] = "L'élunite sous {area:442}",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Prenez le bateau de {area:702} à {area:442}. L'épave repose sous l'eau juste au sud de la jetée sud de {area:442}, où accoste le bateau de Menethil. Ouvrez des caisses d'élunite au fond de la mer autour de l'épave, près d'une énorme tortue engloutie, vers la plage et sous la jetée, jusqu'à en avoir huit ; chaque caisse contient du minerai et revient en 3 à 5 minutes. {npc:6133} gris (niveau 11) dérive au milieu de l'épave et lâche toujours le médaillon : ciblez-le quand vous le voyez, pour le retrouver après être remonté respirer. Surveillez votre souffle ; des batteurs peuvent s'en mêler.",
	["{item:6808}, from Crates of Elunite"] = "{item:6808}, dans les caisses d'élunite",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "De retour sur {area:1660} : {npc:4088} vous remet {item:6812} ; {npc:6142} travaille de l'autre côté, au sud de la même terrasse, facile à manquer.",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Au niveau 10, {npc:913}, le maître des guerriers près de l'auberge de {area:87}, vous envoie auprès de {npc:6089} à {zone:1453} ; {npc:5480}, le maître des guerriers dans {object:2100} de {zone:1453}, la propose aussi.",
	["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} et {npc:6090} sont à la taverne du Cochon et du Sifflet dans {object:2100} ; {npc:6090} est l'ivrogne au bout du comptoir. {npc:6090} (niveau 10) frappe plus fort que son niveau, commencez donc avec toute votre vie ; il abandonne quand sa vie est basse au lieu de mourir. S'il gagne, il disparaît environ trois minutes : gardez la quête et reparlez-lui à son retour. Un nain, un gnome ou un elfe de la nuit qui a pris {quest:1638} auprès de {npc:5480} plutôt que sa route d'origine est guidé à travers {zone:1453} à partir d'ici.",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "Le manoir de {npc:294} se dresse au bord sud-est de {area:88}, dans l'est d'Elwynn, au bout d'une petite route qui ne rejoint pas la grande.",
	["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (niveau 11) campe tout au sud-est d'Elwynn. Un garde se tient à côté de lui et des Défias et des loups sont répartis autour du camp (de temps en temps un garde plus rare aussi) : éliminez-les un par un, puis tuez Jack. Il lâche toujours {item:6783} ; ouvrez {object:85563} dans les caisses près de lui pour {item:6782}. Jack revient 3 minutes après sa mort, la boîte 1 minute après ouverture.",
	["from {npc:6093}"] = "sur {npc:6093}",
	["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "La suite de {spell:23214} est longue : {area:2279}, Hache-tripes Ouest et {area:2057} en groupe, 350 pièces d'or de dons, et des composants valant plusieurs centaines de plus (6 barres d'arcanite, 40 {item:14047}, 10 {item:8836}, deux diamants). Commencez à économiser tôt. Seigneur Grayson se tient dans la cathédrale de la Lumière, {npc:6171} tout près.",
	["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, le maître des prêtres, se promène dans {object:32386}, dans {object:32362} de {zone:1455}. Il vous donne son encensoir contre un don de 150 pièces d'or, prélevé au rendu. Gardez l'encensoir.",
	["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Seigneur Grayson bénit l'encensoir, qui devient {item:18752}, pour {area:2627}.",
	["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} se trouve tout au nord-ouest de {zone:1423}, à l'ouest des portes de {area:2279}. Placez-vous dans une tache verte lumineuse au sol ({object:179747} ; certaines sont dans les maisons en ruine) et utilisez {item:18752} : jusqu'à trois esprits de Terreval (niveau 59-60) se lèvent et attaquent. Leur {spell:7713} réduit toutes vos caractéristiques de 30 % : combattez-les un par un et utilisez {spell:2878}. Les taches reviennent vite ; plusieurs paladins peuvent travailler côte à côte.",
	["{item:18752}, inside a green patch"] = "{item:18752}, dans une tache verte",
	["Terrordale Spirits x25"] = "Esprits de Terreval x25",
	["Lord Grayson takes the censer back."] = "Seigneur Grayson reprend l'encensoir.",
	["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} travaille dans {object:28027} de {zone:1453}. Il forge {item:18753} avec vos composants et 150 pièces d'or.",
	["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047} tombe sur les humanoïdes de niveau 50 et plus (les cogneurs de {area:2255}, la Croisade écarlate dans les Maleterres, les ogres de {area:2577}). {item:8836} est une herbe des Maleterres ({skill:182} 220), courante autour de {area:3197}. {item:12360} est une transmutation d'alchimiste à partir de {item:12359} et de {item:12363}, une fois tous les deux jours par alchimiste : demandez tôt à un alchimiste de guilde, ou achetez les barres. L'hôtel des ventes vend les trois.",
	["{item:14047} x40"] = "{item:14047} x40",
	["{item:8836} x10"] = "{item:8836} x10",
	["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Barres d'arcanite x6 : un alchimiste, ou l'hôtel des ventes du quartier commerçant",
	["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} est un donjon pour un groupe de cinq aux niveaux 58-60, à l'extrémité nord de {zone:1423}. Les caisses de ravitaillement de Stratholme le long des rues des deux moitiés contiennent l'eau bénite, une à trois chacune ; elles reviennent au bout de trois minutes. Certaines caisses libèrent un essaim de rats pestiférés ou d'asticots : soyez prêt. La grande porte (la moitié écarlate) ne demande pas de clé.",
	["Stratholme Supply Crates, inside"] = "Caisses de ravitaillement de Stratholme, à l'intérieur",
	["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Apportez les composants et 150 pièces d'or, prélevées au rendu. {npc:1416} va à sa forge et vous remet {item:18753}.",
	["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Seigneur Grayson garde le caparaçon pour l'instant : vous le récupérez avec la quête suivante.",
	["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Les intendants de {object:2160} vendent des biscuits de manne enrichis, cinq pour 60 pièces d'argent, dès que {object:92525} est Amical envers vous : {npc:10857} à {area:3197} ou {npc:11536} à {area:2268}. Les pierres du Fléau et les quêtes des Maleterres font monter la réputation.",
	["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} élève des chevaux dans l'écurie de {area:271}. Elle fabrique {quest:7645} avec les 20 biscuits et 50 pièces d'or, prélevées au rendu.",
	["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} se trouve au centre de {zone:1444}. Depuis la porte au pied des ruines, montez à travers les cours extérieures jusqu'à la porte de l'aile Ouest à leur extrémité nord ; elle demande {item:18249} (sur Pusillin à Hache-tripes Est) ou le crochetage d'un voleur. {npc:11489} (élite de niveau 60) se tient au fond de la première cour de l'aile Ouest. Une fois attaqué, il appelle tous les {npc:11459} encore en vie dans la cour : tuez-les d'abord. Sa mort libère {quest:7643} : parlez-lui pour lui donner la nourriture du cheval et {item:18753}, et il bénit le caparaçon. Un groupe de cinq au niveau 60.",
	["Dire Maul West's door"] = "La porte de Hache-tripes Ouest",
	["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "{item:12800} vient des filons de thorium et de l'obsidienne, environ un filon sur cent ; {item:18335} tombe rarement sur les élites de niveau 59 et plus (Revanchion et {npc:14695} environ une fois sur neuf et une fois sur cent). L'hôtel des ventes est la source habituelle des deux.",
	["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Seigneur Grayson vous remet {item:18804} : ouvrez-la pour {item:18746} et {item:18792}. Gardez les deux.",
	["{item:18792}, from the satchel"] = "{item:18792}, dans la sacoche",
	["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} se trouve sous {area:2298}, la ville insulaire au sud-est de {zone:1422} ; la porte demande {item:13704} (La clé de {area:2057}). Videz {object:179746}, la salle de Cliquettripes au sous-sol, puis utilisez {item:18746} en son centre. Quatre vagues d'esprits arrivent, chacune se terminant par un Aspect : les joueurs les jugent avec {spell:1105}, Justice, Vertu puis Lumière, ce qui les étourdit. {npc:14516} (élite de niveau 62) arrive après la dernière ; il contrôle l'esprit des joueurs. Ramassez {item:18749}, utilisez-le dans l'ossuaire pour le racheter, et donnez-le avec {item:18792} à {npc:14568}. Si le groupe est anéanti, les portes se verrouillent et le scrutateur disparaît : abandonnez la quête et reprenez-la auprès de Seigneur Grayson pour une nouvelle sacoche. Un groupe de cinq au niveau 60. De nouveau dans {object:179746}, après la monture, vous permet de l'affronter à nouveau.",
	["{item:18749}, inside the {object:179746}"] = "{item:18749}, dans {object:179746}",
	["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "Au niveau 40, {npc:6179}, à l'étage de {object:32386}, vous envoie auprès de {npc:6171} à {zone:1453} ({npc:5149}, en bas, donne la même course ; prenez-en une). Prenez {area:2257} jusqu'à {zone:1453}.",
	["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Au niveau 40, il propose {quest:1661} : acceptez-la et rendez-la-lui aussitôt pour apprendre {spell:13819}. Les paladins n'achètent pas de cheval.",
	["Follow the road from Elwynn into {area:40}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "Suivez la route depuis Elwynn jusqu'à {area:40} : les Furlbrow sont assis près de leur ferme incendiée, la première sur la route. Ramassez de l'avoine sur chaque {object:2724} que vous croisez pendant la boucle : le reste se ramasse dans les champs d'ici au retour.",
	["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "Au nord de la ferme des Molsen. Des trappeurs et des contrebandiers défias campent devant la mine. {object:290} se dresse près de la maison en ruine à l'est de la mine.\nÀ l'ouest de chez les Saldean. Des guetteurs et des golems des moissons travaillent les champs ; ils lâchent les isoressorts, les gyrostabilisateurs, {item:732} et parfois {item:255155}. {npc:573}, un rare de niveau 20, se promène ici : laissez-le tranquille. Continuez à tuer des broche-tripes et des déchireurs à chaque étape de cette boucle.",
	["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {area:111} east to the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Two Defias stand guard inside the house, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "Des gnolls et des éclaireurs Rivepatte (niveau 11-13) parcourent les collines au sud de la côte, d'au-dessus de {area:111} jusqu'à {area:916} à l'est. Les gnolls plus au sud et à l'ouest sont de niveau 13-19 : restez dans les collines du nord.\nDes coureurs de la côte et des pillards murlocs bordent la plage au nord de la mine. Ils fuient quand leur vie est basse : attirez-les un par un.\nAttention : les gnolls proches les uns des autres ont tendance à rejoindre le combat en groupe. Il est plus sûr de les attirer un par un.\nAttention : deux Défias montent la garde dans la maison, dont {npc:502}, un nommé de niveau 15. Ils sont liés : attaquer l'un attire les deux.",
	["Sacks of Oats in the fields around the farm"] = "Sacs d'avoine dans les champs autour de la ferme",
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Des pilleurs et des détrousseurs défias tiennent les fermes à l'ouest de {area:108}, entre la route côtière et {area:20}.\nAttention : la grotte de {area:113} contient beaucoup de Défias serrés les uns contre les autres, il est facile d'en attirer plusieurs à la fois.",
	["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "Des rôdeurs et des cogneurs défias arpentent {area:20} ; des bandits de grand chemin (niveau 17) patrouillent par deux dans les collines au sud et à l'est : séparez-les. L'entrée de {area:1581}, dans la forge, est un donjon de groupe.\nAttention : les camps des collines abritent des groupes mêlés de Défias, il est facile d'en attirer plusieurs à la fois si votre niveau est bas.",
	["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171} et {npc:6173} sont dans la cathédrale de la Lumière ; {npc:6174} se tient dans {object:2096} et demande dix {item:2589} (les humanoïdes en lâchent ; l'hôtel des ventes en vend).",
	["Right-click the {item:6775} he gives you"] = "Clic droit sur {item:6775} qu'il vous donne",
	["{npc:6172}, by {area:86} in Elwynn, on the road to Redridge"] = "{npc:6172}, près de {area:86} en Elwynn, sur la route de Les Carmines",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Tant que vous êtes ici : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Tant que vous êtes ici : apprenez les épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait monter un voleur régulièrement.",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton porte plus de caractéristiques de sorts qu'une arme à une main pendant la montée en niveau.",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, sur la plage à l'ouest des quais ; sous l'eau",
	["the Rabid Thistle Bears nearest {npc:3701}"] = "les ours chardon enragés les plus proches de {npc:3701}",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Des babioles du sanctuaire se trouvent dans les récipients au sol de {area:656}, sous {area:2361} : apportez-en une à {area:2362} au nord-ouest, utilisez-la là-bas et parlez à {npc:11799}. Puis revenez en vol à {area:442} depuis {area:2361}.",
	["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347} : remplissez {item:12346} à {object:174795}",
	["Thresher Eyes; underwater"] = "Yeux de batteur ; sous l'eau",
	["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "Deux épaves reposent au fond de la baie au nord de {area:442} ; chacune contient un coffret. Des rampants des récifs et des rampants des marées incrustés bordent ce rivage.\nAttention : les murlocs à l'intérieur des épaves sont serrés et rapides. Ils traversent souvent les parois et les trous de la coque, vous en attirerez donc généralement d'autres.",
	["Scaber Stalks; below ground"] = "Tiges de scabre ; sous terre",
	["The northern Blackwood camp"] = "Le camp nord des Bois-noirs",
	["The furbolg camp south of the {area:456} keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the {item:12347} in your bags (the {item:12346} is filled at the {object:174795}), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the {item:12355} lies in his Demon Bag."] = "Le camp furbolg au sud de {area:456} garde ses réserves de noix, de fruits et de grain près des feux de camp. Avec un échantillon de chaque et {item:12347} dans vos sacs ({item:12346} se remplit à {object:174795}), utilisez le bol près du feu le plus proche de la rivière : il invoque Xabraxxis, le corrupteur satyre, et {item:12355} se trouve dans son sac démoniaque.",
	["By the bonfire closest to the river: summons Xabraxxis"] = "Près du feu le plus proche de la rivière : invoque Xabraxxis",
	["Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time."] = "Attention : si vous attaquez un ourson, les autres et souvent la mère rejoignent le combat ; attendez-vous à en affronter plusieurs à la fois.",
	["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948} est l'ancien du Bosquet ; {npc:270269} et {npc:11218} dorment à côté de lui.",
	["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."] = "{area:450} se trouve sur la côte au sud de la plage de {npc:10323}. Protégez le prospecteur pendant qu'il cherche le fossile.\nAttention : des embusqués surgissent quand il passe à certains endroits : un éclaireur sort de sous la rampe de planches, et d'autres sortent quand il fouille la tente.",
	["Level 18.47"] = "Niveau 18,47",
	["Top up here to level 18.47 before the hand-ins at {quest:952}: they take you to level 19."] = "Montez ici jusqu'au niveau 18,47 avant les rendus de {quest:952} : ils vous amènent au niveau 19.",
	["Level 20"] = "Niveau 20",
	["Top up here to level 20 before the hand-ins at {zone:1453}: they take you to level 21."] = "Montez ici jusqu'au niveau 20 avant les rendus à {zone:1453} : ils vous amènent au niveau 21.",
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}."] = "Retour auprès de {npc:11802} à {area:2361}, puis {npc:11800}, sur place, emmène les druides directement à {area:702}.",
	["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {area:12}."] = "Le bateau de {area:442} accoste à {area:17203}. Montez en ville pour l'entraînement et {npc:1646}, puis sortez par la grande porte et suivez la route vers l'est à travers {area:12}.",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-ashenvale)"] = "Seulement une fois {quest:97914} rendue : pour {npc:3649}, de retour à {area:442} (06-ashenvale)",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez les armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "Volez jusqu'à {area:108} et partez au nord-ouest vers la côte : {object:177790} repose au fond de la mer au large du rivage. Puis prenez la route vers l'est à travers Elwynn jusqu'aux Carmines.",
	["On the road east, past the {area:91}, head north from the bridge to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Sur la route vers l'est, après {area:91}, partez au nord depuis le pont jusqu'à {area:86}. {npc:6172} est étendu au sud du lac : utilisez {item:6866} sur lui. Les sorciers renégats défias autour de lui portent {item:6846}.",
	["Use the {item:6866} on {npc:6172}"] = "Utilisez {item:6866} sur {npc:6172}",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846} : sorciers renégats défias",
	["{npc:266}, by the docks; upstairs"] = "{npc:266}, près des quais ; à l'étage",
	["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "Des bâtards des Carmines et d'autres gnolls tiennent les collines à l'est de {area:1002}, au nord de la route ; des batteurs des Carmines rôdent parmi eux, des braconniers campent au sud de la route. Les brutes des Carmines, pour les piques et les rivets en fer, tiennent les collines plus au nord ; des condors redoutables et de grands broche-tripes parcourent les collines à leur est.",
	["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345} (niveau 24) fouille le sol autour de l'enclos juste à l'ouest de {area:69}. Éloignez-le des autres sangliers et combattez-le avec toute votre vie.",
	["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "Des mangeurs de chair et des mande-flots murlocs bordent la rive sud à l'est du pont. N'importe lequel peut porter {item:1467} ou une nageoire.\nDe grandes tarentules rampent sur les pentes autour du moulin au nord-est du lac.",
	["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite.\nCareful: Two gnoll guards stay with him and join the fight whenever he is attacked, even if he has wandered a short way off; other gnolls stand close by and wander through the area."] = "À l'est après le moulin, de l'autre côté de la rivière. Les gnolls Peau-d'ombre remplissent la vallée ; {npc:703} (26, bien au-dessus de vous) les mène à son extrémité nord : éliminez d'abord son escorte et combattez-le avec toute votre vie. Évitez {area:2099} au sud : ses orcs sont élites.\nAttention : deux gardes gnolls restent avec lui et rejoignent le combat dès qu'il est attaqué, même s'il s'est un peu éloigné ; d'autres gnolls se tiennent près de là et se promènent dans la zone.",
	["Blackrock camps"] = "Camps Rochenoire",
	["South down the valley's east side to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "Descendez au sud par le côté est de la vallée jusqu'aux camps Rochenoire à l'est de {area:2099}. Des renégats, des grunts et des coursiers les remplissent ; restez à l'est du donjon, dont les orcs sont élites.",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest."] = "Suivez la route au sud depuis {area:1002} jusqu'à {area:10} ; {area:42} se trouve à l'est de la forêt.",
	["{npc:265}, in her house by the tavern; inside"] = "{npc:265}, dans sa maison près de la taverne ; à l'intérieur",
	["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "Pas de {item:4371} pour {quest:174} ? {npc:3133} en vend dans la maison à côté de celle de {npc:276}, en stock limité ; {npc:1448} à {area:150} en vend aussi.\nLa maison de {npc:276} se trouve à l'extrémité est du village. {npc:3133} vend des fournitures d'ingénierie dans la maison voisine.",
	["{npc:633}, at the south end of town; inside"] = "{npc:633}, à l'extrémité sud du village ; à l'intérieur",
	["{npc:663}, by the town hall"] = "{npc:663}, près de l'hôtel de ville",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {area:10} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "Des guerriers et des mages squelettes errent parmi les tombes au sud-est de {area:42}, en contrebas de la maison de {npc:302} sur la colline. Chaque squelette de {area:10} peut lâcher {item:2378}.\nAttention : les squelettes étant proches les uns des autres, foncer dans le tas en attire souvent plusieurs à la fois.",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {area:40} border, so you can easily pull several mobs at once."] = "Des loups redoutables enragés parcourent les bois autour du cimetière et de {npc:289}, des loups redoutables affamés les collines au nord-est de lui. Des araignées pygmées venimeuses rampent à l'est du cimetière et lâchent le venin. Chaque goule de la moitié nord du cimetière peut lâcher un croc.\nAttention : des loups et d'autres types d'araignées partagent la zone le long de la frontière de {area:40}, vous pouvez facilement attirer plusieurs monstres à la fois.",
	["Head back east along the road to the {area:245}."] = "Revenez vers l'est par la route jusqu'à {area:245}.",
	["{quest:337}: a rare drop from {area:10}'s mobs"] = "{quest:337} : un butin rare des monstres de {area:10}",
	["Head west along the road once more."] = "Repartez vers l'ouest par la route.",
	["Head back east to {area:42}."] = "Revenez vers l'est jusqu'à {area:42}.",
	["Head west to the hermit once more."] = "Retournez à l'ouest chez l'ermite.",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "Chaque goule de la moitié nord de {area:492} peut lâcher une côte : mangeurs de chair, mâcheurs d'os, propagateurs de peste et mangeurs de cervelle.\nAttention : {npc:948} lance {spell:3428} en mourant, ce qui fait venir des renforts.",
	["Head west along the road out of {area:94} into {area:40}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Prenez la route vers l'ouest pour sortir de {area:94} et entrer dans {area:40}. {npc:7024} surveille la tour de {npc:7053} depuis les collines juste après la frontière. {npc:7051} (niveau 23) qui garde la tour porte sa clé ; le journal de Klaven est dans le coffre au sommet.",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Partez au nord à travers Elwynn jusqu'à {zone:1453} ; Mathias Shaw est au SI:7 dans {object:2100}.",
	["{npc:6173} and {npc:6171} are in the Cathedral of Light."] = "{npc:6173} et {npc:6171} sont dans la cathédrale de la Lumière.",
	["{npc:6171}: Redemption"] = "{npc:6171} : Rédemption",
	["Rogue training"] = "Entraînement du voleur",
	["Train here, in {zone:1453}, before you go on."] = "Entraînez-vous ici, à {zone:1453}, avant de continuer.",
	["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}."] = "Prenez le bateau de {area:17203} à {area:442}. Assemblez les deux moitiés de pendentif en {item:15885} et lancez {spell:18960} : {npc:11802} est à {area:2361}. Puis {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}.",
	["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then head south along the road through {zone:1439}."] = "Depuis {area:17203}, prenez le bateau pour {area:442} ; {npc:3649} se tient à l'extrémité nord du village. Puis partez au sud par la route à travers {zone:1439}.",
	["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649} : la réponse d'Alexston, si vous l'avez prise à {zone:1453}",
	["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {area:331} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {area:413}."] = "Kerlonian dort à {area:448}, dans le sud de {zone:1439}. Utilisez {item:13536} pour le réveiller et conduisez-le au sud par la route jusqu'à {area:331}, auprès de {npc:11219} à {area:413} ; sonnez à nouveau du cor chaque fois qu'il s'endort.\nAttention : des embuscades de trois monstres attaquent le long de la route : des furbolgs sur le tronçon de {zone:1439} et des morts-vivants près de {area:413}.",
	["{object:176634}, beside him"] = "{object:176634}, à côté de lui",
	["Escort Kerlonian to {area:413} in {area:331}."] = "Escortez Kerlonian jusqu'à {area:413} dans {area:331}.",
	["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970} : pour {npc:1480} à Menethil, à la fin de ce guide ; à l'intérieur",
	["The two stand together at the western end of the road.\nSouth of the murlocs, {npc:3585} waits at the {area:416}."] = "Les deux se tiennent ensemble à l'extrémité ouest de la route.\nAu sud des murlocs, {npc:3585} attend à {area:416}.",
	["Head west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Partez à l'ouest vers le rivage de {area:441}. Teronis gît parmi les murlocs Crache-sel ; n'importe quel murloc peut lâcher {item:5463}.",
	["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of {area:415}. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987} (25) mène les furbolgs Crins-de-chardon au camp au nord de {area:415}. Éliminez d'abord ses gardes, un par un.\nAttention : les furbolgs proches de lui le rejoignent généralement quand on l'attire. Tuer d'abord ceux qui sont sur son chemin permet de l'affronter seul.",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell.\nThe moonwell lies in the hills north-east of {area:415}."] = "Suivez la route vers l'est jusqu'à {area:419} ; {npc:3916} se tient près du puits de lune.\nLe puits de lune se trouve dans les collines au nord-est de {area:415}.",
	["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around {area:1276}: the map marks where to look"] = "{npc:210995} ne les propose peut-être pas à toutes les classes ; s'il ne le fait pas, continuez. ; se promène autour de {area:1276} : la carte indique où chercher",
	["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276} creuse dans {area:2160} à l'extrémité est de la falaise. Parlez-lui et repoussez les pillards de la KapitalRisk pendant qu'il mine.\nAttention : les kobolds arrivent par vagues. La première vague est composée de combattants au corps à corps, la seconde ajoute des lanceurs de sorts. Les monstres ordinaires de la mine réapparaissent vite et peuvent rejoindre le combat pendant les vagues. Un groupe est conseillé.",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "Partez au sud après {area:421} dans le tunnel de {area:1276} ; il débouche sur {area:461} des Serres-Rocheuses. {npc:4080} et {npc:4077} campent sur {area:1076} au sud-ouest de la falaise.",
	["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}, dans la hutte au nord d'eux ; à l'intérieur",
	["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in {area:2103}, a short walk from {npc:1242}.\n{npc:2104} stands in {area:2103}."] = "{npc:5082}, Mikhail et Tapoke Jahn sont tous à l'auberge de Menethil ; Tapoke vous attaque quand vous parlez à Mikhail, mais abandonne une fois battu. {npc:1480} se tient à quelques pas au nord-est de l'auberge.\n{npc:2104} se tient à {area:2103}, à quelques pas de {npc:1242}.\n{npc:2104} se tient à {area:2103}.",
	["{npc:1217}, upstairs in the inn"] = "{npc:1217}, à l'étage de l'auberge",
	["{npc:2086}, by the keep; inside"] = "{npc:2086}, près du donjon ; à l'intérieur",
	["{npc:2104}, by the keep"] = "{npc:2104}, près du donjon",
	["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096} : il ne propose pas la 305 tant que vous la portez",
	["{npc:2094} stands by the north gate."] = "{npc:2094} se tient près de la porte nord.",
	["The excavation site sits on the hill south of the road."] = "Le site de fouilles se trouve sur la colline au sud de la route.",
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground"] = "Un nouveau {item:279996}, pour les quatre gardiens titans autour de {zone:1437} ; sous terre",
	["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Pour {npc:2916} à {zone:1455}, à la fin de ce guide",
	["The raptor hills"] = "Les collines des raptors",
	["Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a {npc:1021} drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight."] = "Des raptors tachetés et des hurleurs parcourent les collines à l'ouest du site de fouilles.\nAttention : une fois à 30 % de vie, {npc:1021} appelle à l'aide les créatures à moins de 20 mètres. Les hurleurs tachetés viennent souvent par trois, et les raptors appelés à l'aide peuvent aussi rejoindre le combat.",
	["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244} : {quest:98283}, un raptor élite",
	["Black, Crimson and Monstrous Oozes fill {area:309}, just west of the road to {area:205} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag.\nMosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Des limons noirs, cramoisis et monstrueux remplissent {area:309}, juste à l'ouest de la route de {area:205} et au nord du camp d'Einar. N'importe quel limon peut détenir le sac de {npc:2111}.\nDes coureurs des marais et des tisse-brume Peau-de-mousse parcourent les berges juste à l'ouest et au sud de {npc:1244} ; presque tous lâchent du silex.",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised.\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "Des dragonnets rouges remplissent les collines à l'ouest des portes, des griffes-pourries enragées {area:1025}, des tranchegueules les pentes nord ; Neru se tient au nord-est (utilisez {item:279996}).\n{quest:98283} est élite : un groupe est conseillé.\nDes rampants des marais se cachent dans les mares au nord-ouest de {area:1025}.\nAttention : hors combat, les rampants des marais lancent Camouflage de temps en temps ; ils sont alors furtifs et difficiles à voir.",
	["Menethil"] = "Menethil",
	["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {area:836} before you go on."] = "La quête de {npc:2092} à {zone:1455} demande le niveau 28. S'il vous manque après ces rendus, tuez des orcs Gueule-de-dragon dans les camps le long de la route vers l'est jusqu'à {area:836} avant de continuer.",
	["Head east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "Partez vers l'est par la route de {zone:1437}, au sud à travers {area:836} jusqu'à {zone:1432}, puis à l'ouest par le tunnel jusqu'à {zone:1426} et {area:1537}.",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:199} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Tant que vous êtes ici : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
	["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, à l'entrée nord du village ; se promène autour de {area:42} : cherchez dans le cercle sur la carte",
	["{npc:276}, at the east end of town; inside"] = "{npc:276}, à l'extrémité est du village ; à l'intérieur",
	["Nightbane Shadow Weavers"] = "Tisseurs d'ombre Plaie-de-nuit",
	["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance."] = "Les worgens les plus forts parcourent les bois au sud de {area:42}, à l'ouest et au sud de {area:121}. {npc:511} se cache dans la petite crypte près du cimetière.\nAttention : {spell:8282} dure 10 minutes et ajoute 13 à chaque coup physique que vous subissez.\nAttention : certains worgens devant la grotte se tiennent en groupes, dont un camp de quatre. Pour éviter les renforts, attirez-les un par un depuis la butte près de l'entrée de la grotte.",
	["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, près de la maison de {npc:633} ; à l'intérieur",
	["Head east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Partez vers l'est jusqu'au tertre des ogres. {object:119} se trouve dans le camp à son entrée ; des ogres Poing-éclaté le gardent.",
	["The Defias camp lies in the south-west of {area:10}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "Le camp défias se trouve au sud-ouest de {area:10}, au sud de {area:94} près de la frontière de {zone:1436}. Le coffre-fort se trouve parmi les tentes.",
	["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Les propagateurs de peste arpentent la moitié nord de {area:492}. {npc:522}, un élite, erre parmi les tombes : tenez-vous à l'écart.\nDes pillards, des soigneurs et des gardiens squelettes tiennent la partie ouest du cimetière, juste à l'est du camp de {npc:311}.\nAttention : les squelettes des catacombes sont serrés les uns contre les autres, vous pouvez facilement attirer d'autres monstres.",
	["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight."] = "Suivez la côte vers le nord jusqu'à l'épave. Des marins maudits arpentent la plage, des fusiliers marins maudits le pont ; {npc:1159} se tient sur la plage près de la proue. De grands crocilisques des Paluns rôdent sur la côte juste au nord.\nAttention : des rampants des marais se cachent, furtifs, là où la rivière se divise près du vaisseau fantôme, et peuvent rejoindre un combat.",
	["{item:2658} along the way to {npc:1078} and Whelgar"] = "{item:2658} en allant vers {npc:1078} et Whelgar",
	["{item:2659} along the way to {npc:1078} and Whelgar"] = "{item:2659} en allant vers {npc:1078} et Whelgar",
	["{item:2660} along the way to {npc:1078} and Whelgar"] = "{item:2660} en allant vers {npc:1078} et Whelgar",
	["{item:2661} along the way to {npc:1078} and Whelgar"] = "{item:2661} en allant vers {npc:1078} et Whelgar",
	["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one.\nThe relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nThe Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Les gardiens goaz se tiennent juste à l'ouest du camp de Whelgar : utilisez à côté de l'un d'eux {item:279996} qu'il vous a donné.\nLes reliques se trouvent dans les fouilles elles-mêmes. {npc:1353}, un grand tranchegueule, rôde dans la vallée des raptors juste à l'ouest.\nLes orcs Gueule-de-dragon campent à l'est du site de fouilles. Les pillards et les coureurs des marais portent les bannières de guerre.",
	["Head east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "Repartez vers l'est jusqu'au camp Gueule-de-dragon. Les quatre plans d'attaque se trouvent à {area:1036} ; {npc:2091}, un élite, se tient aussi dans le camp.",
	["{npc:2104}, in {area:2103}; on the top floor"] = "{npc:2104}, à {area:2103} ; au dernier étage",
	["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "Pour la catapulte Gueule-de-dragon, sur la boucle de {zone:1437} du guide suivant",
	["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Sur la route vers le sud à travers {zone:1413}, {npc:6244} campe à l'est de la route, au nord-est de {area:378} ; arrivez par l'est et évitez les gardes de la Horde.",
	["{npc:2104}: for {npc:270637}; on the top floor"] = "{npc:2104} : pour {npc:270637} ; au dernier étage",
	["The next step, {quest:474}, pits you against an elite chieftain: skip it."] = "L'étape suivante, {quest:474}, vous oppose à un chef élite : passez-la.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:2091} est un élite de niveau 32 : la plupart des classes le battent seules au niveau 34, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.\nAttention : des lanceurs d'ombre se tiennent de chaque côté de lui, et au moins un lui est lié : il le rejoint quand on l'attire. Des centurions et des capitaines non élites sont répartis autour de son cercle de tentes.",
	["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Au nord-est jusqu'à {area:1038} : {npc:271338} se tient aux portes (utilisez {item:279996}).",
	["The Villards"] = "Les Villard",
	["{npc:5683} waits north of {area:205} by the {area:880}; {npc:271322} a short walk further north-east."] = "{npc:5683} attend au nord de {area:205}, près de {area:880} ; {npc:271322} à quelques pas plus au nord-est.",
	["{npc:1071} stands in the dwarves' camp."] = "{npc:1071} se tient dans le camp des nains.",
	["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "Suivez la route au sud par le pont jusqu'à {area:205}, côté {zone:1437}, où {npc:1075} attend.",
	["Level 31.23"] = "Niveau 31,23",
	["If you skipped {quest:474}, grind here to level 31.23 to stay on the route's plan."] = "Si vous avez passé {quest:474}, montez ici jusqu'au niveau 31,23 pour rester dans le plan de la route.",
	["Pick up everything in town before heading out. {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Prenez tout ce qu'il y a en ville avant de partir. {npc:2381} et {npc:2438} se tiennent entre le maître de vol et l'auberge, Farren et {npc:2366} à l'auberge, Maleb à l'hôtel de ville.",
	["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Les murlocs Nageoire-déchirée se pressent à {area:295}, au sud-ouest de {area:271}.\nAttention : un camp contient un groupe serré d'oracles qui attaquent tous ensemble.",
	["A report for {object:2117}; inside"] = "Un rapport pour {object:2117} ; à l'intérieur",
	["Off the boat, {npc:251493} is the first you meet, north-west of the flight master."] = "En descendant du bateau, {npc:251493} est le premier que vous rencontrez, au nord-ouest du maître de vol.",
	["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
	["{npc:211033}: only offered once you have handed in library books (the Library Books guide)"] = "{npc:211033} : proposée seulement une fois les livres de la bibliothèque rendus (le guide des livres de la bibliothèque)",
	["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Les satyres Hainefurie tiennent les ruines de {area:603}, à l'est de {area:608}.\nAttention : les voleurs Hainefurie apparaissent furtifs, et les filous Hainefurie peuvent empoisonner avec leurs attaques.",
	["{quest:5741}; on the top floor"] = "{quest:5741} ; au dernier étage",
	["Follow the road west out of {area:415}; {area:413} lies north of it."] = "Suivez la route vers l'ouest pour sortir de {area:415} ; {area:413} se trouve au nord.",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "Depuis {area:415}, partez au nord-ouest dans les collines : {quest:1738} est un arbre lumineux au nord de la route de {area:413}. Si vous avez pris {quest:65602}, {item:190309} se trouve dans une maison parmi les arbres au nord de {area:413} (26,6 ; 22,0). Puis revenez par {area:415} jusqu'à {area:1276}.",
	["The Forsaken's camp lies in the woods south of {area:2358}.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together."] = "Le camp des Réprouvés se trouve dans les bois au sud de {area:2358}.\nDes coffres rouillés se trouvent autour des camps furbolgs Fourré-d'ombre à l'ouest des Réprouvés ; ouvrez-les jusqu'à trouver le pommeau.\nAttention : des Réprouvés non élites d'environ niveau 28-30 gardent le camp. Certains sont furtifs, et ceux autour de la table attaquent souvent ensemble.",
	["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle."] = "{npc:3931} arpente la rive de {quest:1035}, au sud-ouest des coffres ; {object:669176} se trouve au nord du lac, sur le chemin.\nAttention : d'autres monstres, certains sous l'eau, se trouvent près de l'île. Éliminez-les d'abord pour qu'ils ne rejoignent pas le combat quand vous attirez l'oracle.",
	["Insane druids"] = "Druides déments",
	["The three druids stand together at the Forsaken camp south of {area:2358}.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "Les trois druides se tiennent ensemble au camp des Réprouvés au sud de {area:2358}.\nAttention : la tanière abrite beaucoup de monstres qui réapparaissent vite, dont des morts-vivants furtifs et des patrouilles ; d'autres monstres rejoignent donc souvent le combat.",
	["The {object:19901} stands in the satyr camp of {area:430}, further east along the road.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "{object:19901} se dresse dans le camp satyre de {area:430}, plus à l'est sur la route.\nAttention : les voleurs Musc-gangrené de {area:428} sont souvent furtifs, et {area:430} abrite des satyres lanceurs de sorts.",
	["{npc:3696} and his guards camp just east of {npc:3897}.\nCareful: Wolves and spiders roam near the camp and can join a fight. Some of the wolves come in pairs."] = "{npc:3696} et ses gardes campent juste à l'est de {npc:3897}.\nAttention : des loups et des araignées rôdent près du camp et peuvent rejoindre un combat. Certains loups vont par deux.",
	["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} se tient à l'étage supérieur du donjon de Menethil.",
	["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "L'épave de l'Orfraie volante repose dans les hauts-fonds au sud du donjon.",
	["{zone:1455} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{zone:1455} n'a pas de maître des druides : prenez {area:2257} depuis {object:171524} jusqu'à {zone:1453} et entraînez-vous auprès de {npc:5504}.",
	["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Attention : des camps de trolls sont proches de la zone des tigres, et les trolls peuvent rejoindre un combat si vous attirez sans précaution.\nAttention : le nid de raptors contient de jeunes raptors qui rejoignent le combat quand vous attaquez les adultes.",
	["{npc:2495}, by the bank; inside"] = "{npc:2495}, près de la banque ; à l'intérieur",
	["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910} ; à l'étage",
	["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, dans {object:56910} ; à l'étage",
	["{npc:773}, in the tavern; upstairs"] = "{npc:773}, dans la taverne ; à l'étage",
	["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards.\nThe Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Revenez vers le nord ; {area:310} se trouve à l'ouest de la route, au milieu de la jungle. Les basilics à épines cristallines qui y vivent lâchent les éclats.\nLes trolls Scalp-rouge tiennent les ruines sur la côte à l'ouest du camp de Nesingwary.",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "Des réducteurs de têtes se tiennent au fond de l'enceinte ; les commandos rôdent, furtifs, autour d'elle et dans la grotte. Ramassez les pages des Vertes collines quand elles tombent.\nAttention : les commandos kurzen sont de niveau 34-35, non élites, et apparaissent souvent furtifs ; près de la mort, ils utilisent {spell:7964}.",
	["{item:2006}: {object:58}; underwater"] = "{item:2006} : {object:58} ; sous l'eau",
	["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} est le grand bâtiment qui domine le port ; la plupart des donneurs de quêtes sont à ses étages ou sur les quais en contrebas.",
	["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
	["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him."] = "{npc:5476} garde le carrefour à l'ouest du marais. {npc:217412} se tient un peu au nord de lui.",
	["The wrecked caravan lies off the road near Biggs.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "La caravane détruite se trouve à l'écart de la route, près de Biggs.\nAttention : le camp est plein d'Égarés d'environ niveau 38. Ils se tiennent en groupes liés de 2 ou 3, beaucoup lancent des sorts, et ils réapparaissent vite.",
	["Back west through {zone:1430} to {area:42}."] = "Retour vers l'ouest à travers {zone:1430} jusqu'à {area:42}.",
	["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "Le Syndicat tient la ferme au nord-ouest de {area:320}. {npc:217589} rampe dans la ferme : attrapez-en un avec la trousse d'entomologie de {npc:217412}, puis cochez-le.\nAttention : les bandits de grand chemin du Syndicat sont de niveau 30-31 et lancent Camouflage hors combat ; ils sont donc souvent furtifs et difficiles à repérer.",
	["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "Escortez le professeur jusqu'à la plage au nord de la crique et protégez-le pendant qu'il travaille ; les nagas attaquent par vagues.\nAttention : l'embuscade compte deux élémentaires d'eau de niveau 40, insensibles au givre. Si le combat a lieu dans la grotte, le professeur se bat au lieu de travailler et d'autres élémentaires continuent d'apparaître ; retenir les élémentaires à l'entrée de la grotte, loin de lui, lui permet de finir avec seulement les deux premiers à gérer.",
	["{npc:2595}, underwater"] = "{npc:2595}, sous l'eau",
	["{npc:2596}, underwater"] = "{npc:2596}, sous l'eau",
	["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
	["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Revenez sur le pont : Ebenezer gît sous son extrémité côté Arathi.",
	["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Les kobolds Sèche-moustache creusent dans la gorge à l'est de {area:321} (Horde) ; contournez la ville par le nord. Ils lâchent à la fois les grains et le minerai de Krazek.\nAttention : chaque type de kobold s'enfuit chercher de l'aide quand sa vie est basse (kobolds à 30 %, géomètres et creuseurs à 15 %), ce qui peut en attirer d'autres.",
	["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque clé se trouve à l'un des cercles de pierres levées des Hautes-terres : à l'est des éclats, près de {area:320} et à l'ouest. {object:2702} se dresse à l'ouest de {area:320}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires proches du niveau 39 qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : exilés brûlants à l'ouest, exilés tonnants au cercle extérieur, exilés déferlants à l'est.",
	["Head back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "Revenez au nord-est après {area:320} ; {npc:2712} et {npc:2713} campent dans les collines au nord de {area:314}.",
	["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Restez avec {npc:2713} pendant qu'elle s'infiltre dans {area:314} et en revient ; des orcs de la Horde vous attaquent en chemin.\nAttention : les orcs dont la vie baisse s'enfuient. {npc:2713} les suit et peut attirer d'autres monstres : tuez ou ralentissez vite les fuyards.",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Suivez la route au nord pour sortir de {area:271} vers les montagnes. Des lions des montagnes parcourent les pentes ; les membres du Syndicat de {area:280} portent les chevalières, et {npc:2306} arpente le domaine du manoir au nord de la ville.",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "Les tomes se trouvent dans le donjon en ruine à l'ouest de {area:280} ; des mages de l'ombre d'Argus tiennent les ruines.\nAttention : les va-t-en-guerre Brise-échine appellent les alliés à moins de 15 mètres dès qu'ils passent sous la moitié de leur vie.",
	["{item:3659}: the {object:1760}; inside"] = "{item:3659} : {object:1760} ; à l'intérieur",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:2417} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "Attention : les espions et les assassins du Syndicat peuvent être furtifs. Les assassins vous empoisonnent aussi.\nAttention : environ trois membres furtifs du Syndicat sont dans la maison de {npc:2320}. {npc:2320} ne les rejoint pas quand on les attire, et une attaque à distance par la porte le fait sortir seul.",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {area:130}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Au sud-ouest jusqu'au camp du Kirin Tor sur la rive du lac à l'ouest de {area:279}, juste après la frontière de {area:130} : {npc:269127} s'y tient. L'archimage Ansirem se tient au sud-est, près du dôme.",
	["From {zone:1455} take the tunnel east through {zone:1426} into {area:38} and follow the road to {area:144}."] = "Depuis {zone:1455}, prenez le tunnel vers l'est à travers {zone:1426} jusqu'à {area:38} et suivez la route jusqu'à {area:144}.",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {area:3}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Revenez à l'ouest jusqu'à la route et suivez-la au sud pour sortir de {zone:1432} par le col jusqu'à {area:3}. {npc:2910} et {npc:2860} campent côte à côte aux fouilles.",
	["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Partez au nord-est jusqu'aux fouilles abandonnées ; la caisse de fournitures s'y trouve, parmi les ogres Crache-poussière.",
	["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {area:3}."] = "{npc:4618} et {npc:2817} campent ensemble à {area:1877}, au milieu de {area:3}.",
	["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Le squelette abîmé gît juste à l'est des ogres, au bord du camp des troggs de Cave-pierre ; les brise-os et les chamans autour lâchent les éclats. Theldurin est assis près du camp en ruine plus au sud.",
	["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Partez à l'ouest jusqu'à {area:1878} ; {npc:2921} travaille près de ses machines au milieu.",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nThe Lesser Rock Elementals wander the {area:1878} west of {npc:2921}.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Les ogres Crache-poussière campent juste au sud de la vallée ; tous lâchent de la ferraille. Des busards tournent au-dessus de la plaine à l'est.\nLe squelette abîmé gît au bord du camp des troggs de Cave-pierre ; {quest:739}, le meurtrier d'Agmond, se promène parmi les brise-os.\nLes petits élémentaires de roche errent dans {area:1878} à l'ouest de {npc:2921}.\nAttention : les seigneurs Crache-poussière sont de niveau 44-45. Ils utilisent {spell:5242} et {spell:1160}, et sous 50 % de vie ils appellent les alliés à moins de 15 mètres. Sept d'entre eux se tiennent à environ 750 mètres au sud de {area:340}.",
	["The skeleton's next task, {quest:739}, waits until the later {area:3} guide at 43."] = "La tâche suivante du squelette, {quest:739}, attend le guide ultérieur de {area:3}, au niveau 43.",
	["Head north-east to the dwarven ruins in the north of the {area:3}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Partez au nord-est jusqu'aux ruines naines au nord de {area:3} ; le coffre se trouve parmi les nains Sombrefer. {npc:2745}, tout près, est élite : laissez-lui de la place.",
	["Head south to {area:345}."] = "Partez au sud jusqu'à {area:345}.",
	["{npc:1470}, in the inn; below ground"] = "{npc:1470}, dans l'auberge ; sous terre",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Le maître de vol se tient près de la porte de {area:514} ; {npc:5083} et {npc:4964} sont dans la citadelle.",
	["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} est retenue au camp centaure à l'ouest du cimetière. Libérez-la et gardez-la en vie pendant la sortie ; elle s'arrête près du cimetière.\nAttention : les groupes de l'embuscade sont liés et n'apparaissent que pendant l'escorte ; impossible de les éliminer à l'avance ou de les attirer un par un. Éliminer avant de partir les centaures ordinaires sur le chemin aide quand même.",
	["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Les démons se rassemblent à {area:602}, dans le sud de {zone:1443} : des gangrechiens (mangeurs de mana, chasseurs de mages et de lignes telluriques), des vierges et des sœurs du Néant, et des capitaines gardiens funestes autour de la fosse.\nAttention : la plupart des monstres ici suivent des patrouilles, vous pouvez facilement en attirer d'autres.",
	["The next guide starts in Theramore."] = "Le guide suivant commence à Theramore.",
	["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} se tient près de l'auberge ; {npc:4897}, un fournisseur à quelques pas au sud, vend les épices que veut Jarl.",
	["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
	["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "Suivez la route au nord-ouest pour sortir de Theramore jusqu'à la tour de guet de {area:503}. Des fouisseurs de Roche-boue parcourent le marais alentour.",
	["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "De retour à Theramore : Tervosh attend avec dame Jaina dans la tour de {area:514}.",
	["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}, pour « Œil-des-marais » Jarl",
	["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders."] = "{npc:4966} tient la tour avec quelques déserteurs. Il se retourne contre vous : battez-le jusqu'à ce qu'il se rende.\nAttention : Hendel a deux gardes qui rejoignent le combat quand il devient hostile. Les gardes s'enfuient une fois qu'il se rend.",
	["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Les araignées Sombrebrume nichent autour de la caverne au nord-ouest du marais ; toutes lâchent des yeux.\nAttention : les rôdeuses Sombrebrume se déplacent furtivement et empoisonnent une fois en combat. Les araignées sont serrées, les renforts sont donc fréquents ; attirer des cibles isolées depuis le bord extérieur en limite le nombre.",
	["The burned inn stands on the road west, toward the {area:17}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "L'auberge incendiée se trouve sur la route à l'ouest, vers {area:17} ; l'insigne du garde est dans les cendres et les traces de sabots dans la boue à côté de l'auberge.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {area:12}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. {npc:4732} l'enseigne aux humains à {area:88}, dans l'est de {area:12}, à côté des chevaux de {npc:384}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître d'équitation (non confirmé). Le guide Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. Les Célestes l'apprennent auprès de {npc:265756}, maître des écuries et d'équitation à {area:17684}, à {area:16638} sur l'île de Zephras, qui vend aussi les coursiers du vent : le vaisseau volant vers l'île part du côté nord de {area:279} environ toutes les cinq minutes. Le guide Collection, Montures · Niveau 40 liste les coursiers du vent.",
	["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Équitation et coursiers du vent : {npc:265756}, à {area:17684}, à {area:16638} sur l'île de Zephras.",
	["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Vaisseau volant vers l'île de Zephras : côté nord de {area:279}, environ toutes les cinq minutes.",
	["for Stoley in {zone:1446}: keep it; on the top floor"] = "pour Stoley à {zone:1446} : gardez-le ; au dernier étage",
	["for the {area:8} later"] = "pour {area:8} plus tard",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:728} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Les trolls Brise-crâne tiennent les ruines juste à l'est de la mine ; tous peuvent lâcher des défenses, leurs panthères en lâchent toujours.\nSuivez la route au nord-est jusqu'au camp de la KapitalRisk à {area:310} ; les mineurs, les géomètres et les contremaîtres lâchent les cristaux.\nAttention : des panthères Gueule-d'ombre et des tigresses de Strangleronce furtives parcourent les environs du camp.",
	["Level 42.23"] = "Niveau 42,23",
	["If you skipped {quest:193}, grind here to level 42.23 to stay on the route's plan."] = "Si vous avez passé {quest:193}, montez ici jusqu'au niveau 42,23 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:730} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 42.27"] = "Niveau 42,27",
	["If you skipped {quest:196}, grind here to level 42.27 to stay on the route's plan."] = "Si vous avez passé {quest:196}, montez ici jusqu'au niveau 42,27 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:731} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.\nAttention : des tigres et des panthères Gueule-d'ombre furtives rôdent près de lui. Éliminez-les avant de l'attirer. Quand on l'attire, {npc:731} appelle à l'aide les créatures à moins de 20 mètres.",
	["Level 42.33"] = "Niveau 42,33",
	["If you skipped {quest:208}, grind here to level 42.33 to stay on the route's plan."] = "Si vous avez passé {quest:208}, montez ici jusqu'au niveau 42,33 pour rester dans le plan de la route.",
	["Level 42.46"] = "Niveau 42,46",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan."] = "Si vous avez passé {quest:543}, montez ici jusqu'au niveau 42,46 pour rester dans le plan de la route.",
	["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} se tient près du carrefour à l'ouest du marais.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {area:12}. Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. {npc:4753} l'enseigne aux elfes de la nuit à {zone:1457}, à côté des sabres de {npc:4730} : le bateau de {area:17203} à {area:442}, puis le vol jusqu'à {area:702}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître d'équitation (non confirmé), comme {npc:4732} à {area:88} dans {area:12}. Le guide Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["Ride south out of {zone:1432} through the pass into the {area:3}; {npc:2860} camps at the dig."] = "Chevauchez au sud pour sortir de {zone:1432} par le col jusqu'à {area:3} ; {npc:2860} campe aux fouilles.",
	["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} campe seul à {area:1898}, au sud-est du site de fouilles.",
	["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "pour {npc:4454} à {area:439} : le guide de {zone:1446} les croise au niveau 45, gardez-le",
	["Ride west across the {area:3} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Chevauchez vers l'ouest à travers {area:3} jusqu'au camp Crache-poussière de {area:342}. {npc:2944} se tient au milieu, entouré de chasseurs de wyrms et de cogneurs.",
	["Ride north-east out of {area:271} on the road into the {area:47}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Chevauchez au nord-est pour sortir de {area:271} par la route jusqu'à {area:47} ; {area:348} se trouve juste après la frontière. {npc:5635} tient sa cour au sommet, {quest:1450} s'occupe de la volière et {npc:7884} se tient près de l'auberge.",
	["{npc:7744}: the last guide binds here, so this usually ticks at once; below ground"] = "{npc:7744} : le guide précédent vous y fait lier votre pierre de foyer, cet objectif se coche donc généralement aussitôt ; sous terre",
	["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, à côté du maître de vol au sommet ; à l'intérieur",
	["Talonaxe's next task waits for a later {area:47} guide."] = "La tâche suivante de Hache-serre attend un guide ultérieur de {area:47}.",
	["Theramore flight master"] = "Maître de vol de Theramore",
	["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it."] = "{area:1116} se dresse sur {area:1120}, au large de {area:1108} : le bateau du quai de la côte y traverse.",
	["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121} est l'île juste au sud de {area:1120} : traversez à la nage. Des gardes serpents et des ensorceleuses Crête-haineuse la tiennent ; {npc:8136} (niveau 47) attend dans la grotte à son extrémité sud. Attirez d'abord ses gardes.",
	["Feathermoon flight master"] = "Maître de vol de Pennelune",
	["Boat to the {area:1108} and ride east across {area:357} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Bateau jusqu'à {area:1108}, puis chevauchez vers l'est à travers {area:357} jusqu'au camp Totem-sinistre au nord de la route. {npc:7956} attend devant ; libérez les fées-dards de l'enclos au milieu et gardez en vie {npc:7956} et au moins six d'entre elles.",
	["{npc:7765}'s camp"] = "Le camp de {npc:7765}",
	["The {area:2240} lies on the {area:439} in south-east {area:400}. {npc:4454} and {npc:4630} are in the camps beside the track.\n{npc:4709} stands by the goblin camp.\nWhile {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{area:2240} se trouve sur {area:439}, dans le sud-est de {area:400}. {npc:4454} et {npc:4630} sont dans les camps près de la piste.\n{npc:4709} se tient près du camp gobelin.\nPendant que {npc:4709} retient Rizzle en discutant, ses plans restent sans surveillance dans le camp gnome de l'autre côté de la piste.",
	["Ride south-east off the {area:439} into {area:440}. {area:976} is just inside the border."] = "Chevauchez au sud-est en quittant {area:439} vers {area:440}. {area:976} se trouve juste après la frontière.",
	["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, dans la taverne du port ; à l'intérieur",
	["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Chevauchez vers l'ouest en direction de {area:976}. Les bandits et les voleurs Rôdeurs-des-sables tiennent les dunes en chemin ; n'importe lequel peut porter une outre d'eau.\nAttention : les voleurs Rôdeurs-des-sables (niveau 43-44) se déplacent furtivement et peuvent donc approcher sans être vus.",
	["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Les voleurs, les mages de l'ombre et les assassins Rôdeurs-des-sables les plus coriaces campent au sud-est de {area:976}, au sud des bandits. Laissez {npc:7847}, au milieu du camp sud, pour plus tard.\nAttention : les voleurs Rôdeurs-des-sables restent camouflés hors combat ; des voleurs cachés peuvent donc rejoindre un combat engagé dans un camp.",
	["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Suivez la côte vers le sud jusqu'à la crique des pirates. Les pirates de la Voile sanglante se pressent sur la plage et les bateaux : avancez par les bords et attirez-les un par un. {npc:7883} se tient de l'autre côté ; la cargaison volée de {npc:7881} se trouve dans le camp.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville rejoignent le combat dès qu'il commence.",
	["{quest:2873}; upstairs"] = "{quest:2873} ; à l'étage",
	["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Attention : les voleurs lancent Désarmement. Les voleurs restent cachés grâce à Camouflage. Les assassins utilisent Exécution quand votre vie est à 20 % ou moins.",
	["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Chevauchez au nord-ouest jusqu'à la ruche Centipaar dans les dunes. N'importe quel Centipaar peut lâcher des morceaux d'insecte.\nAttention : les essaimeurs Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits renforts qui vous interrompent.",
	["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "Chevauchez au sud jusqu'à {quest:3362}. Les collecteurs de rosée lâchent les glandes ; seules certaines sont pleines, gardez donc la chargée. Des chardonniers noueux et des façonneurs de racines partagent la vallée. Les chardonniers sont de niveau 48-50, au-dessus de vous : attirez-les un par un.\nAttention : les autres monstres chardonniers de la zone sont de niveau 49-50 et se déplacent beaucoup, vous pouvez facilement en attirer d'autres.",
	["{npc:7583}'s next ingredient grows in the {area:47}, and the route never brings it back: skip it."] = "L'ingrédient suivant de {npc:7583} pousse à {area:47}, et la route n'y revient jamais : passez-le.",
	["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Chevauchez au sud-est jusqu'à {area:985}. {npc:7847} se tient au milieu du camp sud des Rôdeurs-des-sables : faites d'abord le ménage autour de lui.\nAttention : deux voleurs Rôdeurs-des-sables furtifs l'accompagnent partout. À son camp d'apparition, deux mages de l'ombre et leurs serviteurs sont assez proches pour rejoindre le combat. Près des tours, vous pouvez l'affronter sans eux.",
	["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Chevauchez au sud après {area:1938} jusqu'à {area:981}, les tunnels Hazzali ; l'équipement de Scrimshank se trouve tout au fond.\nAttention : un insecte garde l'équipement. Beaucoup d'insectes patrouillent dans les tunnels, certains de niveau 50, les combats attirent donc souvent des renforts.",
	["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Chevauchez au sud-est jusqu'à {area:355}, le temple à degrés Vilebranch au sud de {zone:1425}, et grimpez au sommet. Qiaga et {npc:8636} (élite, 50) s'y tiennent : touchez le sommet et redescendez aussitôt.\nAttention : des trolls élites gardent la plate-forme du sommet, dont {npc:7996} et {npc:8636}, avec plusieurs devins Vilebranch. Les devins lancent des sorts et sont liés au reste du groupe.",
	["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Chevauchez au nord jusqu'à {area:351}, au milieu de {zone:1425}. Des vases vertes et des limons de jade rampent tout autour.\nAttention : des panthères se déplacent furtivement dans la zone.",
	["Ride south through the pass into the {area:3}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Chevauchez au sud par le col jusqu'au bord nord de {area:3} : les troggs de Cave-pierre creusent devant {area:1517}. Les urnes sculptées et les touffes de champignons magenta se trouvent dans leurs grottes et tunnels, hors du donjon lui-même.",
	["The bloodmages' camp is the first stop beside the road into the {area:4}, north-west of {area:1438}."] = "Le camp des mages de sang est la première étape au bord de la route vers {area:4}, au nord-ouest de {area:1438}.",
	["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "Chevauchez vers l'ouest : des ricaneurs affamés parcourent les collines sèches juste au sud du camp des mages de sang ; des dards scorpok (niveau 50) trottinent au milieu du nord. Des vautours {npc:5982} tournent au-dessus de tout cela. Attirez-les un par un.\nDes sangliers Crins-de-cendre et des basilics de Roche-rouge partagent les pentes au sud-ouest du donjon. Évitez les sangliers infernaux plus au sud : ils sont de niveau 52.\nAttention : les dards scorpok utilisent {spell:5416} ; {npc:8301} ajoute un renversement.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:1494} (élite de niveau 52) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.\nThe dwarf stands by the road at the dig site. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "Chevauchez vers l'est à travers le Chaudron jusqu'à {area:247} au sud-est. Le prisonnier dans la cabane en bois veut 15 {item:4306} et huit géologues Sombrefer tués sur le site de fouilles alentour. La cabane s'ouvre aussi avec la clé, si vous en avez trouvé une.\nLe nain se tient près de la route au site de fouilles. Une fois terminé, lisez {object:175704} qu'il laisse sur la route à {area:1959}.",
	["Level 48.27"] = "Niveau 48,27",
	["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "Si vous avez passé {item:3985} ou Affronter Negolash, montez ici jusqu'au niveau 48,27 pour rester dans le plan de la route.",
	["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {area:51}. {area:1446} is the scaffolded camp on the north-west rim."] = "Depuis {area:144}, chevauchez au sud jusqu'à {zone:1418}, puis à l'ouest après la ville de la Horde de {area:340} (gardez vos distances) et montez le sentier jusqu'à {area:51}. {area:1446} est le camp aux échafaudages sur le rebord nord-ouest.",
	["The spiders roam the plateaus and lava pools in the south-west of the gorge.\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "Les araignées parcourent les plateaux et les bassins de lave au sud-ouest de la gorge.\nDe lourds golems de guerre patrouillent au fond du Chaudron sous Kalaran ; des élémentaires de magma dérivent parmi eux. Les golems et les élémentaires lâchent l'huile, les élémentaires les cœurs.\nLes maîtres de corvée et les esclavagistes mènent les esclaves partout dans le Chaudron, et n'importe lequel peut porter {item:10551}. Les forgerons à vapeur travaillent aux fourneaux au milieu ({item:18959}), les guetteurs se tiennent sur les crêtes sud (la longue-vue). N'importe quel {object:147516} peut lâcher {item:11818} : gardez-le.\nAttention : les esclavagistes Sombrefer (niveau 45-46) appellent les alliés à moins de 15 mètres quand on les attire, lancent Filet jusqu'à 15 mètres et utilisent Pourfendre au corps à corps.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:14621} est un élite de niveau 50 : la plupart des classes le battent seules au niveau 52, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 48.66"] = "Niveau 48,66",
	["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan."] = "Si vous avez passé {quest:7701}, montez ici jusqu'au niveau 48,66 pour rester dans le plan de la route.",
	["{object:147516} dwarves"] = "Nains {object:147516}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:5860} (élite de niveau 50) demande un groupe de 3. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 48.98"] = "Niveau 48,98",
	["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan."] = "Si vous avez passé {quest:3452}, montez ici jusqu'au niveau 48,98 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:3181} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["For {npc:8256} in {area:1537}, later"] = "Pour {npc:8256} à {area:1537}, plus tard",
	["From {area:392}, fly to {area:976}."] = "Depuis {area:392}, volez jusqu'à {area:976}.",
	["Ride west out of {area:976} to the long ramp down into {area:490}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Chevauchez vers l'ouest pour sortir de {area:976} jusqu'à la longue rampe qui descend dans {area:490}. {npc:9619} campe au pied de la rampe, dans l'angle sud-est du cratère.",
	["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Chevauchez vers l'ouest pour revenir au refuge.\nÉvitez largement les diablosaures et les stégodons élites. Ramassez chaque cristal de pouvoir et chaque {object:157936} que vous croisez à partir d'ici.",
	["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
	["{area:537} and the eastern jungle"] = "{area:537} et la jungle de l'est",
	["{object:161504}, underwater"] = "{object:161504}, sous l'eau",
	["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "Le pylône se dresse sur la pente à l'est du refuge. Des ptérreurdactyles tournent sur les pentes autour : ils comptent pour Spraggle et lâchent les écailles de {npc:9998}.",
	["Level 49.51"] = "Niveau 49,51",
	["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50."] = "Montez ici jusqu'au niveau 49,51 avant les rendus de {area:541} : ils vous amènent au niveau 50.",
	["grind on Pterrordax"] = "tuer des ptérreurdactyles",
	["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "Chevauchez vers l'ouest depuis {npc:9619} : la ruche silithide remplit le sud du cratère. Utilisez la fiole de raclage sur une couveuse, une salle aux larves suspendues. Les guêpes et les ouvriers gorishi lâchent {quest:3764} ; des ptérreurdactyles nichent sur les falaises sud s'il vous faut encore des victimes.\nAttention : les silithides gorishi sont de niveau 51-54 et lancent {spell:8137} ou {spell:14120} au corps à corps ; les ouvriers gorishi ont 50 % de chances d'appeler à l'aide à moins de 25 mètres une fois sous 45 % de vie.",
	["Level 50.4"] = "Niveau 50,4",
	["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51."] = "Montez ici jusqu'au niveau 50,4 avant les rendus de {area:3137} : ils vous amènent au niveau 51.",
	["The shrine lies in the south-west corner of {area:16}, south of {area:3137}."] = "Le sanctuaire se trouve dans l'angle sud-ouest de {area:16}, au sud de {area:3137}.",
	["Swim to the small island off the southern tip of {area:16}: {npc:8392} waits by the monument."] = "Nagez jusqu'au petit îlot au large de la pointe sud de {area:16} : {npc:8392} attend près du monument.",
	["Level 50.89"] = "Niveau 50,89",
	["Top up here to level 50.89 before the hand-ins at {zone:1426}: they take you to level 51."] = "Montez ici jusqu'au niveau 50,89 avant les rendus à {zone:1426} : ils vous amènent au niveau 51.",
	["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} se trouve au sud-est des Steppes, en haut du col qui monte des Carmines.",
	["Level 51.39"] = "Niveau 51,39",
	["Top up here to level 51.39 before the hand-ins at {area:251}: they take you to level 52."] = "Montez ici jusqu'au niveau 51,39 avant les rendus de {area:251} : ils vous amènent au niveau 52.",
	["Level 52"] = "Niveau 52",
	["Top up here to level 52 before the hand-ins at {area:251}: they take you to level 53."] = "Montez ici jusqu'au niveau 52 avant les rendus de {area:251} : ils vous amènent au niveau 53.",
	["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Les reliques sont les pierres sculptées éparpillées dans {area:250} autour de {area:251} : cliquez dessus jusqu'à récupérer les informations.\nLisez la tablette du camp {object:147516} parmi les ruines, au sud-ouest de {area:251}, pour recopier la transcription.\nUtilisez {item:12284} sur {npc:7047} sur les pentes à l'est de {area:251} juste avant sa mort, puis ramassez l'essence qu'il laisse.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:9461} est un élite de niveau 54 : la plupart des classes le battent seules au niveau 56, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 52.08"] = "Niveau 52,08",
	["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan."] = "Si vous avez passé {quest:4022}, montez ici jusqu'au niveau 52,08 pour rester dans le plan de la route.",
	["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176} et les orcs Rochenoire tiennent les camps et la forteresse au pied de {area:254}, à l'ouest de {area:251}. Attirez-les un par un ; chaque orc et chaque worg peut lâcher un médaillon, tuez-en donc jusqu'à en avoir cinquante.\nAttention : {npc:9176} a un garde lié qui rejoint le combat, et un second soldat patrouille tout près ; éliminez la patrouille avant d'attirer.",
	["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%."] = "Kum'isha attend à {area:2517}, la colline au sud-ouest du donjon. Les monstres de {zone:1419} en chemin lâchent les fragments de draenéthyste imparfaits ; apportez-lui ce que vous avez.\nAttention : Felcular, {npc:7664} et Ilifar sont tous des élites de niveau 60. Razelikh lance {spell:2691}, {spell:8255} et Décimer, et à mesure que sa vie baisse il ajoute {object:141891}, {spell:10854} puis Enrager à 15 %.",
	["The Wildkin Feathers lie on the ground across the {area:47}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Les plumes de sauvage gisent au sol à travers {area:47}, au sud et à l'est de {area:348}, là où rôdent les chouettards ; les monstres d'ici sont maintenant bien en dessous de votre niveau.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:7977} (élite de niveau 48) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Ride north out of {area:415} into {area:361}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Chevauchez au nord pour sortir de {area:415} jusqu'à {area:361}. Le furbolg {npc:11554} se tient près de la route juste au sud de {area:2479}.",
	["Level 52.58"] = "Niveau 52,58",
	["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan."] = "Si vous avez passé Le cor de la bête ou {item:9328}, montez ici jusqu'au niveau 52,58 pour rester dans le plan de la route.",
	["{npc:15395} waits at the north end of {area:361}"] = "{npc:15395} attend à l'extrémité nord de {area:361}",
	["Level 52.69"] = "Niveau 52,69",
	["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53."] = "Montez ici jusqu'au niveau 52,69 avant les rendus de {area:1763} : ils vous amènent au niveau 53.",
	["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited."] = "Les satyres Feu-de-jade tiennent le vallon à l'ouest de la route, avec {npc:9454} au fond.\nAttention : les traqueurs de l'ombre Feu-de-jade (niveau 51-52) utilisent Camouflage et {spell:7992} et sont furtifs ; ils rejoignent donc souvent les combats sans y être invités.",
	["{npc:11016}, in {area:1770}; below ground"] = "{npc:11016}, à {area:1770} ; sous terre",
	["Level 52.9"] = "Niveau 52,9",
	["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53."] = "Montez ici jusqu'au niveau 52,9 avant les rendus de {area:2479} : ils vous amènent au niveau 53.",
	["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Les furbolgs Mort-bois de {area:1762} remplissent les collines à l'ouest de la grotte. Les vengeurs peuvent lâcher {quest:8470}.\nAttention : les guetteurs de la tanière sont de niveau 53-54 ; ils appellent les alliés à moins de 25 mètres une fois sous 50 % de vie et s'enfuient chercher de l'aide sous 15 %.",
	["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558} : les Grumegueules ne vous parlent qu'à partir de Neutre ; se promène par ici : cherchez dans le cercle sur la carte",
	["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57; below ground"] = "{npc:11557} : trente {quest:6031}, rendues quand vous repasserez au niveau 57 ; sous terre",
	["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}."] = "Utilisez {item:12922} au puits de lune corrompu au milieu de {area:1763}. Si vous avez libéré {npc:11018}, retournez dans {area:1770} pour la succube {npc:9518}.",
	["Trey Lightforge's remains lie beside her."] = "La dépouille de Trey Forge-lumière gît à côté d'elle.",
	["The vial is filled in {zone:1457}: keep it; inside"] = "La fiole se remplit à {zone:1457} : gardez-la ; à l'intérieur",
	["{npc:11629}: keep it for {area:2262}; inside"] = "{npc:11629} : gardez-le pour {area:2262} ; à l'intérieur",
	["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431} : gardez les deux pour les Maleterres ; à l'intérieur",
	["Level 55.05"] = "Niveau 55,05",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56."] = "Montez ici jusqu'au niveau 55,05 avant les rendus de {area:2255} : ils vous amènent au niveau 56.",
	["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616} : les termites viennent plus tard, à {area:2627}",
	["Follow the southern road east into the {area:139}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Suivez la route du sud vers l'est jusqu'à {area:139} ; les ruines de {area:2262} se trouvent au sud. Le fantôme de {npc:10926} joue près de la maison en ruine à l'extrémité sud.",
	["{quest:5152}, in the {area:28}: keep it"] = "{quest:5152}, à {area:28} : gardez-le",
	["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038} : Zaeldarr est un élite de niveau 54",
	["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, près des tombes au sud de la chapelle",
	["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Zaeldarr est élite : un groupe est conseillé. Il attend au fond de {area:2261}, la crypte au sud-ouest de la zone.",
	["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : {npc:10411} devient invisible hors combat et appelle des gargouilles Aile-de-roche dès qu'un combat commence. Il n'en existe que 3 et elles réapparaissent toutes les 15 minutes.",
	["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Des écorcheurs squelettes et des goules baveuses parcourent les champs au nord du camp ; tout le Fléau d'ici lâche des pierres du Fléau.\nAttention : ces morts-vivants vous repèrent de loin, et les morts-vivants proches rejoignent le combat quand on en attire un.\nAttention : {npc:10411} (3 exemplaires, réapparition en 15 minutes) devient invisible hors combat et appelle des gargouilles Aile-de-roche dès qu'un combat commence.",
	["{object:175924}, in the farmhouse; inside"] = "{object:175924}, dans la ferme ; à l'intérieur",
	["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal.\nSmall lockboxes lie in the rubble all over Andorhal; each holds a watch.\nCareful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "{npc:1852} est élite : un groupe est conseillé. Il garde son phylactère au milieu d'Andorhal.\nDe petits coffrets gisent dans les décombres partout dans Andorhal ; chacun contient une montre.\nAttention : des goules et des squelettes se tiennent généralement près des coffrets et attaquent quand vous approchez. Les goules brûlantes blessent aussi tout ce qui est proche et rompent le camouflage.",
	["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} arpente le camp de Crête-du-nord à l'est de {npc:11610} ; {npc:11611} garde la tour à l'approche sud de {area:190}.\nAttention : des gardes se tiennent au pied de la tour et un autre tourne autour en patrouille. Éliminez-les avant d'engager Durgen pour qu'ils ne rejoignent pas le combat.",
	["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Montez sur la colline à l'ouest de {area:190} pour dominer la ville.\nAttention : les sentinelles postées à la porte détectent les joueurs camouflés. D'autres sentinelles se trouvent en ville, et un élite patrouille tout près.",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.\n{npc:11140} stands by {npc:12384}' hut in {area:2627}."] = "Chevauchez au nord jusqu'à {area:2627}. {npc:12384} vit dans la hutte en ruine, et son carnet de reçus se trouve dans l'auberge en ruine voisine.\n{npc:11140} se tient près de la hutte de {npc:12384} à {area:2627}.",
	["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Traversez la rivière vers l'est jusqu'à {area:2261}, la crypte au sud-ouest de la zone. {object:177667} se trouve à l'intérieur : sa clé est sur {npc:12248}, tout au nord-est, au guide suivant.",
	["The portal in {area:702} leads up to {zone:1457}."] = "Le portail de {area:702} mène à {zone:1457}.",
	["{quest:6762} in {area:493}: keep it"] = "{quest:6762} à {area:493} : gardez-le",
	["Ranshalla in {area:618}: keep it"] = "Ranshalla à {area:618} : gardez-le",
	["{npc:7900}: keep it for {area:440}"] = "{npc:7900} : gardez-le pour {area:440}",
	["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496} : gardez-le pour Un'Goro ; à l'intérieur",
	["{npc:9299} in {area:976}: keep it"] = "{npc:9299} à {area:976} : gardez-le",
	["Walk into {area:1769} and take the {area:493} branch of the tunnel to {area:2361}."] = "Entrez dans {area:1769} et prenez l'embranchement de {area:493} du tunnel jusqu'à {area:2361}.",
	["For {area:1377}: keep it"] = "Pour {area:1377} : gardez-le",
	["On {npc:7583}"] = "Sur {npc:7583}",
	["For {area:3197}: keep it"] = "Pour {area:3197} : gardez-le",
	["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} attend au cimetière juste à l'est de la ville ; la pierre tombale se dresse tout près.",
	["{quest:3444} is in {area:392}"] = "{quest:3444} est à {area:392}",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; J.D.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Volez de {area:976} à {area:541}. La hutte de {npc:8737} se trouve à {area:538}, à l'ouest du refuge ; J.D.\n{npc:9999}, l'ami de {npc:9997}, a disparu.",
	["The wooden sign beside {npc:9997}"] = "Le panneau de bois à côté de {npc:9997}",
	["Ride out of the crater's north-western pass into {area:1377} and on to {area:3425}."] = "Sortez du cratère par le col nord-ouest jusqu'à {area:1377}, puis jusqu'à {area:3425}.",
	["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Des frappeurs dragueurs creusent dans les dunes au nord-ouest du fort ; des scorpides Fouette-pierre et des trotteurs des sables rôdent tout autour.",
	["Level 56.89"] = "Niveau 56,89",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan."] = "Si vous avez passé {item:9328}, montez ici jusqu'au niveau 56,89 pour rester dans le plan de la route.",
	["Follow the road south-west out of the pass to {area:3425}."] = "Suivez la route au sud-ouest en sortant du col jusqu'à {area:3425}.",
	["{npc:17082}, at the Alliance tents"] = "{npc:17082}, aux tentes de l'Alliance",
	["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Les écraseurs dragueurs creusent plus à l'ouest ; des pinces, des écorcheurs Fouette-pierre et des traqueurs des roches chassent dans les mêmes sables.",
	["Ride east to {npc:13220}."] = "Chevauchez vers l'est jusqu'à {npc:13220}.",
	["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Les druides et les sentinelles torturés hantent le village en ruine au sud-ouest de {npc:13220}.",
	["The {area:2742} tower"] = "La tour de {area:2742}",
	["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Chevauchez vers l'est jusqu'à la tour de {area:2742} à {area:2738} ; grimpez-y et tuez les embusqués qui surgissent pour l'objet incrusté.",
	["Umber in {area:493}: keep it"] = "Umber à {area:493} : gardez-le",
	["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "Chevauchez vers l'ouest après {area:541} et descendez le côté ouest jusqu'à {area:543} : le gobelin {npc:10302} est assis au bord de l'eau.",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Chevauchez vers l'est jusqu'à {area:537}, grimpez-y et utilisez {npc:10541} aux bouches de lave près du sommet.",
	["Ends with {npc:9298} in {area:618}: keep it"] = "Se termine auprès de {npc:9298} à {area:618} : gardez-le",
	["Collie is up the hill behind it."] = "Collie est en haut de la colline derrière.",
	["The crater"] = "Le cratère",
	["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Des bêtes de goudron se vautrent dans {area:538} ; les élémentaires de feu de {area:537}, au milieu, portent la cendre ; les guêpes gorishi de {area:540}, au sud, portent la glande. Toutes les créatures du cratère peuvent lâcher {item:11018}.\nAttention : les ouvriers gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide les alliés à moins de 25 mètres.",
	["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Descendez la rampe dans le cratère : {npc:9619} campe en bas.",
	["The pelts come after loop 2, on the gorilla plateau"] = "Les peaux viennent après la boucle 2, sur le plateau des gorilles",
	["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Les gorilles vivent à {area:1943}, à l'est de {area:541}. Gardez leurs peaux pour {npc:9619}. Évitez la grotte la plus profonde : {npc:9622} est de niveau 55.\nAttention : les gorilles d'Un'Goro (niveau 50-51) appellent les alliés à moins de 20 mètres une fois à 25 % de vie. La zone contient une grotte pleine de singes, et y combattre attire beaucoup de renforts.",
	["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Chevauchez au nord par le côté est jusqu'au plateau des gorilles. {npc:9622}, un gorille de niveau 55, se tient dans la grotte la plus profonde : éliminez d'abord les gorilles à l'entrée de la grotte.",
	["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Le repaire de {npc:9684} se trouve dans la jungle au nord de {npc:9619}, au pied des falaises est : utilisez-y {item:11568}. {npc:9684} est de niveau 56 : commencez avec toute votre vie.",
	["Cross the south of the crater to {npc:9619} by the ramp."] = "Traversez le sud du cratère jusqu'à {npc:9619}, près de la rampe.",
	["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} est assis sur la pente sud-est de {area:537}, au milieu du cratère.",
	["Escort {npc:9999}"] = "Escortez {npc:9999}",
	["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Conduisez {npc:9999} au nord jusqu'à {area:541}. Quand il s'évanouit, utilisez {item:11804} sur lui pour le réveiller.",
	["Ride back to {area:3425} and fly to {area:392}."] = "Revenez à {area:3425} et volez jusqu'à {area:392}.",
	["Take the {area:2257} to {zone:1455}."] = "Prenez {area:2257} jusqu'à {zone:1455}.",
	["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Prenez le bateau de {area:392} à {area:35} et volez jusqu'à {zone:1453}.",
	["{npc:3520}, who walks the canals"] = "{npc:3520}, qui arpente les canaux",
	["For {npc:10778}: keep it"] = "Pour {npc:10778} : gardez-le",
	["{npc:332}, in SI:7"] = "{npc:332}, au SI:7",
	["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} à {area:3197} : gardez-le",
	["Its jars are filled on the next Un'Goro visit"] = "Ses bocaux se remplissent lors du prochain passage à Un'Goro",
	["{npc:14724}, by the tram"] = "{npc:14724}, près du tram",
	["Ride on north to {area:3197} and fly to {area:2268}."] = "Continuez au nord jusqu'à {area:3197} et volez jusqu'à {area:2268}.",
	["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Des champions du Fléau (59) parcourent {area:2270}, au nord de {area:2268}. Passez {item:13156} de {npc:11063} au-dessus de chacun de ceux que vous tuez : les crânes qui résonnent sont ceux qu'il veut. Attirez-les un par un.",
	["{item:13155}, from the Scourge Champions"] = "{item:13155}, sur les champions du Fléau",
	["Chromie in Andorhal: keep it"] = "Chromie à Andorhal : gardez-le",
	["Ride north to the {area:2277}'s north-eastern edge.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Chevauchez au nord jusqu'au bord nord-est de {area:2277}.\nAttention : les trolls le long du chemin vers {area:2273} sont de niveau 57-59. Ils s'enfuient quand leur vie est basse et appellent à l'aide, ils ramènent donc souvent des renforts.",
	["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Chevauchez au sud-ouest jusqu'à {area:2261}. Le tas de terre se trouve à l'intérieur. {npc:11886} est élite : un groupe est conseillé.\nAttention : environ quatre renforts non élites arrivent avec Mercutio. Ils marchent jusqu'à la tombe au lieu d'apparaître sur place.",
	["{zone:1451}, {area:361}, {area:618} & the Plaguelands"] = "{zone:1451}, {area:361}, {area:618} et les Maleterres",
	["Ride north out of {area:415} into {area:361} to the druids' camp on the road just past the border."] = "Chevauchez au nord pour sortir de {area:415} jusqu'à {area:361}, au camp des druides sur la route juste après la frontière.",
	["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "{area:1770} est la grotte au fond de {area:1763}, à l'ouest de la route. Utilisez {item:12906} sur les quatre braseros à l'intérieur. Tuez les ours Griffe-colère et les loups Gangrepatte que vous croisez pour {item:11172}.\nAttention : des monstres du Conseil des ombres de niveau 53-55 remplissent la grotte et viennent souvent en grands groupes liés, beaucoup avec des étourdissements. Un groupe de 2 ou 3 joueurs est conseillé.",
	["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive.\nCareful: Three {quest:5086} ambush you soon after the escort starts."] = "{npc:9598} attend à {area:1767}. Escortez-la hors des bois et gardez-la en vie.\nAttention : trois {quest:5086} vous tendent une embuscade peu après le début de l'escorte.",
	["{object:176091}, if you found the Firewater flask in {area:618}"] = "{object:176091}, si vous avez trouvé la flasque d'eau-de-feu à {area:618}",
	["{quest:5085}: {npc:9298} in {area:618}, keep it"] = "{quest:5085} : {npc:9298} à {area:618}, gardez-le",
	["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "Retournez dans {area:1770} : {npc:9861} et {npc:9860} gardent {npc:9517} dans la salle la plus profonde.\nAttention : les trois chefs combattent ensemble. Tuez d'abord les monstres proches pour ne pas attirer d'ennemis en plus.",
	["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Grimpez sur {area:537} au milieu du cratère et utilisez {item:14644} près du lac de lave au sommet, avec deux barres de thorium dans vos sacs. Remplissez les bocaux à échantillon pur vides de {npc:9616} sur les limons primordiaux des mares autour de la crête.",
	["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} campe devant {area:2743}, la ruche ouest. Ramassez de la silithyste à l'un des geysers rouges tout près et apportez-la à l'extracteur de l'Alliance de son camp.\nAttention : vous perdez la silithyste si vous montez en selle, vous camouflez, utilisez {spell:642}, {spell:5384} ou Disparition. Transfert et {spell:17} ne la font pas tomber.",
	["Fly to {area:3137} in {area:16} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Volez jusqu'à {area:3137} à {area:16} et chevauchez vers l'ouest par la route jusqu'à {area:2358}, juste après la frontière de {zone:1440}.",
	["{npc:10300} waits at {area:2250}, south of {area:2255}.\nProtect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "{npc:10300} attend à {area:2250}, au sud de {area:2255}.\nProtégez {npc:10300} pendant qu'elle allume les torches en chemin vers {object:177404}.",
	["{npc:10300}: her escort comes later on the route"] = "{npc:10300} : son escorte vient plus tard sur la route",
	["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Suivez les indications de {npc:9298} jusqu'à l'entrée de {area:2256}, après les géants Cognegivre : passez-les un par un.",
	["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw; walks around here: look inside the circle on the map"] = "{npc:11558}, juste à l'entrée de la grotte : seulement à partir de Neutre avec les Grumegueules ; se promène par ici : cherchez dans le cercle sur la carte",
	["{npc:11557}, if you have thirty {quest:6031}; below ground"] = "{npc:11557}, si vous avez trente {quest:6031} ; sous terre",
	["The western Winterfall furbolgs drop the beads.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Les furbolgs Tombe-hiver de l'ouest lâchent les perles.\nAttention : le rendu fait apparaître trois ou quatre embusqués Tombe-hiver de niveau 56-57 qui vous attaquent ; vous pouvez leur échapper en monture, camouflé ou avec {spell:5384}, et ils se regroupent ensuite près du lac, ce qui vous permet de prendre la quête suivante.",
	["Take the {area:1769} tunnel from its {area:618} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Prenez le tunnel de {area:1769} depuis son entrée côté {area:618}, à l'ouest de {npc:9298}, et suivez l'embranchement de {area:493} jusqu'à {area:2361}. {npc:11939} étudie sur la rive du lac.",
	["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {quest:6031}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722} prend soixante étoffes de soie, soixante de tisse-mage et soixante {quest:6031} : rendez ce que vous portez (ou achetez à l'hôtel des ventes), passez le reste.",
	["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest.\nCareful: Jadefire Shadowstalkers are level 51-52 and move stealthed. They use {spell:7992} and are found about 550 yd south of {area:1997}.\nCareful: Jadefire Shadowstalkers sneak around and use {spell:7992}."] = "Prenez {area:2257} jusqu'à {zone:1455}. {npc:14724} et {npc:14723} prennent chacun soixante étoffes de laine, soixante de soie et soixante de tisse-mage, puis soixante {item:14047} : rendez ce que vous portez (ou achetez à l'hôtel des ventes), passez le reste.\nAttention : les traqueurs de l'ombre Feu-de-jade sont de niveau 51-52 et se déplacent furtivement. Ils utilisent {spell:7992} et se trouvent à environ 550 mètres au sud de {area:1997}.\nAttention : les traqueurs de l'ombre Feu-de-jade se faufilent et utilisent {spell:7992}.",
	["Sixty {item:2592}, if you carry them"] = "Soixante {item:2592}, si vous en portez",
	["Running {area:2057} ({area:2298}, south-east {area:28}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Faire {area:2057} ({area:2298}, sud-est de {area:28}) ou {area:2279} en groupe au lieu de tuer des monstres vous y amène plus vite. Passez cette étape pour monter seul.",
	["{npc:912}, the warrior trainer; inside"] = "{npc:912}, le maître des guerriers ; à l'intérieur",
	["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, à la porte de {area:77} ; à l'intérieur",
	["{npc:836}, inside {area:77}; below ground"] = "{npc:836}, dans {area:77} ; sous terre",
	["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, à la porte en sortant ; à l'intérieur",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "Suivez la route par le tunnel puis au nord-est jusqu'à {area:131}. Commencez dehors : {npc:1252} et le feu de camp d'Eric sont devant {area:2102}.",
	["Sit by Eric's campfire (type /sit) and wait for the buff."] = "Asseyez-vous près du feu de camp d'Eric (tapez /assis) et attendez l'amélioration.",
	["{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "{npc:1872} travaille à la forge à l'ouest de la distillerie.\nPuis entrez : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez les pièces de cuivre.",
	["Last: some classes' trainers stand outside"] = "Enfin : certains maîtres de classe se tiennent dehors",
	["{npc:1694}, beside him"] = "{npc:1694}, à côté de lui",
	["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "Gretchen campe juste devant {area:136}, la grotte des wendigos au sud-ouest de {area:131}.",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Les cargaisons de Flintfire gisent au sol de la grotte, et {object:460004} a disparu quelque part à l'intérieur.\nAttention : les wendigos sont serrés dans la grotte, les combats en attirent donc facilement plusieurs ; les attirer un par un avec des attaques à distance depuis l'extérieur l'évite.",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785} se trouve à côté de {npc:271546}, au sud de {area:136}.",
	["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243} campe au sud-ouest, près de la route de Frigèbre.",
	["{item:2894}, from {npc:1247}; upstairs"] = "{item:2894}, auprès de {npc:1247} ; à l'étage",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Tuez les sangliers des rochers en chemin : leurs côtes tombent avant que vous ayez la quête de {npc:1267} et comptent pour elle. De retour à la distillerie : {npc:1699} enseigne {skill:185}, puis les côtes vont à {npc:1267}.",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699} : Le camping pour les nuls vous demande de l'apprendre ; sous terre",
	["{npc:1269}, by the depot; below ground"] = "{npc:1269}, près du dépôt ; sous terre",
	["{area:137} sits on the lake west of {area:131}. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "{area:137} se trouve sur le lac à l'ouest de {area:131}. Le quai de {npc:8508} est le premier arrêt ; {npc:1374} et {npc:1375} sont dans le village au-delà.",
	["{npc:8508}, on the dock"] = "{npc:8508}, sur le quai",
	["{npc:1196}, on the way to the Hold"] = "{npc:1196}, en allant au fort",
	["{npc:1127}, on the way"] = "{npc:1127}, en chemin",
	["{npc:1201}, on the way"] = "{npc:1201}, en chemin",
	["{area:135} is the troll cave in the hills south-west of {area:137}. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} est la grotte des trolls dans les collines au sud-ouest de {area:137}. Les ours Griffe-de-glace, les vieux sangliers des rochers et les léopards des neiges tués en chemin comptent pour {npc:1374}. Tuez les chasseurs de têtes à l'entrée et traversez jusqu'au fond.",
	["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373} garde les tonneaux de {item:2686} dans la cave de la distillerie. Achetez {item:2686} auprès de {npc:1247}, cliquez sur le tonneau gardé, puis donnez la bière à {npc:1373} depuis sa fenêtre de quête (il n'y a pas de quête à accepter) ; ensuite, le tonneau non gardé donne {spell:8553}.",
	["{npc:1252}: {npc:1274} in {zone:1455} takes it"] = "{npc:1252} : {npc:1274} à {zone:1455} le prend",
	["{item:2686}, from {npc:1247} in the distillery; upstairs"] = "{item:2686}, auprès de {npc:1247} dans la distillerie ; à l'étage",
	["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}, à côté du tonneau ; sous terre",
	["The {object:270} in the distillery; below ground"] = "{object:270} dans la distillerie ; sous terre",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676} pousse dans des paniers en haut de {area:802}, la pente enneigée au nord de la route entre {area:131} et Brewnall : grimpez depuis la route à l'ouest de {area:131}. Les voyants Crins-de-givre qui campent sur la crête en lâchent aussi.",
	["{npc:1266} camps in {area:801}, south of the road back east from Brewnall to {area:131}. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266} campe à {area:801}, au sud de la route qui revient de Brewnall vers {area:131} à l'est. Ses viandes sont dans le garde-manger de la grotte de {npc:1271}, à l'est de son camp. {npc:1271} est un yéti élite : attendez hors de vue qu'il parte en patrouille, puis prenez les viandes et repartez avant son retour. Inutile de le combattre.",
	["{item:2667}: the meat locker; below ground"] = "{item:2667} : le garde-manger ; sous terre",
	["Back east through {area:131}: the class quests here wait for level 10."] = "Retour à l'est par {area:131} : les quêtes de classe d'ici attendent le niveau 10.",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "Suivez la route au nord-est depuis {area:131} jusqu'au dépôt : tout l'est de {area:1} se fait d'une traite à partir d'ici.",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Les trois fusils gisent dans la neige autour du lac gelé près du refuge. Des petits élémentaires de glace dérivent autour du lac et en chemin : tuez-les au passage pour {quest:99160}.\nFinissez les petits élémentaires de glace autour du petit lac juste à l'ouest du refuge s'il vous en manque.",
	["{npc:276003}, around the small lake"] = "{npc:276003}, autour du petit lac",
	["The quarry lies just east of Farsen's ridge."] = "La carrière se trouve juste à l'est de la crête de Farsen.",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Les embusqués Mâchoire-de-roche près de {area:212}, au nord de la carrière, et les brise-échines Mâchoire-de-roche plus à l'est lâchent {quest:95214}. Les brise-os Mâchoire-de-roche rôdent dans la carrière et près du lac ; des espions Sombrefer se faufilent sur la rive du lac. Un espion lâche {item:274268}.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:1388} est un élite de niveau 12 : la plupart des classes le battent seules au niveau 14, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["On the road back west to {zone:1455}."] = "Sur la route du retour vers l'ouest jusqu'à {zone:1455}.",
	["Level 11.6"] = "Niveau 11,6",
	["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "Si vous avez passé {quest:314}, montez ici jusqu'au niveau 11,6 pour rester dans le plan de la route.",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "Suivez la route tout à l'est jusqu'à {area:806}, au tunnel de {area:38}.",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Passez le tunnel jusqu'à {area:38}. Juste après, un chemin balisé de pierres monte dans les collines à droite de la route, au nord, jusqu'au camp de {npc:257808}.",
	["{npc:1960} waits at the {area:808}, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960} attend à {area:808}, au nord de la porte Sud ; le cadavre du nain gît en haut du col, à l'ouest de lui.",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "Au lieu de remonter à pied jusqu'à {area:1537}, passez par le tunnel de la porte Sud vers l'est jusqu'à {area:38} et suivez la route au nord jusqu'à {area:144}. {npc:1681} se tient à l'est de la ville, après {area:2101} ; sa course paie un vol de retour vers {area:1537}.",
	["{npc:1572}, the gryphon master"] = "{npc:1572}, le maître des griffons",
	["{npc:1573}, the gryphon master where you landed"] = "{npc:1573}, le maître des griffons là où vous avez atterri",
	["Inn and flight master"] = "Auberge et maître de vol",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, {npc:6179} et {npc:6178} à son étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Ressortez de {zone:1455} et prenez la route vers l'est jusqu'à {area:212}. {npc:6177} gît mort sur la rive : utilisez {item:6866} sur lui. Les espions Sombrefer qui se faufilent autour du lac portent le texte.",
	["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090} est dans {object:32390}, {npc:258785} dans {object:32386}, {npc:6120} dans {object:32383}.",
	["{npc:270459} in {zone:1416}; {area:1} has no druid trainer"] = "{npc:270459} à {zone:1416} ; {area:1} n'a pas de maître des druides",
	["{npc:1274}, in the {object:171709} with King Magni"] = "{npc:1274}, dans {object:171709} avec le roi Magni",
	["{npc:376} is in the Cathedral of Light."] = "{npc:376} est dans la cathédrale de la Lumière.",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "Retour auprès de {npc:6122}. Utilisez {item:6928} au cercle d'invocation de la cave de {object:2164} et battez le marcheur du Vide qu'il appelle. {area:40} est la suite, à l'ouest de {area:87}.",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}.\n{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "Suivez la route par le tunnel puis au nord-est jusqu'à {area:131}. Commencez dehors : {npc:1252} et le feu de camp d'Eric sont devant {area:2102}.\n{npc:1872} travaille à la forge à l'ouest de la distillerie.\nPuis entrez : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez les pièces de cuivre.",
	["Level 11.41"] = "Niveau 11,41",
	["If you skipped {quest:314}, grind here to level 11.41 to stay on the route's plan."] = "Si vous avez passé {quest:314}, montez ici jusqu'au niveau 11,41 pour rester dans le plan de la route.",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, Tiza et Muiredon à son étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {area:40}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la grande porte. La cascade de {quest:1861} se trouve au sud-ouest des portes, sur le chemin de {area:40} à l'ouest : remplissez {item:7207} à son pied.",
	["{npc:247229}, in the library; inside"] = "{npc:247229}, dans la bibliothèque ; à l'intérieur",
	["{npc:911}, the warrior trainer; inside"] = "{npc:911}, le maître des guerriers ; à l'intérieur",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:248362} (élite de niveau 3) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 5.48"] = "Niveau 5,48",
	["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, montez ici jusqu'au niveau 5,48 pour rester dans le plan de la route.",
	["Level 5.77"] = "Niveau 5,77",
	["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, montez ici jusqu'au niveau 5,77 pour rester dans le plan de la route.",
	["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Asseyez-vous (/assis) près de son feu de camp jusqu'à obtenir {spell:1229451}",
	["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306} : pour les dépeceurs seulement, les peaux se dépècent ; à l'intérieur",
	["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430} : Le camping pour les nuls vous demande de l'apprendre ; sous terre",
	["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La ferme des Champierreux se trouve à l'ouest de la mine. M'man et « tante » Bernice se tiennent près de la maison.\nElle est assise dans la ferme.",
	["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} pousse dans les champs autour des vignes et de la ferme des Champierreux ; les sangliers Rochefendre alentour donnent le sang.\nLes sangliers Rochefendre broutent entre les vignes et la ferme.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:248464} (élite de niveau 6) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 8.39"] = "Niveau 8,39",
	["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Si vous avez passé {quest:91775}, montez ici jusqu'au niveau 8,39 pour rester dans le plan de la route.",
	["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} à {zone:1426} ; {area:87} n'a pas de maître des chamans",
	["{npc:270459} in {zone:1416}; {area:87} has no druid trainer"] = "{npc:270459} à {zone:1416} ; {area:87} n'a pas de maître des druides",
	["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. {npc:248278} roams the murloc shore along the river too: right-click the head it drops. {npc:248278} is elite: grouping up is advised."] = "{item:247813}, la hache et la boîte à outils gisent dans la rivière au sud du pont. {npc:330}, une grosse laie, fouille le sol dans {area:62} à l'ouest de la rivière avec ses {npc:390} : éloignez d'abord les marcassins. Tuez des rôdeurs et des jeunes ours des forêts en chemin. {npc:248278} parcourt aussi la rive des murlocs le long de la rivière : faites un clic droit sur la tête qu'il lâche. {npc:248278} est élite : un groupe est conseillé.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:91740} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 8.85"] = "Niveau 8,85",
	["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Si vous avez passé {quest:91740}, montez ici jusqu'au niveau 8,85 pour rester dans le plan de la route.",
	["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Suivez la route vers l'est après {area:91} jusqu'au pont. Finissez les rôdeurs et les jeunes ours des forêts autour de la rivière au sud.",
	["{npc:240}, while William brews"] = "{npc:240}, pendant que William fait son infusion",
	["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377} : {npc:376} à {zone:1453} prend les deux",
	["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Des avortons et des coursiers Rivepatte tiennent les collines au sud de la garnison, le long de la frontière de {zone:1436}.",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, à côté d'elle : {spell:5149}",
	["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955} : il veut votre {item:247824} ; à l'intérieur",
	["{npc:1984} along the way to Back at {area:256}"] = "{npc:1984} en allant vers Retour à {area:256}",
	["{npc:3593}, the warrior trainer; inside"] = "{npc:3593}, le maître des guerriers ; à l'intérieur",
	["{npc:3595}, the priest trainer: in at the tree's front entrance and up the ramp"] = "{npc:3595}, la maîtresse des prêtres : entrez par l'entrée principale de l'arbre et montez la rampe",
	["{npc:3595}: in at the tree's front entrance and up the ramp; upstairs"] = "{npc:3595} : entrez par l'entrée principale de l'arbre et montez la rampe ; à l'étage",
	["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979} : lancez {spell:1259799} et Camouflage dans l'ombre, puis rendez-la à {npc:3595}",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside."] = "Des sabres-de-nuit galeux et des sangliers des chardons parcourent le nord de {area:256}, sur le chemin de la grotte. {npc:1994} se tient tout au fond.",
	["{npc:8584} waits in the trees west of the cave mouth."] = "{npc:8584} attend dans les arbres à l'ouest de l'entrée de la grotte.",
	["Webwood Spiders; below ground"] = "Araignées Tisse-bois ; sous terre",
	["The moonwell sits north of {area:256}."] = "Le puits de lune se trouve au nord de {area:256}.",
	["{npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "{npc:8584} est un peu plus au nord-ouest. {quest:3522} dure cinq minutes : remplissez la fiole et allez directement le voir.",
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/assis près du feu de camp de {npc:265811} jusqu'à obtenir {spell:1229451}",
	["{npc:6286}, south of the inn: Camping 101 asks you to learn it"] = "{npc:6286}, au sud de l'auberge : Le camping pour les nuls vous demande de l'apprendre",
	["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "Des sabres-de-nuit, des chouettes strigides et des rôdeuses Tisse-bois parcourent les environs de {area:186} et la route vers l'est ; les rôdeuses lâchent aussi les pattes d'araignée de la recette. Le puits de lune est au bord ouest de {area:260}.",
	["North from the lake to {npc:2150}, on the road back to {area:186}."] = "Au nord depuis le lac jusqu'à {npc:2150}, sur la route du retour vers {area:186}.",
	["{npc:2107} stands in the village, east of the moonwell. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} se tient dans le village, à l'est du puits de lune. {object:126158} est dans la maison sur la colline à l'extrémité est du village.",
	["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Au sud-ouest de Brise-étoile, au sud de {npc:2150}. {npc:2080} soigne ses jeunes arbres sur la rive ; des pousses de fouetteur et des sylvains errent autour de lui, et {quest:919} pousse parmi eux.",
	["{npc:7318}, in the den; walks around {area:736}: look inside the circle on the map"] = "{npc:7318}, dans la tanière ; se promène autour de {area:736} : cherchez dans le cercle sur la carte",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Des pommes de gangrepin gisent sous les arbres tout autour de {area:186} et de {npc:2150} : ramassez-les sur la route de l'est et donnez-les à {npc:2150} en allant voir {npc:7234}.",
	["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Les mystiques Pin-tordu et {npc:7234} campent au nord-est de {area:260}. {npc:7234} lâche {item:8049} : ouvrez-le pour le joyau.\nAttention : {npc:7234} attend près du feu de camp, entouré de mystiques ; difficile de l'attirer sans renforts.",
	["The Bloodfeather harpies nest on the slopes west and north of the glade.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Les harpies Plume-sanglante nichent sur les pentes à l'ouest et au nord de la clairière.\nAttention : les harpies sont serrées, d'autres rejoignent donc souvent le combat. Des lanceuses de sorts sont mêlées aux autres.",
	["Use the {item:18152} at the moonwell"] = "Utilisez {item:18152} au puits de lune",
	["the same {object:673378}: Fandral in {zone:1457} takes it"] = "le même {object:673378} : Fandral à {zone:1457} le prend",
	["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Descendez au sud par le côté ouest de l'île. Ursal rôde tout au sud, sous {area:478}.\nAttention : des Pin-tordu d'environ niveau 9-12 remplissent le camp, serrés les uns contre les autres ; il est facile d'en attirer plusieurs à la fois. Affrontez-les un par un avant d'engager Ursal.",
	["{npc:3598}, the warrior trainer: {quest:1684} in {zone:1457} takes it"] = "{npc:3598}, le maître des guerriers : {quest:1684} à {zone:1457} le prend",
	["{npc:3567}, back in {area:186}; upstairs"] = "{npc:3567}, de retour à {area:186} ; à l'étage",
	["{npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "{npc:6094} prend {item:159} avec les frondes et la fiole : si vous avez bu la vôtre, achetez-en une autre auprès de {npc:6736} dans cette auberge avant de rendre.",
	["{quest:1684} stands on the {area:1660}, just inside the city."] = "{quest:1684} se tient sur {area:1660}, juste à l'entrée de la ville.",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Ressortez par la porte de la ville et prenez la route vers l'est : {quest:1683} se tient au sud, près de {area:736}. Rapportez son cor à {quest:1684}.",
	["{npc:4088}, on the {area:1660}: {spell:71}"] = "{npc:4088}, sur {area:1660} : {spell:71}",
	["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, à {area:1658} : {spell:5149}",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; un bâton porte plus de caractéristiques de sorts qu'une arme à une main pendant la montée en niveau.",
	["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Prenez le portail qui descend à {area:702}. {npc:10118} se tient sur le quai, {npc:3838} près des hippogriffes. Une fois {quest:6342} obtenue, reparlez à {npc:3838} et choisissez le vol vers {area:442} : il est gratuit et atterrit à côté de {npc:4200}. Si la carte des vols s'ouvre à la place, fermez-la et reparlez-lui en maintenant Maj.",
	["talk to {npc:3838} again: free with {quest:6342}"] = "reparlez à {npc:3838} : gratuit avec {quest:6342}",
	["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Apprenez la route aérienne auprès de {npc:3841} à l'atterrissage. L'étal de poissons de {npc:4200} est juste au nord d'elle, près des quais.\nLe bateau accoste à l'ouest du village. Le maître de vol se tient sur la colline au sud de l'auberge ; les donneurs de quêtes sont répartis le long de la rue principale.",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442} for the boat."] = "Revenez en vol à {area:702} depuis {npc:3841}, donnez {item:16263} à {npc:10118} sur le quai, puis revolez jusqu'à {area:442} pour le bateau.",
	["Tide Crawlers scuttle along the shore below the village; {object:17182} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Des rampants des marées trottinent sur le rivage sous le village ; {object:17182} se dresse sur la plage juste au sud des quais. Des batteurs de Sombrivage nagent dans les hauts-fonds. {object:175207} se trouve sur le rivage juste au sud du village.",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; {quest:5929} se trouve dans les bois au nord-ouest. Puis {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}, sans route aérienne.",
	["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "{npc:10118} se tient sur le quai de Rut'theran où vous atterrissez. Puis prenez le portail qui monte auprès de {npc:4217} à {area:1658}.",
	["Take the boat to {zone:1453} from {area:442}'s docks."] = "Prenez le bateau pour {zone:1453} depuis les quais de {area:442}.",
	["From {area:17203}, head through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "Depuis {area:17203}, passez les portes de la ville vers {zone:1429} et suivez la route vers l'ouest jusqu'à {zone:1436}.",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {item:7586} on one and lead it back to him."] = "Des ours chardon enragés parcourent les collines juste à l'est de {area:442}. Utilisez {item:7586} sur l'un d'eux et ramenez-le-lui.",
	["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {object:17183} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Au nord par les collines. {npc:3650} attend dans les ruines de {quest:954} ; des grells sauvages et des esprits malfaisants les remplissent, des satyres Deth'ryll le bord est. {object:17183} se dresse près de la route à l'ouest des ruines ; {quest:4723} se trouve sur le rivage en allant le voir.",
	["Follow the road south. Onu is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "Suivez la route vers le sud. Onu est l'ancien du Bosquet ; {npc:270269} et {npc:11218} dorment à côté de lui.",
	["Follow the coast north-east to the {area:443}. Mathystra Relics lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Suivez la côte au nord-est jusqu'à {area:443}. Des reliques de Mathystra gisent parmi les ruines ; des myrmidons, des ensorceleuses et des guerriers Écaille-tempête les tiennent, et des maîtresses des bêtes Écaille-tempête arpentent le rivage.",
	["Hearthstone on cooldown? Follow the coast road back south."] = "Pierre de foyer pas encore prête ? Suivez la route côtière vers le sud.",
	["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} et {npc:263113} se tiennent au sommet de la tour de guet, à quelques pas au nord-est de {npc:251368}.",
	["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Sautez du haut de la tour de guet et utilisez {spell:1259416} pour descendre en planant jusqu'à {npc:251361}, à l'ouest de la tour.",
	["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} monte la garde à l'est du bosquet. {npc:251143} et les convertis d'Al'Aketh se rassemblent juste au nord d'elle ; {object:460002} s'élève plus au nord : lancez-y votre capacité raciale {spell:1259705}.",
	["Cast {spell:1259705} at the {object:460002}"] = "Lancez {spell:1259705} sur {object:460002}",
	["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} campe au sud de la tanière d'Ursera. Les brutes d'Al'Aketh tiennent le camp au sud-ouest d'elle ; {npc:256935} se tient au milieu.\nAttention : {npc:256935} lance des horions ; éloignez-le des autres cultistes avant de combattre pour qu'ils ne le rejoignent pas.",
	["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/assis près du feu de camp de {npc:263664} jusqu'à obtenir {spell:1229451}",
	["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905} : Le camping pour les nuls vous demande de l'apprendre",
	["{npc:251918} along the way to Shen'dar turn-ins"] = "{npc:251918} en allant vers les rendus de Shen'dar",
	["\"Badwind\" Bennic, below ground"] = "« Malvent » Bennic, sous terre",
	["{npc:5148} in {zone:1455}; {area:16624} has no paladin trainer"] = "{npc:5148} à {zone:1455} ; {area:16624} n'a pas de maître des paladins",
	["Priest trainer"] = "Maître des prêtres",
	["Lariia in {zone:1438}; {area:16624} has no priest trainer"] = "Lariia à {zone:1438} ; {area:16624} n'a pas de maître des prêtres",
	["{npc:258098} in {zone:1455}; {area:16624} has no shaman trainer"] = "{npc:258098} à {zone:1455} ; {area:16624} n'a pas de maître des chamans",
	["Warlock trainer"] = "Maître des démonistes",
	["{item:2450} in {zone:1455}; {area:16624} has no warlock trainer"] = "{item:2450} à {zone:1455} ; {area:16624} n'a pas de maître des démonistes",
	["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} attend à l'entrée de {quest:92529}, au sud de Shen'dar. {spell:1254832} vous permet de marcher parmi les fidèles.",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar."] = "Partez au nord-ouest jusqu'aux nids d'hippogriffes sur les falaises ouest. {item:263493} se trouve autour des nids ; la matriarche patrouille parmi eux.\nLes voyants novices s'entraînent dans la clairière à l'ouest de Shen'dar.",
	["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "{npc:257006} et {npc:252448} se tiennent du côté ouest de {area:16638}, à côté de l'auberge ; {npc:252377} et {npc:252389} s'entraînent juste à l'ouest de {npc:257006}. Des rampants Chant-du-vent bordent le rivage plus à l'ouest, vers 51,70.",
	["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}, à côté de {npc:257006} : {npc:257196} tient le Rempart à {area:16629}",
	["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "{npc:252389}, à côté de {npc:257006} : le premier {item:15908}",
	["Innkeeper {npc:255940}, by the west gate"] = "L'aubergiste {npc:255940}, près de la porte ouest",
	["The {object:581822} lies by the path west of {area:16638}."] = "{object:581822} se trouve près du chemin à l'ouest de {area:16638}.",
	["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "{npc:254588}, parmi les crabes : apprivoisez-en un avec le premier {item:15908} de {npc:252389} tant que vous y êtes",
	["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Le camp de Fillion est au nord-ouest, et les matriarches criardes nichent juste à l'ouest du camp.",
	["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} reprend le premier {item:15908} et vous en donne deux autres, un par un : des coursiers du vent grincheux et des alphas vuldren parcourent les champs juste au nord d'elle. Apprivoisez chacun avec son bâtonnet et rapportez-lui le bâtonnet. {npc:254411}, à côté d'elle, enseigne {spell:5149}.",
	["{item:262668}: by the formations"] = "{item:262668} : près des formations",
	["{npc:252359}, the druid trainer, stands between the west gate and Valennia's house."] = "{npc:252359}, le maître des druides, se tient entre la porte ouest et la maison de Valennia.",
	["{npc:252359}: {quest:94006} (level 10)"] = "{npc:252359} : {quest:94006} (niveau 10)",
	["{npc:5148} in {zone:1455}; {area:16638} has no paladin trainer"] = "{npc:5148} à {zone:1455} ; {area:16638} n'a pas de maître des paladins",
	["{npc:5141} in {zone:1455}; {area:16638} has no priest trainer"] = "{npc:5141} à {zone:1455} ; {area:16638} n'a pas de maître des prêtres",
	["{npc:258098} in {zone:1455}; {area:16638} has no shaman trainer"] = "{npc:258098} à {zone:1455} ; {area:16638} n'a pas de maître des chamans",
	["{item:2450} in {zone:1455}; {area:16638} has no warlock trainer"] = "{item:2450} à {zone:1455} ; {area:16638} n'a pas de maître des démonistes",
	["Meet {npc:253844} at the gate"] = "Retrouvez {npc:253844} à la porte",
	["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853}, près des chutes au nord-est de {area:16638}, sur le chemin du nord : {spell:5487}",
	["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:254151}, {npc:258130} et {npc:258134} sont au nord-est de {npc:257944} ; {npc:253622} se tient à leur est. Haalien lâche aussi {quest:94490}. Pour {quest:94489}, entrez dans la tanière des Croc-de-nuit, soignez 7 druides blessés et trouvez {npc:258130}.",
	["{item:263993}: {npc:257196} holds it, west of the shrine's approach; defeat him for it on the way in"] = "{item:263993} : {npc:257196} le détient, à l'ouest de l'accès au sanctuaire ; battez-le pour l'obtenir en entrant",
	["{npc:253590}, in the sanctum; upstairs"] = "{npc:253590}, dans le sanctuaire ; à l'étage",
	["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "Lorthuna attend en haut de {area:16630}, à l'est du sanctuaire : prenez le portail vers {area:16630} dans le sanctuaire intérieur, à côté de Valennia, et traversez les hauteurs vers l'est jusqu'à {npc:252475}. Quand elle tombe, {object:617084} à côté d'elle vous ramène en ville.",
	["{npc:252475} sends you on to {area:279}. Once you have trained, take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475} vous envoie à {area:279}. Une fois entraîné, prenez le coupe-ciel à la tour du quai juste au sud de {area:16638} : il atterrit près du camp du Kirin Tor à l'ouest de {area:279}, à côté de {npc:259084} et du portail céleste.",
	["Leave {zone:2521} to {zone:1416}"] = "Quitter {zone:2521} pour {zone:1416}",
	["{npc:259084} stands beside the Skyborne Portal, where the skycutter lands by the Kirin Tor camp west of {area:279}. The portal takes you to {zone:1453}."] = "{npc:259084} se tient à côté du portail céleste, là où le coupe-ciel atterrit près du camp du Kirin Tor à l'ouest de {area:279}. Le portail vous emmène à {zone:1453}.",
	["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {area:40}."] = "Bolvar Fordragon se tient dans la salle du trône de {object:2117}, à l'extrémité nord de la ville. Puis sortez par la grande porte vers {area:40}.",
	["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, le maître des druides de {zone:1453}, vous enseigne {spell:18960}. L'accueil de {npc:11802} attend votre voyage par {spell:499} à la fin de {zone:1439}.",
} end)
